{"command": "cat > /tmp/dprobe.py <<'EOF'
import subprocess, sys, re
EXE='/workspace/executable'
def q(expr):
    r = subprocess.run([EXE, expr], capture_output=True, text=True)
    return r.stdout.replace('\x1b','').strip('\n'), r.stderr.replace('\x1b','').strip('\n'), r.returncode
def probe(lit):
    out,err,rc = q("year('%s'), month('%s'), day('%s'), dow('%s'), dayname('%s'), doy('%s')" % (lit,lit,lit,lit,lit,lit))
    if rc!=0 or not out:
        return None, err
    p = out.split('\t')
    return dict(zip(['year','month','day','dow','dayname','doy'],p)), err
lits = sys.argv[1:]
for l in lits:
    d, err = probe(l)
    if d: print("%-28r => %s" % (l, ' '.join("%s=%s"%(k,v) for k,v in d.items() if k!='dayname')))
    else: print("%-28r => ERR: %s" % (l, err))
EOF
