// Tokenizer for the fselect query language.

#[derive(Clone, Debug, PartialEq)]
pub struct Tok {
    pub text: String,
    /// true when there was no whitespace between this token and the previous one
    pub glued: bool,
}

fn is_space(c: char) -> bool {
    c.is_whitespace()
}

/// Characters that terminate a token and start a new operator-ish token
fn is_break(c: char) -> bool {
    matches!(c, ',' | '(' | ')' | '{' | '}' | '=' | '<' | '>' | '!' | '~' | '*')
}

pub fn tokenize(input: &str) -> Vec<Tok> {
    let mut out: Vec<Tok> = Vec::new();
    let chars: Vec<char> = input.chars().collect();
    let mut i = 0usize;
    let mut cur = String::new();
    let mut glue_start = false;
    let mut have_content = false;
    while i < chars.len() {
        let c = chars[i];
        if is_space(c) {
            if have_content {
                out.push(Tok { text: cur.clone(), glued: glue_start });
                cur.clear();
                have_content = false;
            }
            glue_start = false;
            i += 1;
            continue;
        }
        if c == '\'' || c == '"' || c == '`' {
            // find matching quote
            let mut j = i + 1;
            let mut s = String::new();
            while j < chars.len() && chars[j] != c {
                s.push(chars[j]);
                j += 1;
            }
            // if unterminated, consume to the end
            if j < chars.len() { j += 1; }
            if have_content {
                out.push(Tok { text: cur.clone(), glued: glue_start });
                cur.clear();
                have_content = false;
            }
            out.push(Tok { text: s, glued: glue_start });
            glue_start = false;
            i = j;
            continue;
        }
        if is_break(c) {
            if have_content {
                out.push(Tok { text: cur.clone(), glued: glue_start });
                cur.clear();
                have_content = false;
            }
            // munch multi char operators
            let op = munch_op(&chars[i..]);
            out.push(Tok { text: op.clone(), glued: false });
            i += op.chars().count();
            glue_start = false;
            continue;
        }
        if c == '+' || c == '-' || c == '/' || c == '%' {
            // keep inside token
            cur.push(c);
            have_content = true;
            i += 1;
            glue_start = false;
            continue;
        }
        if have_content && glue_start {
            glue_start = false;
        }
        cur.push(c);
        have_content = true;
        glue_start = false;
        i += 1;
    }
    if have_content {
        out.push(Tok { text: cur.clone(), glued: glue_start });
    }
    out
}

fn munch_op(ch: &[char]) -> String {
    if ch.is_empty() { return String::new(); }
    let a = ch[0];
    let n1 = if ch.len() > 1 { ch[1] } else { '\0' };
    let n2 = if ch.len() > 2 { ch[2] } else { '\0' };
    match a {
        '!' => {
            if n1 == '~' {
                if n2 == '=' { "!~=".into() } else { "!~".into() }
            } else if n1 == '=' {
                if n2 == '=' { "!==".into() }
                else if n2 == '~' { "!=~".into() }
                else { "!=".into() }
            } else { "!".into() }
        }
        '=' => {
            if n1 == '=' {
                if n2 == '=' { "===".into() } else { "==".into() }
            } else if n1 == '~' { "=~".into() } else { "=".into() }
        }
        '<' => {
            if n1 == '=' { "<=".into() } else if n1 == '>' { "<>".into() } else { "<".into() }
        }
        '>' => {
            if n1 == '=' { ">=".into() } else { ">".into() }
        }
        '~' => {
            if n1 == '=' { "~=".into() } else { "~".into() }
        }
        other => other.to_string(),
    }
}
RSEOF
