// Date/time helpers: parsing of the various date spellings understood by fselect
// plus formatting. Everything works on naive local timestamps.

#[derive(Clone, Copy, Debug)]
pub struct DateTime {
    pub year: i64,
    pub month: u32,
    pub day: u32,
    pub hour: u32,
    pub min: u32,
    pub sec: u32,
}

impl DateTime {
    pub fn from_epoch(ts: i64) -> DateTime {
        let (y, m, d) = civil_from_days(ts.div_euclid(86400));
        let s = ts.rem_euclid(86400);
        DateTime { year: y, month: m, day: d, hour: (s / 3600) as u32, min: ((s % 3600) / 60) as u32, sec: (s % 60) as u32 }
    }
    pub fn to_epoch(&self) -> i64 {
        let days = days_from_civil(self.year, self.month, self.day);
        days * 86400 + (self.hour as i64) * 3600 + (self.min as i64) * 60 + self.sec as i64
    }
    pub fn is_valid(&self) -> bool {
        if self.month < 1 || self.month > 12 { return false; }
        if self.day < 1 || self.day > days_in_month(self.year, self.month) { return false; }
        if self.hour > 23 || self.min > 59 || self.sec > 59 { return false; }
        true
    }
    pub fn dow(&self) -> u32 {
        // 1 = Sunday .. 7 = Saturday
        let days = days_from_civil(self.year, self.month, self.day);
        let w = (days + 4).rem_euclid(7); // 1970-01-01 was Thursday (4)
        ((w + 1) % 7 + 1) as u32
    }
    pub fn doy(&self) -> u32 {
        let mut d = 0;
        for m in 1..self.month {
            d += days_in_month(self.year, m);
        }
        d + self.day
    }
    pub fn format(&self) -> String {
        format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02}", self.year, self.month, self.day, self.hour, self.min, self.sec)
    }
    pub fn date_string(&self) -> String {
        format!("{:04}-{:02}-{:02}", self.year, self.month, self.day)
    }
    pub fn time_string(&self) -> String {
        format!("{:02}:{:02}:{:02}", self.hour, self.min, self.sec)
    }
}

pub fn days_in_month(year: i64, month: u32) -> u32 {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => { if is_leap(year) { 29 } else { 28 } }
        _ => 30,
    }
}

pub fn is_leap(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

// Howard Hinnant's civil_from_days / days_from_civil
pub fn days_from_civil(y: i64, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = ((m as i64) + 9) % 12;
    let doy = (153 * mp + 2) / 5 + (d as i64) - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

pub fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    (if m <= 2 { y + 1 } else { y }, m as u32, d as u32)
}

pub const MONTH_NAMES: [&str; 12] = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december"];
pub const DAY_NAMES: [&str; 7] = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"];

fn month_from_name(tok: &str) -> Option<u32> {
    let t = tok.to_lowercase();
    if t.chars().count() < 5 { return None; }
    for (i, m) in MONTH_NAMES.iter().enumerate() {
        if m.starts_with(&t) { return Some(i as u32 + 1); }
    }
    None
}

fn month_from_abbr(tok: &str) -> Option<u32> {
    let t = tok.to_lowercase();
    for (i, m) in MONTH_NAMES.iter().enumerate() {
        if m.starts_with(&t) { return Some(i as u32 + 1); }
    }
    None
}

fn day_from_name(tok: &str) -> Option<u32> {
    let t = tok.to_lowercase();
    if t.chars().count() < 5 { return None; }
    for (i, m) in DAY_NAMES.iter().enumerate() {
        if m.starts_with(&t) { return Some(i as u32 + 1); } // 1 = monday
    }
    None
}

#[derive(Clone, Copy, Debug)]
pub struct ParsedDate {
    pub dt: DateTime,
    /// 0 - exact, 1 - whole day, 2 - whole hour, 3 - whole minute
    pub precision: u32,
}

pub fn now_epoch() -> i64 {
    std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs() as i64).unwrap_or(0)
}

pub fn today() -> DateTime {
    DateTime::from_epoch(now_epoch())
}

/// Local timezone offset in seconds for a given epoch instant
pub fn tz_offset(ts: i64) -> i64 {
    #[repr(C)]
    struct Tm {
        tm_sec: i32, tm_min: i32, tm_hour: i32, tm_mday: i32,
        tm_mon: i32, tm_year: i32, tm_wday: i32, tm_yday: i32,
        tm_isdst: i32, tm_gmtoff: i64, tm_zone: *const i8,
    }
    extern "C" { fn localtime_r(t: *const i64, tm: *mut Tm) -> *mut Tm; }
    let mut tm = Tm { tm_sec: 0, tm_min: 0, tm_hour: 0, tm_mday: 0, tm_mon: 0, tm_year: 0, tm_wday: 0, tm_yday: 0, tm_isdst: 0, tm_gmtoff: 0, tm_zone: std::ptr::null() };
    let t = ts;
    let r = unsafe { localtime_r(&t as *const i64, &mut tm as *mut Tm) };
    if r.is_null() { 0 } else { tm.tm_gmtoff }
}

/// Convert a naive local date/time to an epoch (UTC) timestamp
pub fn local_to_epoch(dt: &DateTime) -> i64 {
    let utc = dt.to_epoch();
    utc - tz_offset(utc)
}

/// Convert an epoch (UTC) timestamp to a naive local date/time
pub fn epoch_to_local(ts: i64) -> DateTime {
    DateTime::from_epoch(ts + tz_offset(ts))
}

fn parse_time_part(s: &str) -> Option<(u32, u32, u32)> {
    let parts: Vec<&str> = s.split(':').collect();
    if parts.is_empty() || parts.len() > 3 { return None; }
    let h: u32 = parts[0].parse().ok()?;
    let m: u32 = if parts.len() > 1 { parts[1].parse().ok()? } else { 0 };
    let sec: u32 = if parts.len() > 2 { parts[2].parse().ok()? } else { 0 };
    Some((h, m, sec))
}

/// Parse an ISO-like date/time. Returns None when the string does not match.
fn parse_iso(s: &str) -> Option<ParsedDate> {
    let s = s.trim();
    if s.is_empty() { return None; }
    // date part: YYYY-MM-DD
    let (dpart, tpart) = if let Some(pos) = s.find(|c: char| c == ' ' || c == 'T') {
        (s[..pos].trim().to_string(), Some(s[pos + 1..].trim().to_string()))
    } else {
        (s.to_string(), None)
    };
    let dp: Vec<&str> = dpart.split('-').collect();
    if dp.len() != 3 { return None; }
    let y: i64 = dp[0].parse().ok()?;
    let mo: u32 = dp[1].parse().ok()?;
    let d: u32 = dp[2].parse().ok()?;
    if !(1..=12).contains(&mo) { return None; }
    if d < 1 || d > days_in_month(y, mo) { return None; }
    let mut dt = DateTime { year: y, month: mo, day: d, hour: 0, min: 0, sec: 0 };
    let mut precision = 1u32;
    if let Some(t) = tpart {
        let t = t.trim();
        if t.is_empty() { return Some(ParsedDate { dt, precision }); }
        // time part: HH | HH:MM | HH:MM:SS
        let tc: Vec<&str> = t.split(':').collect();
        if tc.len() == 0 || tc.len() > 3 { return None; }
        let h: u32 = tc[0].parse().ok()?;
        if h > 23 { return None; }
        if tc.len() == 1 { precision = 2; dt.hour = h; }
        else if tc.len() == 2 {
            let m: u32 = tc[1].parse().ok()?;
            if m > 59 { return None; }
            precision = 3; dt.hour = h; dt.min = m;
        } else {
            let m: u32 = tc[1].parse().ok()?;
            let sec: u32 = tc[2].parse().ok()?;
            if m > 59 || sec > 59 { return None; }
            precision = 0; dt.hour = h; dt.min = m; dt.sec = sec;
        }
    }
    Some(ParsedDate { dt, precision })
}

/// Unit multipliers for relative date arithmetic, in seconds
fn unit_seconds(u: &str) -> Option<i64> {
    let u = u.to_lowercase();
    if u.starts_with("sec") { Some(1) }
    else if u.starts_with("min") { Some(60) }
    else if u.starts_with("hour") { Some(3600) }
    else if u.starts_with("day") { Some(86400) }
    else if u.starts_with("week") { Some(604800) }
    else if u.starts_with("month") { Some(2629746) } // average month
    else if u.starts_with("year") { Some(31556952) }
    else { None }
}

fn add_months(dt: &DateTime, months: i64) -> DateTime {
    let total = (dt.year as i64) * 12 + (dt.month as i64 - 1) + months;
    let y = total.div_euclid(12);
    let m = total.rem_euclid(12) + 1;
    let mut d = dt.day;
    let max = days_in_month(y, m as u32);
    if d > max { d = max; }
    DateTime { year: y, month: m as u32, day: d, hour: dt.hour, min: dt.min, sec: dt.sec }
}

fn weekday_apply(dt: &DateTime, wd: u32, next: bool, this_is_ok: bool) -> DateTime {
    // wd: 1 = monday .. 7 = sunday
    let cur = dt.dow(); // 1 = sunday
    let cur_mon = ((cur + 5) % 7) + 1; // 1 = monday
    let mut diff = (wd as i64) - (cur_mon as i64);
    if diff < 0 { diff += 7; }
    if !next {
        if diff == 0 {
            if this_is_ok { return *dt; }
            diff = -7;
        }
    }
    let epoch = dt.to_epoch() + diff * 86400;
    DateTime::from_epoch(epoch)
}

/// Parse a date in the "human readable" style (chrono-english compatible subset)
pub fn parse_human(s: &str) -> Option<ParsedDate> {
    let s = s.trim();
    if s.is_empty() { return None; }
    let lc = s.to_lowercase();
    let now = DateTime::from_epoch(now_epoch());
    // relative plain: -N / +N / N
    if let Some(num) = lc.strip_prefix('-') {
        if let Ok(n) = num.trim().parse::<i64>() {
            let e = now_epoch() - n * 86400;
            return Some(ParsedDate { dt: DateTime::from_epoch(e), precision: 0 });
        }
        return None;
    }
    if let Some(num) = lc.strip_prefix('+') {
        if let Ok(n) = num.trim().parse::<i64>() {
            let e = now_epoch() + n * 86400;
            return Some(ParsedDate { dt: DateTime::from_epoch(e), precision: 0 });
        }
        return None;
    }
    // split into tokens by whitespace
    let toks: Vec<&str> = s.split_whitespace().collect();
    let mut dt = now;
    let mut precision = 0u32;
    let mut idx = 0usize;
    // "today" / "yesterday" / "tomorrow"
    if idx < toks.len() {
        let t = toks[idx].to_lowercase();
        if t == "today" { idx += 1; }
        else if t == "yesterday" { dt = DateTime::from_epoch(now_epoch() - 86400); idx += 1; }
        else if t == "tomorrow" { dt = DateTime::from_epoch(now_epoch() + 86400); idx += 1; }
    }
    let mut rel: Option<i64> = None;
    let mut rel_unit: Option<i64> = None;
    let mut ago = false;
    while idx < toks.len() {
        let t = toks[idx];
        let tl = t.to_lowercase();
        if tl == "ago" { ago = true; idx += 1; continue; }
        if rel_unit.is_some() { break; }
        // "N <unit>"
        if let Ok(n) = tl.parse::<i64>() {
            if idx + 1 < toks.len() {
                if let Some(u) = unit_seconds(toks[idx + 1]) {
                    rel = Some(n); rel_unit = Some(u); idx += 2; continue;
                }
            }
            // bare number with no unit -> fail (unless first)
            return None;
        }
        if let Some(u) = unit_seconds(tl) {
            // unit without number (e.g. "last month")
            break;
        }
        // weekday
        if let Some(wd) = day_from_name(&tl) {
            let next = true;
            dt = weekday_apply(&dt, wd, next, false);
            idx += 1;
            continue;
        }
        // "last <weekday>"
        if tl == "last" || tl == "next" {
            if idx + 1 < toks.len() {
                if let Some(wd) = day_from_name(&toks[idx + 1].to_lowercase()) {
                    dt = weekday_apply(&dt, wd, tl == "next", false);
                    idx += 2;
                    continue;
                }
            }
            return None;
        }
        // month name
        if let Some(mo) = month_from_abbr(&tl) {
            // "apr 1" / "1 apr" / "1 apr 2024"
            dt.month = mo;
            idx += 1;
            continue;
        }
        // numeric day
        if let Ok(d) = tl.parse::<u32>() {
            if d >= 1 && d <= 31 { dt.day = d; idx += 1; continue; }
            return None;
        }
        if let Ok(y) = tl.parse::<i64>() {
            dt.year = y; idx += 1; continue;
        }
        return None;
    }
    if rel.is_some() {
        let mut n = rel.unwrap() * rel_unit.unwrap();
        if ago { n = -n; }
        dt = DateTime::from_epoch(now_epoch() + n);
    }
    // optional time part remaining
    if idx < toks.len() {
        let t = toks[idx];
        let tl = t.to_lowercase();
        // "10am" / "10:30" / "10:30:00"
        if let Some(pos) = tl.find(|c: char| c.is_ascii_digit()) {
            let num_part: String = tl[..pos].to_string();
            let rest: String = tl[pos..].to_string();
            let mut ampm = None;
            let mut time_str = rest.clone();
            if rest.ends_with("am") { ampm = Some(false); time_str = rest[..rest.len() - 2].to_string(); }
            else if rest.ends_with("pm") { ampm = Some(true); time_str = rest[..rest.len() - 2].to_string(); }
            let mut done = false;
            if !time_str.is_empty() {
                let parts: Vec<&str> = time_str.split(':').collect();
                if parts.len() <= 3 && !parts[0].is_empty() {
                    let mut h: i64 = parts[0].parse().ok()?;
                    let mut m: i64 = 0;
                    let mut sec: i64 = 0;
                    if parts.len() > 1 { m = parts[1].parse().ok()?; }
                    if parts.len() > 2 { sec = parts[2].parse().ok()?; }
                    if let Some(p) = ampm {
                        if h < 12 { h += 12; }
                        if p == false && h == 12 { h = 0; }
                    }
                    if h >= 0 && h <= 23 && m >= 0 && m <= 59 && sec >= 0 && sec <= 59 {
                        dt.hour = h as u32; dt.min = m as u32; dt.sec = sec as u32;
                        precision = 0;
                        done = true;
                    }
                }
            }
            if !done { return None; }
            idx += 1;
        } else {
            return None;
        }
    }
    if idx != toks.len() && rel.is_none() {
        return None;
    }
    if !dt.is_valid() { return None; }
    Some(ParsedDate { dt, precision })
}

/// Parse the DD/MM (or MM/DD with us_dates) style date
pub fn parse_slash(s: &str, us: bool) -> Option<ParsedDate> {
    let t = s.trim();
    let parts: Vec<&str> = t.split('/').collect();
    if parts.len() != 2 && parts.len() != 3 { return None; }
    let today = today();
    let mut precision = 1u32;
    if parts.len() == 3 {
        let y: i64 = parts[2].parse().ok()?;
        if parts[2].chars().count() == 4 {
            precision = 1;
            let (a, b): (u32, u32) = (parts[0].parse().ok()?, parts[1].parse().ok()?);
            let (mo, d) = if us { (a, b) } else { (b, a) };
            if !(1..=12).contains(&mo) { return None; }
            if d < 1 || d > days_in_month(y, mo) { return None; }
            return Some(ParsedDate { dt: DateTime { year: y, month: mo, day: d, hour: 0, min: 0, sec: 0 }, precision });
        }
        return None;
    }
    let a: u32 = parts[0].parse().ok()?;
    let b: u32 = parts[1].parse().ok()?;
    let (mo, d) = if us { (a, b) } else { (b, a) };
    if !(1..=12).contains(&mo) { return None; }
    if d < 1 || d > days_in_month(today.year, mo) { return None; }
    Some(ParsedDate { dt: DateTime { year: today.year, month: mo, day: d, hour: 0, min: 0, sec: 0 }, precision })
}

/// Master entry point: try to parse the given text as a date
pub fn parse_date(s: &str, us: bool) -> Option<ParsedDate> {
    if let Some(p) = parse_iso(s) { return Some(p); }
    if let Some(p) = parse_slash(s, us) { return Some(p); }
    parse_human(s)
}
