    Class { neg: bool, items: Vec<ClassItem> },
    Start,
    End,
    Group(Box<Node>),
    Concat(Vec<Node>),
    Alt(Vec<Node>),
    Repeat { node: Box<Node>, min: u32, max: u32, greedy: bool },
}

pub struct Regex {
    root: Node,
    icase: bool,
}

fn is_word(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

impl Regex {
    pub fn compile(pat: &str, icase: bool) -> Result<Regex, String> {
        let chars: Vec<char> = pat.chars().collect();
        let mut p = Parser { ch: chars, i: 0, icase };
        let root = p.parse_alt()?;
        if p.i != p.ch.len() {
            return Err(format!("unexpected character at position {}", p.i));
        }
        Ok(Regex { root, icase })
    }

    pub fn is_match(&self, text: &str) -> bool {
        let s: Vec<char> = if self.icase { text.to_lowercase().chars().collect() } else { text.chars().collect() };
        let root = if self.icase { lower_node(&self.root) } else { self.root.clone() };
        let mut res = false;
        let mut k = |_p: usize| -> bool { res = true; true };
        m(&root, &s, 0, &mut k);
        res
    }
}

fn lower_node(n: &Node) -> Node {
    match n {
        Node::Char(c) => Node::Char(c.to_lowercase().next().unwrap_or(*c)),
        Node::Group(b) => Node::Group(Box::new(lower_node(b))),
        Node::Concat(v) => Node::Concat(v.iter().map(lower_node).collect()),
        Node::Alt(v) => Node::Alt(v.iter().map(lower_node).collect()),
        Node::Repeat { node, min, max, greedy } => Node::Repeat { node: Box::new(lower_node(node)), min: *min, max: *max, greedy: *greedy },
        other => other.clone(),
    }
}

fn class_matches(items: &[ClassItem], neg: bool, c: char) -> bool {
    let mut hit = false;
    for it in items {
        let m = match it {
            ClassItem::Ch(x) => *x == c,
            ClassItem::Range(a, b) => c >= *a && c <= *b,
            ClassItem::Digit(p) => c.is_ascii_digit() == *p,
            ClassItem::Word(p) => is_word(c) == *p,
            ClassItem::Space(p) => c.is_whitespace() == *p,
        };
        if m { hit = true; break; }
    }
    hit != neg
}

// backtracking matcher: returns true when a match was found that lets the continuation succeed
fn m(node: &Node, s: &[char], pos: usize, k: &mut dyn FnMut(usize) -> bool) -> bool {
    match node {
        Node::Empty => k(pos),
        Node::Start => { if pos == 0 { k(pos) } else { false } }
        Node::End => { if pos == s.len() { k(pos) } else { false } }
        Node::Char(c) => {
            if pos < s.len() && s[pos] == *c { k(pos + 1) } else { false }
        }
        Node::Any => {
            if pos < s.len() && s[pos] != '\n' { k(pos + 1) } else { false }
        }
        Node::Class { neg, items } => {
            if pos < s.len() && class_matches(items, *neg, s[pos]) { k(pos + 1) } else { false }
