        Node::Group(inner) => m(inner, s, pos, k),
        Node::Concat(v) => m_seq(v, 0, s, pos, k),
        Node::Alt(v) => {
            for a in v {
                if m(a, s, pos, k) { return true; }
            }
            false
        }
        Node::Repeat { node, min, max, greedy } => m_rep(node, 0, *min, *max, *greedy, s, pos, k),
    }
}

fn m_seq(v: &[Node], i: usize, s: &[char], pos: usize, k: &mut dyn FnMut(usize) -> bool) -> bool {
    if i >= v.len() { return k(pos); }
    let rest = &v[i + 1..];
    let mut kk = |p: usize| -> bool {
        let mut cont = |p2: usize| -> bool { m_seq(rest, 0, s, p2, k) };
        m(&v[i], s, p, &mut cont)
    };
    m(&v[i], s, pos, &mut kk)
