fn m_rep(node: &Node, count: u32, min: u32, max: u32, greedy: bool, s: &[char], pos: usize, k: &mut dyn FnMut(usize) -> bool) -> bool {
    if greedy {
        if count < max {
            let mut kk = |p: usize| -> bool {
