struct Parser {
    ch: Vec<char>,
    i: usize,
    icase: bool,
}

impl Parser {
    fn peek(&self) -> Option<char> { self.ch.get(self.i).copied() }
    fn next(&mut self) -> Option<char> { let c = self.peek(); if c.is_some() { self.i += 1; } c }

    fn parse_alt(&mut self) -> Result<Node, String> {
        let mut alts = vec![self.parse_concat()?];
        while self.peek() == Some('|') {
            self.next();
            alts.push(self.parse_concat()?);
        }
        if alts.len() == 1 { Ok(alts.pop().unwrap()) } else { Ok(Node::Alt(alts)) }
    }

    fn parse_concat(&mut self) -> Result<Node, String> {
        let mut items = Vec::new();
        loop {
            match self.peek() {
                None | Some('|') | Some(')') => break,
                _ => {}
            }
            let atom = self.parse_atom()?;
            let atom = self.parse_repeat(atom)?;
            items.push(atom);
        }
        if items.is_empty() { Ok(Node::Empty) } else if items.len() == 1 { Ok(items.pop().unwrap()) } else { Ok(Node::Concat(items)) }
    }

    fn parse_repeat(&mut self, atom: Node) -> Result<Node, String> {
        let mut node = atom;
        loop {
            let (min, max) = match self.peek() {
                Some('*') => { self.next(); (0u32, u32::MAX) }
                Some('+') => { self.next(); (1u32, u32::MAX) }
                Some('?') => { self.next(); (0u32, 1u32) }
                Some('{') => {
                    // try to parse {n}, {n,}, {n,m}
                    let save = self.i;
                    self.next();
                    let mut a = String::new();
                    while let Some(c) = self.peek() {
                        if c.is_ascii_digit() { a.push(c); self.next(); } else { break; }
                    }
                    if a.is_empty() { self.i = save; break; }
                    let mut comma = false;
                    if self.peek() == Some(',') { comma = true; self.next(); }
                    let mut b = String::new();
                    while let Some(c) = self.peek() {
                        if c.is_ascii_digit() { b.push(c); self.next(); } else { break; }
                    }
                    if self.peek() != Some('}') { self.i = save; break; }
                    self.next();
                    let an: u32 = a.parse().map_err(|_| "invalid repetition".to_string())?;
                    let bn: u32 = if !comma { an } else if b.is_empty() { u32::MAX } else { b.parse().map_err(|_| "invalid repetition".to_string())? };
                    (an, bn)
                }
                _ => break,
            };
            let greedy = if self.peek() == Some('?') { self.next(); false } else { true };
            node = Node::Repeat { node: Box::new(node), min, max, greedy };
        }
        Ok(node)
    }

    fn parse_atom(&mut self) -> Result<Node, String> {
        let c = self.next().ok_or("unexpected end of expression")?;
        match c {
            '.' => Ok(Node::Any),
            '^' => Ok(Node::Start),
            '$' => Ok(Node::End),
            '(' => {
                // (?:...) or (?i) etc
                if self.peek() == Some('?') {
                    self.next();
                    match self.peek() {
                        Some(':') => { self.next(); }
                        Some('i') => { self.next(); if self.peek() == Some(')') { self.next(); return Ok(Node::Empty); } return Err("unsupported group flags".into()); }
                        _ => return Err("unsupported group flags".into()),
                    }
                }
                let inner = self.parse_alt()?;
                if self.next() != Some(')') { return Err("missing closing parenthesis".into()); }
                Ok(Node::Group(Box::new(inner)))
            }
            '[' => self.parse_class(),
            '\\' => {
                let e = self.next().ok_or("unexpected end of expression")?;
                Ok(match e {
                    'd' => Node::Class { neg: false, items: vec![ClassItem::Digit(false)] },
                    'D' => Node::Class { neg: false, items: vec![ClassItem::Digit(true)] },
                    'w' => Node::Class { neg: false, items: vec![ClassItem::Word(false)] },
                    'W' => Node::Class { neg: false, items: vec![ClassItem::Word(true)] },
                    's' => Node::Class { neg: false, items: vec![ClassItem::Space(false)] },
                    'S' => Node::Class { neg: false, items: vec![ClassItem::Space(true)] },
                    'n' => Node::Char('\n'),
                    'r' => Node::Char('\r'),
                    't' => Node::Char('\t'),
                    '0' => Node::Char('\0'),
                    other => Node::Char(other),
                })
            }
            '*' | '+' | '?' => Err("repetition operator missing expression".into()),
            ')' => Err("unopened group".into()),
            other => Ok(Node::Char(if self.icase { other.to_lowercase().next().unwrap_or(other) } else { other })),
        }
    }

    fn parse_class(&mut self) -> Result<Node, String> {
        let mut neg = false;
        if self.peek() == Some('^') { neg = true; self.next(); }
        let mut items: Vec<ClassItem> = Vec::new();
        let mut first = true;
        loop {
            let c = match self.peek() { Some(c) => c, None => return Err("missing closing bracket".into()) };
            if c == ']' && !first {
                self.next();
                return Ok(Node::Class { neg, items });
            }
            first = false;
            self.next();
            let lit = if c == '\\' {
                let e = self.next().ok_or("unexpected end of expression")?;
                match e {
                    'd' => { items.push(ClassItem::Digit(false)); continue; }
                    'D' => { items.push(ClassItem::Digit(true)); continue; }
                    'w' => { items.push(ClassItem::Word(false)); continue; }
                    'W' => { items.push(ClassItem::Word(true)); continue; }
                    's' => { items.push(ClassItem::Space(false)); continue; }
                    'S' => { items.push(ClassItem::Space(true)); continue; }
                    'n' => '\n', 'r' => '\r', 't' => '\t',
                    other => other,
                }
            } else { c };
            // possible range
            if self.peek() == Some('-') {
                if self.ch.get(self.i + 1).copied() != Some(']') {
                    self.next();
                    let h = self.next().ok_or("unexpected end of expression")?;
                    let lo = lit;
                    let hi = h;
                    items.push(ClassItem::Range(if self.icase { lo.to_lowercase().next().unwrap_or(lo) } else { lo }, if self.icase { hi.to_lowercase().next().unwrap_or(hi) } else { hi }));
                    continue;
                }
            }
            items.push(ClassItem::Ch(if self.icase { lit.to_lowercase().next().unwrap_or(lit) } else { lit }));
        }
    }
}
