// Value types used during evaluation
use crate::dates::{DateTime, epoch_to_local, local_to_epoch, parse_date};

#[derive(Clone, Debug)]
pub enum Val {
    Str(String),
    Num(f64),
    Bool(bool),
    Date(i64),
    Null,
}

impl Val {
    pub fn is_null(&self) -> bool {
        match self {
            Val::Null => true,
            Val::Str(s) => s.is_empty(),
            _ => false,
        }
    }

    pub fn to_str(&self) -> String {
        match self {
            Val::Str(s) => s.clone(),
            Val::Num(v) => format_num(*v),
            Val::Bool(b) => if *b { "true".into() } else { "false".into() },
            Val::Date(ts) => epoch_to_local(*ts).format(),
            Val::Null => String::new(),
        }
    }

    pub fn num(&self) -> f64 {
        match self {
            Val::Num(v) => *v,
            Val::Str(s) => s.trim().parse::<f64>().unwrap_or(0.0),
            Val::Bool(b) => if *b { 1.0 } else { 0.0 },
            Val::Date(ts) => *ts as f64,
            Val::Null => 0.0,
        }
    }

    pub fn boolean(&self) -> bool {
        match self {
            Val::Bool(b) => *b,
            Val::Num(v) => *v != 0.0,
            Val::Str(s) => {
                let l = s.to_lowercase();
                l == "true" || l == "yes" || l == "1" || l == "on"
            }
            Val::Date(_) => true,
            Val::Null => false,
        }
    }

    /// Text without date formatting (used by functions that operate on strings)
    pub fn raw_str(&self) -> String {
        match self {
            Val::Str(s) => s.clone(),
            Val::Date(ts) => {
                let d = epoch_to_local(*ts);
                d.format()
            }
            Val::Null => String::new(),
            other => other.to_str(),
        }
    }

    pub fn as_date(&self) -> Option<i64> {
        match self {
            Val::Date(ts) => Some(*ts),
            Val::Null => None,
            _ => None,
        }
    }
}

pub fn format_num(v: f64) -> String {
    if v == v.trunc() && v.abs() < 1e15 {
        format!("{}", v as i64)
    } else {
        format!("{}", v)
    }
}

/// Date related info bundled with a value for interval comparisons
#[derive(Clone, Debug)]
pub struct DateVal {
    pub ts: i64,
}

pub fn parse_date_val(text: &str, us_dates: bool) -> Option<DateVal> {
    let p = parse_date(text, us_dates)?;
    let mut dt = p.dt;
    if p.precision == 1 {
        dt.hour = 0; dt.min = 0; dt.sec = 0;
    } else if p.precision == 2 {
        dt.min = 0; dt.sec = 0;
    } else if p.precision == 3 {
        dt.sec = 0;
    }
    let ts = local_to_epoch(&dt);
    let mut end = ts;
    match p.precision {
        1 => { end = ts + 86399; }
        2 => { end = ts + 3599; }
        3 => { end = ts + 59; }
        _ => {}
    }
    Some(DateVal { ts })
}

/// Parse a date literal and return both bounds (used for inexact comparisons)
pub fn parse_date_range(text: &str, us_dates: bool) -> Option<(i64, i64)> {
    let p = parse_date(text, us_dates)?;
    let dt = p.dt;
    let start = local_to_epoch(&dt);
    let end = match p.precision {
        1 => start + 86399,
        2 => start + 3599,
        3 => start + 59,
        _ => start,
    };
    Some((start, end))
}

pub fn date_from_parts(d: &DateTime) -> i64 {
    local_to_epoch(d)
}
