    pub dfs: bool,
    pub regexp: bool,
    pub alias: Option<String>,
}

#[derive(Clone, Debug)]
pub struct Root {
    pub path: String,
    pub opts: RootOpts,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Format { Tabs, Lines, List, Csv, Json, Html }

#[derive(Clone, Debug)]
pub struct Field {
    pub expr: Expr,
    pub display: String,
}

#[derive(Clone, Debug)]
pub struct OrderKey {
    pub expr: Expr,
    pub desc: bool,
    pub display: String,
}

#[derive(Clone, Debug)]
pub struct Query {
    pub fields: Vec<Field>,
    pub roots: Vec<Root>,
    pub cond: Option<Cond>,
    pub group_by: Vec<Expr>,
    pub order_by: Vec<OrderKey>,
    pub limit: u64,
    pub offset: u64,
    pub format: Format,
    pub has_agg: bool,
}

pub struct ParseErr(pub String);

pub fn parse_text(text: &str) -> Result<Query, ParseErr> {
    let toks = tokenize(text);
    parse(&toks)
}

struct P {
    t: Vec<Tok>,
    i: usize,
}

const SECTION_KEYWORDS: [&str; 8] = ["from", "where", "group", "order", "limit", "offset", "into", "select"];

impl P {
    fn peek(&self) -> Option<&Tok> { self.t.get(self.i) }
    fn peek_text(&self) -> Option<&str> { self.t.get(self.i).map(|t| t.text.as_str()) }
    fn peek_n(&self, n: usize) -> Option<&Tok> { self.t.get(self.i + n) }
    fn cur(&self) -> Option<String> { self.peek().map(|t| t.text.clone()) }
    fn next(&mut self) -> Option<String> {
        let r = self.t.get(self.i).map(|t| t.text.clone());
        if r.is_some() { self.i += 1; }
        r
    }
    fn eat(&mut self, s: &str) -> bool {
        if self.peek_text() == Some(s) { self.i += 1; true } else { false }
    }
    fn eat_ci(&mut self, s: &str) -> bool {
        if let Some(t) = self.peek() { if t.text.eq_ignore_ascii_case(s) { self.i += 1; return true; } }
        false
    }
    fn is_section_kw(&self) -> bool {
        match self.peek_text() {
            Some(t) => SECTION_KEYWORDS.contains(&t.to_lowercase().as_str()),
            None => false,
        }
    }
    fn is_glued(&self) -> bool { self.t.get(self.i).map(|t| t.glued).unwrap_or(false) }
    fn is_glued_n(&self, n: usize) -> bool { self.t.get(self.i + n).map(|t| t.glued).unwrap_or(false) }
}

fn cmp_op(tok: &str) -> Option<CmpOp> {
    let t = tok.to_lowercase();
    Some(match t.as_str() {
        "=" | "==" | "eq" => CmpOp::Eq,
        "===" | "eeq" => CmpOp::EEq,
        "!=" | "<>" | "ne" => CmpOp::Ne,
        "!==" | "ene" => CmpOp::ENe,
        "<" | "lt" => CmpOp::Lt,
        "<=" | "lte" | "le" => CmpOp::Le,
        ">" | "gt" => CmpOp::Gt,
        ">=" | "gte" | "ge" => CmpOp::Ge,
        "=~" | "~=" | "regexp" | "rx" => CmpOp::Rx,
        "!=" | _ if t == "!=~" || t == "!~=" || t == "notrx" => CmpOp::NotRx,
        "like" => CmpOp::Like,
        "notlike" => CmpOp::NotLike,
        "between" => CmpOp::Between,
        "in" => CmpOp::In,
        "exists" => CmpOp::Exists,
        _ => return None,
    })
}

fn is_arith_op(tok: &str) -> Option<char> {
    let l = tok.to_lowercase();
    match tok {
        "+" => Some('+'),
        "-" => Some('-'),
        "*" => Some('*'),
        "/" => Some('/'),
        "%" => Some('%'),
        _ => match l.as_str() {
            "plus" => Some('+'),
            "minus" => Some('-'),
            "mul" => Some('*'),
            "div" => Some('/'),
            "mod" => Some('%'),
            _ => None,
        },
    }
}

fn camel(s: &str) -> String {
    s.split('_').map(|p| {
        let mut cs = p.chars();
        match cs.next() {
            Some(c) => c.to_uppercase().collect::<String>() + &cs.collect::<String>(),
            None => String::new(),
        }
    }).collect()
}

pub fn display_name(e: &Expr) -> String {
    match e {
        Expr::Col { name } => camel(&columns::canonical(name)),
        Expr::Str(s) => s.clone(),
        Expr::Num(v) => crate::val::format_num(*v),
        Expr::Bool(b) => if *b { "true".into() } else { "false".into() },
        Expr::Func { name, args } => {
            if functions::is_aggregate(name) {
                format!("{}({})", functions::aggregate_display(name), args.iter().map(display_lower).collect::<Vec<_>>().join(", "))
            } else {
                format!("{}({})", camel(&functions::canonical(name)), args.iter().map(display_name).collect::<Vec<_>>().join(", "))
            }
        }
        Expr::Arith { op, l, r } => format!("{} {} {}", display_name(l), crate::functions::arith_name(*op), display_name(r)),
        Expr::Alias { alias, name } => format!("{}.{}", alias, name),
    }
}

fn display_lower(e: &Expr) -> String {
    display_name(e).to_lowercase()
}

fn display_cmp(op: CmpOp) -> &'static str {
    match op {
        CmpOp::Eq => "Eq", CmpOp::Ne => "Ne", CmpOp::Lt => "Lt", CmpOp::Le => "Lte",
        CmpOp::Gt => "Gt", CmpOp::Ge => "Gte", CmpOp::Rx => "Rx", CmpOp::NotRx => "NotRx",
        CmpOp::Like => "Like", CmpOp::NotLike => "NotLike", CmpOp::EEq => "Eeq",
        CmpOp::ENe => "Ene", CmpOp::Between => "Between", CmpOp::In => "In",
        CmpOp::NotIn => "NotIn", CmpOp::Exists => "Exists", CmpOp::NotExists => "NotExists",
    }
}

pub fn parse(toks: &[Tok]) -> Result<Query, ParseErr> {
    let mut p = P { t: toks.to_vec(), i: 0 };
    // optional leading select
    let _ = p.eat_ci("select");
    let mut fields: Vec<Field> = Vec::new();
    // parse fields
    if p.peek().is_none() {
        return Ok(Query {
            fields, roots: vec![], cond: None, group_by: vec![], order_by: vec![],
            limit: 0, offset: 0, format: Format::Tabs, has_agg: false,
        });
    }
    loop {
        if p.is_section_kw() { break; }
        let start = p.i;
        match parse_field(&mut p) {
            Ok(Some(f)) => fields.push(f),
            Ok(None) => { p.i = start; break; }
            Err(e) => return Err(e),
        }
        // after a field: comma -> next field, or section keyword -> stop, else stop
        if p.eat(",") {
            // if the next token looks like a leading division expression, stop (leave tokens)
            if let Some(t) = p.peek_text() {
                if t.starts_with('/') { p.i -= 1; break; }
            }
            continue;
        }
        break;
    }
    let mut roots: Vec<Root> = Vec::new();
    let mut cond: Option<Cond> = None;
    let mut group_by: Vec<Expr> = Vec::new();
    let mut order_by: Vec<OrderKey> = Vec::new();
    let mut limit = 0u64;
    let mut offset = 0u64;
    let mut format = Format::Tabs;
    let mut state = 0u8;
    loop {
        match p.peek_text() {
            Some(t) if t.eq_ignore_ascii_case("from") => {
                if state != 0 || !roots.is_empty() { break; }
                p.i += 1;
                roots = parse_roots(&mut p)?;
                state = 0;
            }
            Some(t) if t.eq_ignore_ascii_case("where") => {
                if state > 1 { break; }
                p.i += 1;
                cond = Some(parse_cond(&mut p)?);
                state = 2;
            }
            Some(t) if t.eq_ignore_ascii_case("group") => {
                if state > 2 { break; }
                p.i += 1;
                if !p.eat_ci("by") { return Err(ParseErr("Expecting 'by' after group".into())); }
                group_by = parse_expr_list(&mut p)?;
                state = 3;
            }
            Some(t) if t.eq_ignore_ascii_case("order") => {
                if state > 3 { break; }
                p.i += 1;
                if !p.eat_ci("by") { return Err(ParseErr("Expecting 'by' after order".into())); }
                order_by = parse_order(&mut p)?;
                state = 4;
            }
            Some(t) if t.eq_ignore_ascii_case("limit") => {
                if state > 4 { break; }
                p.i += 1;
                match p.next() {
                    Some(v) => match v.parse::<u64>() { Ok(n) => limit = n, Err(_) => return Err(ParseErr("Expecting number after limit".into())) },
                    None => return Err(ParseErr("Expecting number after limit".into())),
                }
                state = 5;
            }
            Some(t) if t.eq_ignore_ascii_case("offset") => {
                if state > 5 { break; }
                p.i += 1;
                match p.next() {
                    Some(v) => match v.parse::<u64>() { Ok(n) => offset = n, Err(_) => return Err(ParseErr("Expecting number after offset".into())) },
                    None => return Err(ParseErr("Expecting number after offset".into())),
                }
                state = 6;
            }
            Some(t) if t.eq_ignore_ascii_case("into") => {
                if state > 6 { break; }
                p.i += 1;
                match p.next() {
                    Some(v) => {
                        format = match v.to_lowercase().as_str() {
                            "tabs" => Format::Tabs,
                            "lines" => Format::Lines,
                            "list" => Format::List,
                            "csv" => Format::Csv,
                            "json" => Format::Json,
                            "html" => Format::Html,
                            _ => return Err(ParseErr("Unknown output format".into())),
                        };
                    }
                    None => return Err(ParseErr("Unknown output format".into())),
                }
                state = 7;
            }
            _ => break,
        }
    }
    if p.i != p.t.len() {
        return Err(ParseErr("could not parse tokens at the end of the query".into()));
    }
    let has_agg = fields.iter().any(|f| contains_agg(&f.expr))
        || group_by.is_empty() && fields.iter().any(|f| contains_agg(&f.expr))
        || contains_agg_expr_list(&group_by);
    let has_agg = fields.iter().any(|f| contains_agg(&f.expr)) || contains_agg_expr_list(&group_by);
    Ok(Query { fields, roots, cond, group_by, order_by, limit, offset, format, has_agg })
}

fn contains_agg(e: &Expr) -> bool {
    match e {
        Expr::Func { name, args } => functions::is_aggregate(name) || args.iter().any(contains_agg),
        Expr::Arith { l, r, .. } => contains_agg(l) || contains_agg(r),
        _ => false,
    }
}

fn contains_agg_expr_list(v: &[Expr]) -> bool {
    v.iter().any(contains_agg)
}

fn parse_field(p: &mut P) -> Result<Option<Field>, ParseErr> {
    let start = p.i;
    let e = match parse_expr(p)? {
        Some(e) => e,
        None => { p.i = start; return Ok(None); }
    };
    if p.i == start { return Ok(None); }
    let mut text = Vec::new();
    for t in &p.t[start..p.i] {
        text.push(t.text.clone());
    }
    // rebuild display text
    let display = render_tokens(&p.t[start..p.i]);
    Ok(Some(Field { expr: e, display }))
}

/// Rebuild the human readable column name from a token slice
pub fn render_tokens(toks: &[Tok]) -> String {
    let mut out = String::new();
    let mut prev_special = false;
    for (i, t) in toks.iter().enumerate() {
        let s = &t.text;
        let is_open = s == "(" || s == "{";
        let is_close = s == ")" || s == "}";
        let is_comma = s == ",";
        if i > 0 && !is_open && !prev_special {
            out.push(' ');
        }
        if is_comma {
            out.push_str(",");
        } else {
            out.push_str(s);
        }
        prev_special = is_open || is_comma;
    }
    // trailing close without space is handled since prev_special false -> space added; fix:
    let mut fixed = String::new();
    for (i, ch) in out.chars().enumerate() {
        if ch == ' ' && i + 1 < out.len() {
            let nxt = out.chars().nth(i + 1).unwrap();
            if nxt == ')' || nxt == '}' { continue; }
        }
        if ch == ' ' && i > 0 {
            let prev = out.chars().nth(i - 1).unwrap();
            if prev == '(' || prev == '{' { continue; }
        }
        fixed.push(ch);
    }
    fixed
}

fn parse_expr_list(p: &mut P) -> Result<Vec<Expr>, ParseErr> {
    let mut out = Vec::new();
    loop {
        if p.is_section_kw() { break; }
        let start = p.i;
        match parse_expr(p)? {
            Some(e) => out.push(e),
            None => { p.i = start; break; }
        }
        if p.i == start { break; }
        if !p.eat(",") { break; }
    }
    Ok(out)
}

fn parse_order(p: &mut P) -> Result<Vec<OrderKey>, ParseErr> {
    let mut out = Vec::new();
    loop {
        if p.is_section_kw() { break; }
        let start = p.i;
        let e = match parse_expr(p)? {
            Some(e) => e,
            None => { p.i = start; break; }
        };
        if p.i == start { break; }
        let mut desc = false;
        if p.eat_ci("desc") { desc = true; }
        else { let _ = p.eat_ci("asc"); }
        let display = render_tokens(&p.t[start..p.i]);
        out.push(OrderKey { expr: e, desc, display });
        if !p.eat(",") { break; }
    }
    Ok(out)
}

/// Parse a single expression (operand possibly followed by arithmetic operators)
fn parse_expr(p: &mut P) -> Result<Option<Expr>, ParseErr> {
    let start = p.i;
    let first = match parse_operand(p)? {
        Some(e) => e,
        None => { p.i = start; return Ok(None); }
    };
    let mut left = first;
    loop {
        let op = match p.peek_text() { Some(t) => is_arith_op(t), None => None };
        match op {
            Some(o) => {
                p.i += 1;
                let r = match parse_operand(p)? {
                    Some(e) => e,
                    None => {
                        // operator without right operand: treat whole thing as literal
                        p.i = start;
                        return Ok(None);
                    }
                };
                left = Expr::Arith { op: o, l: Box::new(left), r: Box::new(r) };
            }
            None => break,
        }
    }
    Ok(Some(left))
}

fn split_token_operators(tok: &str) -> Vec<String> {
    // split a single token into operator/operand chunks for + - * / %
    let mut out = Vec::new();
    let mut cur = String::new();
    for c in tok.chars() {
        if matches!(c, '+' | '-' | '*' | '/' | '%') {
            if !cur.is_empty() { out.push(cur.clone()); cur.clear(); }
            out.push(c.to_string());
        } else {
            cur.push(c);
        }
    }
    if !cur.is_empty() { out.push(cur.clone()); }
    out
}

fn parse_operand(p: &mut P) -> Result<Option<Expr>, ParseErr> {
    let start = p.i;
    let tok = match p.peek() { Some(t) => t.text.clone(), None => return Ok(None) };
    let glued = p.is_glued();
    // parenthesised / braced group
    if tok == "(" || tok == "{" {
        p.i += 1;
        let close = if tok == "(" { ")" } else { "}" };
        let e = parse_expr(p)?;
        if e.is_none() { return Err(ParseErr("Error parsing expression, expecting string".into())); }
        if !p.eat(close) { return Err(ParseErr("Error parsing expression, expecting string".into())); }
        return Ok(e);
    }
    if tok == ")" || tok == "}" {
        return Ok(None);
    }
    // function call?
    let low = tok.to_lowercase();
    if functions::is_function(&low) {
        let name = low.clone();
        let mut args = Vec::new();
        let had_paren = p.peek_n(1).map(|t| t.text == "(").unwrap_or(false);
        if had_paren {
            p.i += 2;
            loop {
                if p.peek_text() == Some(")") { p.i += 1; break; }
                let start = p.i;
                let e = parse_expr(p)?;
                match e {
                    Some(e) => args.push(e),
                    None => { p.i = start; return Err(ParseErr("Error parsing expression, expecting string".into())); }
                }
                if !p.eat(",") {
                    if p.peek_text() == Some(")") { p.i += 1; }
                    break;
                }
            }
        } else if !functions::requires_parens(&name) {
            // aggregates without parentheses consume following args
            loop {
                if p.is_section_kw() { break; }
                if p.peek_text().map(|t| t == "," || t == ")" || t == "}").unwrap_or(true) { break; }
                let e = match parse_expr(p)? { Some(e) => e, None => break };
                args.push(e);
                if !p.eat(",") { break; }
            }
        }
        return Ok(Some(Expr::Func { name, args }));
    }
    // star column expansion
    if tok == "*" {
        p.i += 1;
        return Ok(Some(Expr::Col { name: "*".into() }));
    }
    // alias.column reference
    if tok.contains('.') && !tok.starts_with('/') {
        let parts: Vec<&str> = tok.splitn(2, '.').collect();
        if parts.len() == 2 && columns::is_column(&parts[1].to_lowercase()) {
            p.i += 1;
            return Ok(Some(Expr::Alias { alias: parts[0].to_string(), name: parts[1].to_lowercase() }));
        }
    }
    // embedded operators inside a single token (e.g. size/2, 5--2, -2)
    if let Some(parts) = split_embedded(&tok) {
        if parts.len() > 1 {
            p.i += 1;
            let mut iter = parts.into_iter();
            let first = iter.next().unwrap();
            let mut left = operand_from_text(&first)?;
            for chunk in iter {
                let (op, txt) = chunk;
                let r = operand_from_text(&txt)?;
                left = Expr::Arith { op, l: Box::new(left), r: Box::new(r) };
            }
            return Ok(Some(left));
        }
    }
    // number?
    if let Ok(v) = tok.parse::<f64>() {
        p.i += 1;
        return Ok(Some(Expr::Num(v)));
    }
    // boolean?
    if low == "true" || low == "false" {
        p.i += 1;
        return Ok(Some(Expr::Bool(low == "true")));
    }
    // known column?
    if columns::is_column(&low) {
        p.i += 1;
        return Ok(Some(Expr::Col { name: low }));
    }
    // string literal: bare unknown word or quoted string
    if !glued || tok.chars().next().map(|c| c.is_alphabetic()).unwrap_or(false) || tok.starts_with('/') {
        p.i += 1;
        return Ok(Some(Expr::Str(tok)));
    }
    p.i = start;
    Ok(None)
}

/// Split a token into (operator, text) chunks when it contains arithmetic operators
/// and the pieces look like numbers or valid operands. Returns None when the token
/// should be treated as a plain literal.
fn split_embedded(tok: &str) -> Option<Vec<(char, String)>> {
    if tok.is_empty() { return None; }
    if tok.starts_with('/') {
        // leading division: empty left operand
        let rest = &tok[1..];
        let inner = split_token_operators(rest);
        if inner.is_empty() { return None; }
        let mut out: Vec<(char, String)> = Vec::new();
        let mut cur: Vec<String> = Vec::new();
        let mut op = '/';
        for piece in inner {
            if piece.len() == 1 && "+-*/%".contains(&piece) {
                cur.push(piece.clone());
                continue;
            }
            // decide operator between accumulated operands
            if out.is_empty() {
                op = '/';
            }
            cur.push(piece.clone());
            out.push((op, cur.join("")));
            cur = Vec::new();
        }
        if !cur.is_empty() {
            // trailing operator with no operand
            return None;
        }
        return Some(out);
    }
    let pieces = split_token_operators(tok);
    if pieces.len() <= 1 { return None; }
    // Check the pieces: operands must be numbers or known columns or bare words
    let mut out: Vec<(char, String)> = Vec::new();
    let mut cur_ops: Vec<char> = Vec::new();
    let mut cur = String::new();
    let mut have_first = false;
    for piece in pieces {
        if piece.len() == 1 && "+-*/%".contains(&piece) {
            cur_ops.push(piece.chars().next().unwrap());
            continue;
        }
        if !have_first {
            // first operand: must be a number, column or bare word (not empty)
            if piece.is_empty() { return None; }
            if !(piece.parse::<f64>().is_ok() || columns::is_column(&piece.to_lowercase()) || piece.chars().all(|c| c.is_alphanumeric() || c == '_' || c == '.')) {
                return None;
            }
            cur = piece;
            have_first = true;
        } else {
            let op = *cur_ops.first().unwrap_or(&'+');
            cur_ops.clear();
            if !(piece.parse::<f64>().is_ok() || columns::is_column(&piece.to_lowercase()) || piece.chars().all(|c| c.is_alphanumeric() || c == '_' || c == '.')) {
                return None;
            }
            out.push((op, cur.clone()));
            cur = piece;
        }
    }
    if !have_first { return None; }
    if !cur_ops.is_empty() {
        // trailing operator: not a valid expression
        return None;
    }
    if out.is_empty() { return None; }
    out.push(('*', cur.clone()));
    // rebuild: replace the dummy last entry with the operator-less tail
    if let Some(last) = out.last_mut() { last.0 = *out.iter().nth_back(1).map(|x| x.0).unwrap_or('*'); }
    // Instead of this hack, reconstruct properly below
    let mut res: Vec<(char, String)> = Vec::new();
    let mut pending: Option<char> = None;
    let mut first_txt: Option<String> = None;
    for piece in pieces {
        if piece.len() == 1 && "+-*/%".contains(&piece) {
            pending = piece.chars().next();
            continue;
        }
        match first_txt.take() {
            None => first_txt = Some(piece),
            Some(prev) => {
                let op = pending.unwrap_or('+');
                pending = None;
                res.push((op, prev));
                first_txt = Some(piece);
            }
        }
    }
    if let Some(last) = first_txt { res.push(('+', last)); }
    if res.len() < 2 { return None; }
    // shift operators so entry i holds the operator applied to entry i+1
    let mut fixed: Vec<(char, String)> = Vec::new();
    for (i, (op, txt)) in res.iter().enumerate() {
        if i + 1 < res.len() {
            let next_op = res[i + 1].0;
            fixed.push((next_op, txt.clone()));
        } else {
            fixed.push((*op, txt.clone()));
        }
    }
    let mut proper: Vec<(char, String)> = Vec::new();
    let mut txts: Vec<String> = fixed.iter().map(|x| x.1.clone()).collect();
    let mut ops: Vec<char> = Vec::new();
    for piece in pieces {
        if piece.len() == 1 && "+-*/%".contains(&piece) { ops.push(piece.chars().next().unwrap()); }
    }
    // ops has ops.len() = txts.len() - 1
    if ops.len() + 1 != txts.len() { return None; }
    for i in 0..txts.len() - 1 {
        proper.push((ops[i], txts[i].clone()));
    }
    proper.push((ops[0], txts.last().unwrap().clone()));
    proper.pop();
    let mut final_res: Vec<(char, String)> = Vec::new();
    for i in 0..txts.len() {
        if i + 1 < txts.len() {
            final_res.push((ops[i], txts[i].clone()));
        }
    }
    final_res.push(('+', txts.last().unwrap().clone()));
    let mut r = final_res;
    r.pop();
    r.push(('+', txts.last().unwrap().clone()));
    // We just need pairs (op, operand) where op is the operator before operand (index i uses ops[i-1]);
    // rebuild cleanly:
    let mut out2: Vec<(char, String)> = Vec::new();
    out2.push((ops[0], txts[0].clone()));
    for i in 1..txts.len() {
        out2.push((ops[i - 1], txts[i].clone()));
    }
    Some(out2)
}

fn operand_from_text(txt: &str) -> Result<Expr, ParseErr> {
    if txt.is_empty() {
        return Ok(Expr::Str(String::new()));
    }
    if let Ok(v) = txt.parse::<f64>() { return Ok(Expr::Num(v)); }
    let low = txt.to_lowercase();
    if low == "true" { return Ok(Expr::Bool(true)); }
    if low == "false" { return Ok(Expr::Bool(false)); }
    if columns::is_column(&low) { return Ok(Expr::Col { name: low }); }
    Ok(Expr::Str(txt.to_string()))
}

fn parse_roots(p: &mut P) -> Result<Vec<Root>, ParseErr> {
    let mut out: Vec<Root> = Vec::new();
    loop {
        if p.peek().is_none() { break; }
        if p.is_section_kw() { break; }
        if p.peek_text() == Some(",") {
            p.i += 1;
            if p.peek().is_none() || p.is_section_kw() { break; }
            return Err(ParseErr("could not parse tokens at the end of the query".into()));
        }
        let path = match p.next() { Some(t) => t, None => break };
        let mut opts = RootOpts::default();
        loop {
            let t = match p.peek_text() { Some(t) => t.to_lowercase(), None => break };
            match t.as_str() {
                "," => break,
                "mindepth" => { p.i += 1; let v = p.next().ok_or(ParseErr("Expecting number".into()))?; opts.mindepth = v.parse::<u32>().ok(); }
                "maxdepth" | "depth" => { p.i += 1; let v = p.next().ok_or(ParseErr("Expecting number".into()))?; opts.maxdepth = v.parse::<u32>().ok(); }
                "archives" | "arc" => { p.i += 1; opts.archives = true; }
                "symlinks" | "sym" => { p.i += 1; opts.symlinks = true; }
                "gitignore" | "git" => { p.i += 1; opts.gitignore = true; }
                "nogitignore" | "nogit" => { p.i += 1; opts.gitignore = false; }
                "hgignore" | "hg" => { p.i += 1; opts.hgignore = true; }
                "nohgignore" | "nohg" => { p.i += 1; opts.hgignore = false; }
                "dockerignore" | "docker" | "dock" => { p.i += 1; opts.dockerignore = true; }
                "nodockerignore" | "nodocker" | "nodock" => { p.i += 1; opts.dockerignore = false; }
                "dfs" => { p.i += 1; opts.dfs = true; }
                "bfs" => { p.i += 1; opts.dfs = false; }
                "regexp" | "rx" => { p.i += 1; opts.regexp = true; }
                "as" => { p.i += 1; let v = p.next().ok_or(ParseErr("Expecting alias".into()))?; opts.alias = Some(v); }
                _ => break,
            }
        }
        out.push(Root { path, opts });
        if !p.eat(",") { break; }
    }
    Ok(out)
}

fn parse_cond(p: &mut P) -> Result<Cond, ParseErr> {
    parse_or(p)
}

fn parse_or(p: &mut P) -> Result<Cond, ParseErr> {
    let mut left = parse_and(p)?;
    while p.eat_ci("or") {
        let r = parse_and(p)?;
        left = Cond::Or(Box::new(left), Box::new(r));
    }
    Ok(left)
}

fn parse_and(p: &mut P) -> Result<Cond, ParseErr> {
    let mut left = parse_not(p)?;
    while p.eat_ci("and") {
        let r = parse_not(p)?;
        left = Cond::And(Box::new(left), Box::new(r));
    }
    Ok(left)
}

fn parse_not(p: &mut P) -> Result<Cond, ParseErr> {
    if p.eat_ci("not") {
        // "not exists (...)" / "not in (...)"
        let inner = parse_not(p)?;
        if let Cond::Sub { left, neg, sub, exists } = inner {
            return Ok(Cond::Sub { left, neg: !neg, sub, exists });
        }
        if let Cond::Cmp { left, op, right, right_text } = inner {
            let neg_op = match op {
                CmpOp::Rx => Some(CmpOp::NotRx),
                CmpOp::In => Some(CmpOp::NotIn),
                CmpOp::Exists => Some(CmpOp::NotExists),
                _ => None,
            };
            if let Some(nop) = neg_op {
                return Ok(Cond::Cmp { left, op: nop, right, right_text });
            }
        }
        return Ok(Cond::Not(Box::new(inner)));
    }
    parse_primary(p)
}

fn parse_primary(p: &mut P) -> Result<Cond, ParseErr> {
    if let Some(t) = p.peek_text() {
        if t == "(" || t == "{" {
            let close = if t == "(" { ")" } else { "}" };
            p.i += 1;
            let c = parse_or(p)?;
            if !p.eat(close) { return Err(ParseErr("Error parsing expression, expecting string".into())); }
            return Ok(c);
        }
        if t.eq_ignore_ascii_case("exists") {
            p.i += 1;
            let sub = parse_subquery(p)?;
            return Ok(Cond::Sub { left: Expr::Str(String::new()), neg: false, sub: Box::new(sub), exists: true });
        }
    }
    // left expression
    let lstart = p.i;
    let left = match parse_expr(p)? {
        Some(e) => e,
        None => return Err(ParseErr("Error parsing expression, expecting string".into())),
    };
    if p.i == lstart {
        return Err(ParseErr("Error parsing expression, expecting string".into()));
    }
    // operator
    let optxt = match p.peek_text() {
        Some(t) => t.to_string(),
        None => return Err(ParseErr("Error parsing expression, expecting string".into())),
    };
    let op = match cmp_op(&optxt) {
        Some(o) => { p.i += 1; o }
        None => return Err(ParseErr("Error parsing expression, expecting string".into())),
    };
    match op {
        CmpOp::Between => {
            let a = parse_value_expr(p)?;
            if !p.eat_ci("and") { return Err(ParseErr("Error parsing expression, expecting string".into())); }
            let b = parse_value_expr(p)?;
            let right_text = format!("{} and {}", value_text(&a), value_text(&b));
            Ok(Cond::Cmp { left, op, right: Expr::Func { name: "between_args".into(), args: vec![a, b] }, right_text })
        }
        CmpOp::In | CmpOp::NotIn => {
            if !p.eat("(") { return Err(ParseErr("Error parsing expression, expecting string".into())); }
            // subquery?
            if p.peek_text().map(|t| t.eq_ignore_ascii_case("select")).unwrap_or(false) {
                p.i += 1;
                let sub = parse_query_tokens(p)?;
                if !p.eat(")") { return Err(ParseErr("Error parsing expression, expecting string".into())); }
                return Ok(Cond::Sub { left, neg: op == CmpOp::NotIn, sub: Box::new(sub), exists: false });
            }
            let mut vals = Vec::new();
            loop {
                if p.peek_text() == Some(")") { p.i += 1; break; }
                let e = match parse_value_expr(p) { Some(e) => e, None => return Err(ParseErr("Error parsing expression, expecting string".into())) };
                vals.push(e);
                if !p.eat(",") {
                    if p.peek_text() == Some(")") { p.i += 1; }
                    break;
                }
            }
            Ok(Cond::Cmp { left, op, right: Expr::Func { name: "in_list".into(), args: vals }, right_text: String::new() })
        }
        CmpOp::Exists | CmpOp::NotExists => {
            let sub = parse_subquery(p)?;
            Ok(Cond::Sub { left: Expr::Str(String::new()), neg: op == CmpOp::NotExists, sub: Box::new(sub), exists: true })
        }
        _ => {
            let rstart = p.i;
            let right = match parse_value_expr(p) {
                Some(e) => e,
                None => return Err(ParseErr("Error parsing expression, expecting string".into())),
            };
            let right_text = render_tokens(&p.t[rstart..p.i]);
            Ok(Cond::Cmp { left, op, right, right_text })
        }
    }
}

fn value_text(e: &Expr) -> String {
    match e {
        Expr::Str(s) => s.clone(),
        Expr::Num(v) => crate::val::format_num(*v),
        Expr::Bool(b) => if *b { "true".into() } else { "false".into() },
        _ => display_name(e),
    }
}

fn parse_value_expr(p: &mut P) -> Option<Expr> {
    // A value expression: merge adjacent glued tokens into one literal when needed
    let start = p.i;
    if p.peek().is_none() { return None; }
    // try normal expression parse first
    match parse_expr(p) {
        Ok(Some(e)) => return Some(e),
        Ok(None) => {}
        Err(_) => { p.i = start; return None; }
    }
    if p.i == start { return None; }
    None
}

fn parse_subquery(p: &mut P) -> Result<Query, ParseErr> {
    if !p.eat("(") { return Err(ParseErr("Error parsing expression, expecting string".into())); }
    let _ = p.eat_ci("select");
    let q = parse_query_tokens(p)?;
    if !p.eat(")") { return Err(ParseErr("Error parsing expression, expecting string".into())); }
    Ok(q)
}

/// Parse a query from the current position until a closing parenthesis or the end
fn parse_query_tokens(p: &mut P) -> Result<Query, ParseErr> {
    let mut fields = Vec::new();
    loop {
        if p.peek().is_none() { break; }
        let t = p.peek_text().map(|s| s.to_string()).unwrap_or_default();
        if t == ")" { break; }
        if t.eq_ignore_ascii_case("from") || t.eq_ignore_ascii_case("where") { break; }
        let start = p.i;
        match parse_field(p)? {
            Some(f) => fields.push(f),
            None => { p.i = start; break; }
        }
        if p.eat(",") {
            if let Some(t2) = p.peek_text() {
                if t2.starts_with('/') { p.i -= 1; break; }
            }
            continue;
        }
        break;
    }
    let mut roots = Vec::new();
    let mut cond = None;
    let mut group_by = Vec::new();
    let mut order_by = Vec::new();
    let mut limit = 0u64;
    let mut offset = 0u64;
    let mut format = Format::Tabs;
    let mut state = 0u8;
    loop {
        match p.peek_text() {
            Some(t) if t.eq_ignore_ascii_case("from") => {
                if state != 0 || !roots.is_empty() { break; }
                p.i += 1;
                roots = parse_roots_sub(p)?;
                state = 0;
            }
            Some(t) if t.eq_ignore_ascii_case("where") => {
                if state > 1 { break; }
                p.i += 1;
                cond = Some(parse_cond(p)?);
                state = 2;
            }
            Some(t) if t.eq_ignore_ascii_case("group") => {
                if state > 2 { break; }
                p.i += 1;
                let _ = p.eat_ci("by");
                group_by = parse_expr_list(p)?;
                state = 3;
            }
            Some(t) if t.eq_ignore_ascii_case("order") => {
                if state > 3 { break; }
                p.i += 1;
                let _ = p.eat_ci("by");
                order_by = parse_order(p)?;
                state = 4;
            }
            Some(t) if t.eq_ignore_ascii_case("limit") => {
                if state > 4 { break; }
                p.i += 1;
                if let Some(v) = p.next() { limit = v.parse::<u64>().unwrap_or(0); }
                state = 5;
            }
            Some(t) if t.eq_ignore_ascii_case("offset") => {
                if state > 5 { break; }
                p.i += 1;
                if let Some(v) = p.next() { offset = v.parse::<u64>().unwrap_or(0); }
                state = 6;
            }
            Some(t) if t.eq_ignore_ascii_case("into") => {
                if state > 6 { break; }
                p.i += 1;
                if let Some(v) = p.next() {
                    format = match v.to_lowercase().as_str() {
                        "tabs" => Format::Tabs, "lines" => Format::Lines, "list" => Format::List,
                        "csv" => Format::Csv, "json" => Format::Json, "html" => Format::Html,
                        _ => Format::Tabs,
                    };
                }
                state = 7;
            }
            _ => break,
        }
    }
    let has_agg = fields.iter().any(|f| contains_agg(&f.expr));
    Ok(Query { fields, roots, cond, group_by, order_by, limit, offset, format, has_agg })
}

fn parse_roots_sub(p: &mut P) -> Result<Vec<Root>, ParseErr> {
    let mut out = Vec::new();
    loop {
        if p.peek().is_none() { break; }
        let t = p.peek_text().map(|s| s.to_string()).unwrap_or_default();
        if t == ")" { break; }
        if ["where", "group", "order", "limit", "offset", "into"].iter().any(|k| t.eq_ignore_ascii_case(k)) { break; }
        if t == "," {
            p.i += 1;
            continue;
        }
        let path = match p.next() { Some(t) => t, None => break };
        let mut opts = RootOpts::default();
        loop {
            let t2 = match p.peek_text() { Some(t2) => t2.to_lowercase(), None => break };
            match t2.as_str() {
                "mindepth" => { p.i += 1; let v = p.next().unwrap_or_default(); opts.mindepth = v.parse::<u32>().ok(); }
                "maxdepth" | "depth" => { p.i += 1; let v = p.next().unwrap_or_default(); opts.maxdepth = v.parse::<u32>().ok(); }
                "archives" | "arc" => { p.i += 1; opts.archives = true; }
                "symlinks" | "sym" => { p.i += 1; opts.symlinks = true; }
                "dfs" => { p.i += 1; opts.dfs = true; }
                "bfs" => { p.i += 1; opts.dfs = false; }
                "as" => { p.i += 1; if let Some(v) = p.next() { opts.alias = Some(v); } }
                _ => break,
            }
        }
        out.push(Root { path, opts });
        if !p.eat(",") { break; }
    }
    Ok(out)
}
