pub fn mode_string(mode: u32, ftype: u8) -> String {
    let c = match ftype {
        1 => '-',
        2 => 'd',
        3 => 'l',
        4 => 'p',
        5 => 'c',
        6 => 'b',
        7 => 's',
        _ => '-',
    };
    let mut s = String::new();
    s.push(c);
    let bits = [
        (0o400, 'r', 'S'), (0o200, 'w', 'S'), (0o100, 'x', 'S'),
        (0o40, 'r', 'S'), (0o20, 'w', 'S'), (0o10, 'x', 'S'),
