fn decode_names(buf: &[i8]) -> Vec<String> {
    let bytes: Vec<u8> = buf.iter().map(|b| *b as u8).collect();
    let mut out = Vec::new();
    for part in bytes.split(|b| *b == 0) {
        if !part.is_empty() {
            out.push(String::from_utf8_lossy(part).to_string());
        }
    }
    out
}

const FS_IOC_GETFLAGS: u64 = 0x40086602;
const FS_IOC_FLAGS: [u32; 26] = [
    0x00000080, // s secure deletion
    0x00000100, // u undelete
    0x00000400, // c compress
    0x00000008, // S synchronous updates
    0x00000010, // i immutable
    0x00000020, // a append only
    0x00000040, // d no dump
    0x00000001, // A no atime
    0x00100000, // E encrypted
    0x00001000, // I indexed directory
    0x00002000, // j journal data
    0x00010000, // t no tail-merging
    0x00020000, // D dirsync
    0x00040000, // T top of directory hierarchy
    0x00080000, // e extents
    0x00200000, // V verity
    0x00400000, // C no copy-on-write
    0x00800000, // x DAX
    0x00004000, // N inline data
    0x02000000, // P project hierarchy
    0x04000000, // F case-insensitive
    0, 0, 0, 0, 0,
];
const FS_IOC_LETTERS: [char; 26] = ['s','u','c','S','i','a','d','A','E','I','j','t','D','T','e','V','C','x','N','P','F','-','-','-','-','-'];

pub fn extattrs_of(path: &std::path::Path) -> Option<String> {
    let c = match CString::new(path.as_os_str().to_string_lossy().as_bytes()) {
        Ok(c) => c,
        Err(_) => return None,
    };
    let fd = unsafe { open(c.as_ptr(), 0 /*O_RDONLY*/, 0) };
    if fd < 0 { return None; }
    let mut flags: i64 = 0;
    let r = unsafe { ioctl(fd, FS_IOC_GETFLAGS, &mut flags as *mut i64) };
    unsafe { close(fd) };
    if r != 0 { return None; }
    let uflags = flags as u32;
    let mut s = String::new();
    for (i, f) in FS_IOC_FLAGS.iter().enumerate() {
        if *f != 0 && uflags & *f != 0 {
            s.push(FS_IOC_LETTERS[i]);
        }
    }
    Some(s)
}

pub fn has_extattr_flag(path: &std::path::Path, letter: &str) -> Option<bool> {
    let s = extattrs_of(path)?;
    if letter.is_empty() { return Some(false); }
    Some(s.contains(letter))
}
RSEOF
echo ok"}

