pub fn find(name: &str) -> Option<&'static ColDef> {
    COLS.iter().find(|c| c.canon == name || c.aliases.iter().any(|a| *a == name))
}
pub fn canonical(name: &str) -> &'static str { find(name).map(|c| c.canon).unwrap_or(name) }
pub fn is_column(name: &str) -> bool { find(name).is_some() }

pub fn ext_of(name: &str) -> String {
    match std::path::Path::new(name).extension() {
        Some(e) => e.to_string_lossy().to_string(),
        None => String::new(),
    }
}

pub fn get(entry: &mut Entry, name: &str, ctx: &mut EvalCtx) -> Result<Val, (String, bool)> {
