        "accessed" => Val::Date(entry.atime),
        "modified" => Val::Date(entry.mtime),
        "is_dir" => Val::Bool(entry.is_dir),
        "is_file" => Val::Bool(entry.is_file),
        "is_symlink" => Val::Bool(entry.is_symlink),
        "is_pipe" => Val::Bool(entry.is_pipe),
        "is_character_device" => Val::Bool(entry.is_char),
        "is_block_device" => Val::Bool(entry.is_block),
        "is_socket" => Val::Bool(entry.is_socket),
        "device" => Val::Num(entry.device as f64),
        "rdev" => Val::Num(entry.rdev as f64),
        "inode" => Val::Num(entry.inode as f64),
        "blocks" => Val::Num(entry.blocks as f64),
        "hardlinks" => Val::Num(entry.hardlinks as f64),
        "atime" => Val::Num(entry.atime as f64),
        "mtime" => Val::Num(entry.mtime as f64),
        "ctime" => Val::Num(entry.ctime as f64),
        "mode" => Val::Str(crate::fsx::mode_string(entry.mode, entry.ftype)),
        "user_read" => Val::Bool(entry.mode & 0o400 != 0),
        "user_write" => Val::Bool(entry.mode & 0o200 != 0),
        "user_exec" => Val::Bool(entry.mode & 0o100 != 0),
        "user_all" => Val::Bool(entry.mode & 0o700 == 0o700),
        "group_read" => Val::Bool(entry.mode & 0o40 != 0),
        "group_write" => Val::Bool(entry.mode & 0o20 != 0),
        "group_exec" => Val::Bool(entry.mode & 0o10 != 0),
        "group_all" => Val::Bool(entry.mode & 0o70 == 0o70),
        "other_read" => Val::Bool(entry.mode & 0o4 != 0),
