        "xattr_count" => Val::Num(xattr_list(entry).map(|v| v.len() as f64).unwrap_or(0.0)),
        "extattrs" => Val::Str(entry.extattrs.borrow_mut().get_or_insert_with(|| crate::fsx::extattrs_of(&entry.path)).clone().unwrap_or_default()),
        "has_extattrs" => Val::Bool(!entry.extattrs.borrow_mut().get_or_insert_with(|| crate::fsx::extattrs_of(&entry.path)).clone().unwrap_or_default().is_empty()),
