pub fn find(name: &str) -> Option<&'static ColDef> {
    COLS.iter().find(|c| c.canon == name || c.aliases.iter().any(|a| *a == name))
}
pub fn canonical(name: &str) -> &'static str { find(name).map(|c| c.canon).unwrap_or(name) }
pub fn is_column(name: &str) -> bool { find(name).is_some() }

pub fn ext_of(name: &str) -> String {
    match std::path::Path::new(name).extension() {
        Some(e) => e.to_string_lossy().to_string(),
        None => String::new(),
    }
}

pub fn get(entry: &mut Entry, name: &str, ctx: &mut EvalCtx) -> Result<Val, (String, bool)> {
    let canon = canonical(name);
    Ok(match canon {
        "name" => Val::Str(entry.name.clone()),
        "filename" => Val::Str(file_stem(&entry.name)),
        "extension" => Val::Str(ext_of(&entry.name)),
        "path" => Val::Str(rel_path(entry)),
        "abs_path" => Val::Str(abs_path(entry)),
        "directory" => Val::Str(dir_of(entry)),
        "abs_dir" => Val::Str(abs_dir(entry)),
        "size" => Val::Num(entry.size.unwrap_or(0) as f64),
        "formatted_size" => Val::Str(crate::fmtsize::format_size(entry.size.unwrap_or(0), ctx.cfg.default_file_size_format.as_str())),
        "uid" => Val::Num(entry.uid as f64),
        "gid" => Val::Num(entry.gid as f64),
        "user" => Val::Str(crate::fsx::user_name(entry.uid)),
        "group" => Val::Str(crate::fsx::group_name(entry.gid)),
        "created" => Val::Date(entry.btime.unwrap_or(entry.ctime)),
        "accessed" => Val::Date(entry.atime),
        "modified" => Val::Date(entry.mtime),
        "is_dir" => Val::Bool(entry.is_dir),
        "is_file" => Val::Bool(entry.is_file),
        "is_symlink" => Val::Bool(entry.is_symlink),
        "is_pipe" => Val::Bool(entry.is_pipe),
        "is_character_device" => Val::Bool(entry.is_char),
        "is_block_device" => Val::Bool(entry.is_block),
        "is_socket" => Val::Bool(entry.is_socket),
        "device" => Val::Num(entry.device as f64),
        "rdev" => Val::Num(entry.rdev as f64),
        "inode" => Val::Num(entry.inode as f64),
        "blocks" => Val::Num(entry.blocks as f64),
        "hardlinks" => Val::Num(entry.hardlinks as f64),
        "atime" => Val::Num(entry.atime as f64),
        "mtime" => Val::Num(entry.mtime as f64),
        "ctime" => Val::Num(entry.ctime as f64),
        "mode" => Val::Str(crate::fsx::mode_string(entry.mode, entry.ftype)),
        "user_read" => Val::Bool(entry.mode & 0o400 != 0),
        "user_write" => Val::Bool(entry.mode & 0o200 != 0),
        "user_exec" => Val::Bool(entry.mode & 0o100 != 0),
        "user_all" => Val::Bool(entry.mode & 0o700 == 0o700),
        "group_read" => Val::Bool(entry.mode & 0o40 != 0),
        "group_write" => Val::Bool(entry.mode & 0o20 != 0),
        "group_exec" => Val::Bool(entry.mode & 0o10 != 0),
        "group_all" => Val::Bool(entry.mode & 0o70 == 0o70),
        "other_read" => Val::Bool(entry.mode & 0o4 != 0),
        "other_write" => Val::Bool(entry.mode & 0o2 != 0),
        "other_exec" => Val::Bool(entry.mode & 0o1 != 0),
        "other_all" => Val::Bool(entry.mode & 0o7 == 0o7),
        "suid" => Val::Bool(entry.mode & 0o4000 != 0),
        "sgid" => Val::Bool(entry.mode & 0o2000 != 0),
        "is_sticky" => Val::Bool(entry.mode & 0o1000 != 0),
        "is_hidden" => Val::Bool(entry.name.starts_with('.')),
        "has_xattrs" => Val::Bool(xattr_list(entry).map(|v| !v.is_empty()).unwrap_or(false)),
        "xattr_count" => Val::Num(xattr_list(entry).map(|v| v.len() as f64).unwrap_or(0.0)),
        "extattrs" => Val::Str(entry.extattrs.borrow_mut().get_or_insert_with(|| crate::fsx::extattrs_of(&entry.path)).clone().unwrap_or_default()),
        "has_extattrs" => Val::Bool(!entry.extattrs.borrow_mut().get_or_insert_with(|| crate::fsx::extattrs_of(&entry.path)).clone().unwrap_or_default().is_empty()),
        "acl" => Val::Str(String::new()),
        "has_acl" => Val::Bool(false),
        "default_acl" => Val::Str(String::new()),
        "has_default_acl" => Val::Bool(false),
        "has_capabilities" => Val::Bool(false),
        "capabilities" => Val::Str(String::new()),
        "is_shebang" => Val::Bool(shebang(entry)),
        "is_empty" => Val::Bool(is_empty(entry)),
        "width" => Val::Num(crate::img::dimensions(entry).0.unwrap_or(0) as f64),
        "height" => Val::Num(crate::img::dimensions(entry).1.unwrap_or(0) as f64),
        "duration" => Val::Num(duration(entry)),
        "bitrate" => Val::Num(crate::mp3::info(entry).bitrate.unwrap_or(0) as f64),
        "freq" => Val::Num(crate::mp3::info(entry).freq.unwrap_or(0) as f64),
        "title" => Val::Str(crate::mp3::info(entry).title.clone().unwrap_or_default()),
        "album" => Val::Str(crate::mp3::info(entry).album.clone().unwrap_or_default()),
        "artist" => Val::Str(crate::mp3::info(entry).artist.clone().unwrap_or_default()),
        "genre" => Val::Str(crate::mp3::info(entry).genre.clone().unwrap_or_default()),
        "mp3_year" => Val::Num(crate::mp3::info(entry).year.unwrap_or(0) as f64),
        "mime" => Val::Str(crate::mime::detect(entry)),
        "line_count" => Val::Num(line_count(entry) as f64),
        "is_binary" => Val::Bool(binary(entry)),
        "is_text" => Val::Bool(text(entry)),
        "is_archive" => Val::Bool(crate::cfg::is_ext(entry, "is_archive")),
        "is_audio" => Val::Bool(crate::cfg::is_ext(entry, "is_audio")),
        "is_book" => Val::Bool(crate::cfg::is_ext(entry, "is_book")),
        "is_doc" => Val::Bool(crate::cfg::is_ext(entry, "is_doc")),
        "is_font" => Val::Bool(crate::cfg::is_ext(entry, "is_font")),
        "is_image" => Val::Bool(crate::cfg::is_ext(entry, "is_image")),
        "is_source" => Val::Bool(crate::cfg::is_ext(entry, "is_source")),
        "is_video" => Val::Bool(crate::cfg::is_ext(entry, "is_video")),
        "sha1" => Val::Str(hash(entry, "sha1")?),
        "sha256" => Val::Str(hash(entry, "sha256")?),
        "sha512" => Val::Str(hash(entry, "sha512")?),
        "sha3" => Val::Str(hash(entry, "sha3")?),
        _ => Val::Null,
    })
}

pub fn xattr_list(entry: &Entry) -> Option<Vec<(String, String)>> {
    entry.xattrs.borrow_mut().get_or_insert_with(|| crate::fsx::list_xattrs(&entry.path)).clone()
}

fn file_stem(name: &str) -> String {
    match std::path::Path::new(name).file_stem() {
        Some(s) => s.to_string_lossy().to_string(),
        None => name.to_string(),
    }
}

pub fn rel_path(entry: &Entry) -> String {
    if let Some(a) = &entry.archive {
        return a.clone();
    }
    let p = entry.path.to_string_lossy();
    let root = &entry.root_path;
    if root.is_empty() { return p.to_string(); }
    match std::path::Path::new(&p).strip_prefix(std::path::Path::new(root)) {
        Ok(r) => r.to_string_lossy().to_string(),
        Err(_) => p.to_string(),
    }
}

pub fn abs_path(entry: &Entry) -> String {
    if let Some(a) = &entry.archive { return a.clone(); }
    let canon = std::fs::canonicalize(&entry.path);
    match canon {
        Ok(p) => p.to_string_lossy().to_string(),
        Err(_) => entry.path.to_string_lossy().to_string(),
    }
}

pub fn dir_of(entry: &Entry) -> String {
    let p = rel_path(entry);
    match std::path::Path::new(&p).parent() {
        Some(d) => d.to_string_lossy().to_string(),
        None => String::new(),
    }
}

pub fn abs_dir(entry: &Entry) -> String {
    let p = abs_path(entry);
    match std::path::Path::new(&p).parent() {
        Some(d) => d.to_string_lossy().to_string(),
        None => String::new(),
    }
}

fn read_head(entry: &Entry, n: usize) -> Option<Vec<u8>> {
    use std::io::Read;
    if !entry.is_file && !entry.is_symlink { return None; }
    let mut f = std::fs::File::open(&entry.path).ok()?;
    let mut buf = vec![0u8; n];
    let mut total = 0;
    while total < n {
        match f.read(&mut buf[total..]) {
            Ok(0) => break,
            Ok(k) => total += k,
            Err(_) => break,
        }
    }
    buf.truncate(total);
    Some(buf)
}

pub fn shebang(entry: &Entry) -> bool {
    if entry.is_dir { return false; }
    match read_head(entry, 2) {
        Some(b) => b == b"#!",
        None => false,
    }
}

pub fn is_empty(entry: &Entry) -> bool {
    if entry.is_dir {
        match std::fs::read_dir(&entry.path) {
            Ok(mut it) => it.next().is_none(),
            Err(_) => false,
        }
    } else {
        entry.size.unwrap_or(1) == 0
    }
}

pub fn line_count(entry: &Entry) -> u64 {
    if entry.is_dir { return 0; }
    *entry.line_count.borrow_mut().get_or_insert_with(|| {
        match std::fs::read(&entry.path) {
            Ok(data) => Some(data.iter().filter(|b| **b == b'\n').count() as u64),
            Err(_) => Some(0),
        }
    }).unwrap_or(0)
}

pub fn mime_of(entry: &Entry) -> String { crate::mime::detect(entry) }

pub fn binary(entry: &Entry) -> bool {
    if !entry.is_file { return false; }
    let m = mime_of(entry);
    is_binary_mime(&m)
}

pub fn text(entry: &Entry) -> bool {
    if !entry.is_file { return false; }
    !binary(entry)
}

pub fn is_binary_mime(m: &str) -> bool {
    if m.starts_with("text/") { return false; }
    if m == "application/x-shellscript" { return false; }
    if m == "inode/directory" { return false; }
    true
}

fn hash(entry: &Entry, kind: &str) -> Result<String, (String, bool)> {
    if entry.is_dir { return Ok(String::new()); }
    let cell = match kind {
        "sha1" => &entry.sha1,
        "sha256" => &entry.sha256,
        "sha512" => &entry.sha512,
        _ => &entry.sha3,
    };
    let computed = cell.borrow_mut().get_or_insert_with(|| {
        match std::fs::read(&entry.path) {
            Ok(data) => Some(crate::hash::digest(kind, &data)),
            Err(_) => Some(String::new()),
        }
    }).clone();
    Ok(computed.unwrap_or_default())
}

pub fn duration(entry: &Entry) -> f64 {
    crate::mp3::info(entry).duration.unwrap_or(0.0)
}
