// Expression evaluation
use crate::val::{Val, parse_date_range};
use crate::parse::{Expr, CmpOp, Cond, Query, Field};
use crate::fsx::Entry;
use crate::columns;
use crate::functions;
use crate::cfg::Config;
use crate::rx::Regex;
use crate::dates::{DateTime, local_to_epoch, epoch_to_local, now_epoch, days_from_civil, civil_from_days, days_in_month, MONTH_NAMES, DAY_NAMES};

pub struct EvalCtx<'a> {
    pub entry: &'a mut Entry,
    pub err_prefix: String,
    pub us_dates: bool,
    pub no_errors: bool,
    pub cwd: std::path::PathBuf,
}

pub type EvalResult = Result<Val, (String, bool)>;

fn rerr(msg: &str) -> EvalResult { Err((msg.to_string(), true)) }

pub fn eval(e: &Expr, ctx: &mut EvalCtx) -> EvalResult {
    match e {
        Expr::Col { name } => crate::columns::get(ctx.entry, name, ctx),
        Expr::Str(s) => Ok(Val::Str(s.clone())),
        Expr::Num(v) => Ok(Val::Num(*v)),
        Expr::Bool(b) => Ok(Val::Bool(*b)),
        Expr::Arith { op, l, r } => {
            let a = eval(l, ctx)?;
            let b = eval(r, ctx)?;
            arith(*op, &a, &b)
        }
        Expr::Func { name, args } => eval_func(name, args, ctx),
        Expr::Alias { alias, name } => {
            // resolved earlier by the engine: store in the context overrides
            if let Some(v) = ctx.alias_value(alias, name) {
                Ok(v)
            } else {
                crate::columns::get(ctx.entry, name, ctx)
            }
        }
    }
}

pub fn arith(op: char, a: &Val, b: &Val) -> EvalResult {
    let x = a.num();
    let y = b.num();
    let v = match op {
        '+' => x + y,
        '-' => x - y,
        '*' => x * y,
        '/' => { if y == 0.0 { return rerr("Division by zero"); } x / y }
        '%' => { if y == 0.0 { return rerr("Division by zero"); } x % y }
        _ => return rerr("Unknown operator"),
    };
    Ok(Val::Num(v))
}

fn as_string(v: &Val) -> String { v.raw_str() }

fn glob_to_regex(pat: &str) -> String {
    let mut out = String::new();
    for c in pat.chars() {
        match c {
            '*' => out.push_str(".*"),
            '?' => out.push('.'),
            other => {
                if "\\.+()[]{}|^$".contains(other) { out.push('\\'); }
                out.push(other);
            }
        }
    }
    out
}

fn like_to_regex(pat: &str) -> Result<String, String> {
    if pat.is_empty() { return Err(pat.to_string()); }
    let mut out = String::new();
    for c in pat.chars() {
        match c {
            '%' => out.push_str(".*"),
            '_' => out.push('.'),
            other => {
                if "\\.+*?()[]{}|^$".contains(other) { out.push('\\'); }
                out.push(other);
            }
        }
    }
    Ok(out)
}

fn compare(op: CmpOp, left: &Val, right: &Val, right_text: &str, ctx: &mut EvalCtx) -> Result<bool, (String, bool)> {
    let res = match left {
        Val::Date(ts) => date_cmp(op, *ts, right_text, ctx)?,
        Val::Bool(b) => {
            let rb = right.boolean();
            match op {
                CmpOp::Eq | CmpOp::EEq => *b == rb,
                CmpOp::Ne | CmpOp::ENe => *b != rb,
                CmpOp::Lt => (*b as i32) < (rb as i32),
                CmpOp::Le => (*b as i32) <= (rb as i32),
                CmpOp::Gt => (*b as i32) > (rb as i32),
                CmpOp::Ge => (*b as i32) >= (rb as i32),
                _ => false,
            }
        }
        Val::Num(x) => {
            let y = right.num();
            match op {
                CmpOp::Eq | CmpOp::EEq => x == y,
                CmpOp::Ne | CmpOp::ENe => x != y,
                CmpOp::Lt => x < y,
                CmpOp::Le => x <= y,
                CmpOp::Gt => x > y,
                CmpOp::Ge => x >= y,
                _ => false,
            }
        }
        Val::Null => match op {
            CmpOp::Eq | CmpOp::EEq => right.is_null(),
            CmpOp::Ne | CmpOp::ENe => !right.is_null(),
            _ => false,
        },
        Val::Str(s) => string_cmp(op, s, right, right_text, ctx)?,
    };
    Ok(res)
}

fn string_cmp(op: CmpOp, s: &str, right: &Val, right_text: &str, ctx: &mut EvalCtx) -> Result<bool, (String, bool)> {
    let other = right.raw_str();
    Ok(match op {
        CmpOp::Eq | CmpOp::Ne | CmpOp::ENe => {
            let has_glob = other.contains('*') || other.contains('?');
            let m = if has_glob {
                let re = Regex::compile(&format!("^{}$", glob_to_regex(&other)), true).map_err(|_| (format!("Incorrect regex expression: {}", other), false))?;
                re.is_match(s)
            } else {
                s == other
            };
            if op == CmpOp::Eq { m } else { !m }
        }
        CmpOp::EEq => s == other,
        CmpOp::Lt => s < other.as_str(),
        CmpOp::Le => s <= other.as_str(),
        CmpOp::Gt => s > other.as_str(),
        CmpOp::Ge => s >= other.as_str(),
        CmpOp::Rx | CmpOp::NotRx => {
            let re = Regex::compile(&other, false).map_err(|_| (format!("Incorrect regex expression: {}", other), false))?;
            let m = re.is_match(s);
            if op == CmpOp::Rx { m } else { !m }
        }
        CmpOp::Like | CmpOp::NotLike => {
            let pat = like_to_regex(&other).map_err(|p| (format!("Error parsing LIKE expression: {}", p), true))?;
            let re = Regex::compile(&format!("^{}$", pat), true).map_err(|_| (format!("Error parsing LIKE expression: {}", other), true))?;
            let m = re.is_match(s);
            if op == CmpOp::Like { m } else { !m }
        }
        _ => false,
    })
}

fn date_cmp(op: CmpOp, ts: i64, right_text: &str, ctx: &mut EvalCtx) -> Result<bool, (String, bool)> {
    let t = right_text.trim().trim_matches('\'').trim_matches('"').trim_matches('`').to_string();
    let rng = parse_date_range(&t, ctx.us_dates).ok_or((format!("Can't parse datetime: {}", t), true))?;
    Ok(match op {
        CmpOp::Eq => ts >= rng.0 && ts <= rng.1,
        CmpOp::Ne => !(ts >= rng.0 && ts <= rng.1),
        CmpOp::EEq => ts == rng.0 && rng.0 == rng.1,
        CmpOp::ENe => !(ts == rng.0),
        CmpOp::Lt => ts < rng.0,
        CmpOp::Le => ts <= rng.1,
        CmpOp::Gt => ts > rng.1,
        CmpOp::Ge => ts >= rng.0,
        _ => false,
    })
}

pub fn eval_cond(c: &Cond, ctx: &mut EvalCtx) -> Result<bool, (String, bool)> {
    match c {
        Cond::And(a, b) => {
            if !eval_cond(a, ctx)? { return Ok(false); }
            eval_cond(b, ctx)
        }
        Cond::Or(a, b) => {
            if eval_cond(a, ctx)? { return Ok(true); }
            eval_cond(b, ctx)
        }
        Cond::Not(a) => Ok(!eval_cond(a, ctx)?),
        Cond::Cmp { left, op, right, right_text } => {
            let lv = eval(left, ctx)?;
            match op {
                CmpOp::In | CmpOp::NotIn => {
                    let args = match right { Expr::Func { name, args } if name == "in_list" => args.clone(), _ => vec![] };
                    let mut found = false;
                    for a in &args {
                        let rv = eval(a, ctx)?;
                        let eq = match &lv {
                            Val::Str(_) => string_cmp(CmpOp::Eq, &lv.raw_str(), &rv, "", ctx)?,
                            Val::Num(_) => lv.num() == rv.num(),
                            Val::Bool(_) => lv.boolean() == rv.boolean(),
                            _ => false,
                        };
                        if eq { found = true; break; }
                    }
                    Ok(if *op == CmpOp::In { found } else { !found })
                }
                CmpOp::Between => {
                    let args = match right { Expr::Func { name, args } if name == "between_args" => args.clone(), _ => vec![] };
                    if args.len() != 2 { return Ok(false); }
                    let a = eval(&args[0], ctx)?;
                    let b = eval(&args[1], ctx)?;
                    let r1 = compare(CmpOp::Ge, &lv, &a, "", ctx)?;
                    let r2 = compare(CmpOp::Le, &lv, &b, "", ctx)?;
                    Ok(r1 && r2)
                }
                _ => {
                    let rv = eval(right, ctx)?;
                    compare(*op, &lv, &rv, right_text, ctx)
                }
            }
        }
        Cond::Sub { .. } => {
            // handled by the engine
            Ok(false)
        }
    }
}

// ---------------- functions ----------------

fn eval_func(name: &str, args: &[Expr], ctx: &mut EvalCtx) -> EvalResult {
    let canon = functions::canonical(name);
    let mut vals: Vec<Val> = Vec::with_capacity(args.len());
    for a in args {
        vals.push(eval(a, ctx)?);
    }
    match canon {
        "lower" => Ok(Val::Str(vals.first().map(|v| v.raw_str().to_lowercase()).unwrap_or_default())),
        "upper" => Ok(Val::Str(vals.first().map(|v| v.raw_str().to_uppercase()).unwrap_or_default())),
        "init_cap" => Ok(Val::Str(initcap(&vals.first().map(|v| v.raw_str()).unwrap_or_default()))),
        "length" => Ok(Val::Num(vals.first().map(|v| v.raw_str().chars().count() as f64).unwrap_or(0.0))),
        "to_base64" => Ok(Val::Str(crate::b64::encode(vals.first().map(|v| v.raw_str().as_bytes()).unwrap_or(&[])))),
        "from_base64" => {
            let s = vals.first().map(|v| v.raw_str()).unwrap_or_default();
            match crate::b64::decode(&s) {
                Some(d) => Ok(Val::Str(String::from_utf8_lossy(&d).to_string())),
                None => Ok(Val::Null),
            }
        }
        "concat" => Ok(Val::Str(vals.iter().map(|v| v.raw_str()).collect::<Vec<_>>().join(""))),
        "concat_ws" => {
            if vals.is_empty() { return Ok(Val::Null); }
            let sep = vals[0].raw_str();
            Ok(Val::Str(vals[1..].iter().filter(|v| !v.is_null()).map(|v| v.raw_str()).collect::<Vec<_>>().join(&sep)))
        }
        "locate" => {
            if vals.len() < 2 { return rerr("LOCATE requires a search substring"); }
            let hay = vals[0].raw_str();
            let needle = vals[1].raw_str();
            let start = if vals.len() > 2 { vals[2].num().max(1.0) as usize } else { 1 };
            let h: Vec<char> = hay.chars().collect();
            let n: Vec<char> = needle.chars().collect();
            if n.is_empty() { return Ok(Val::Num(0.0)); }
            let mut i = start.saturating_sub(1);
            while i + n.len() <= h.len() {
                if h[i..i + n.len()] == n[..] { return Ok(Val::Num((i + 1) as f64)); }
                i += 1;
            }
            Ok(Val::Num(0.0))
        }
        "substring" => {
            let s: Vec<char> = vals.first().map(|v| v.raw_str().chars().collect()).unwrap_or_default();
            let pos = vals.get(1).map(|v| v.num() as i64).unwrap_or(1);
            let len = vals.get(2).map(|v| v.num() as i64).unwrap_or(-1);
            let start = if pos <= 0 { 0usize } else { (pos - 1).max(0) as usize };
            let start = start.min(s.len());
            let end = if len < 0 { s.len() } else { (start + len.max(0) as usize).min(s.len()) };
            Ok(Val::Str(s[start..end].iter().collect()))
        }
        "replace" => {
            if vals.len() < 3 { return rerr("REPLACE requires two arguments: search string and replacement"); }
            Ok(Val::Str(vals[0].raw_str().replace(&vals[1].raw_str(), &vals[2].raw_str())))
        }
        "trim" => Ok(Val::Str(vals.first().map(|v| v.raw_str().trim().to_string()).unwrap_or_default())),
        "l_trim" => Ok(Val::Str(vals.first().map(|v| v.raw_str().trim_start().to_string()).unwrap_or_default())),
        "r_trim" => Ok(Val::Str(vals.first().map(|v| v.raw_str().trim_end().to_string()).unwrap_or_default())),
        "contains_japanese" => Ok(Val::Bool(has_script(&vals, |c| is_japanese(c)))),
        "contains_hiragana" => Ok(Val::Bool(has_script(&vals, |c| ('\u{3040}'..='\u{309f}').contains(&c)))),
        "contains_katakana" => Ok(Val::Bool(has_script(&vals, |c| ('\u{30a0}'..='\u{30ff}').contains(&c)))),
        "contains_kana" => Ok(Val::Bool(has_script(&vals, |c| ('\u{3040}'..='\u{30ff}').contains(&c)))),
        "contains_kanji" => Ok(Val::Bool(has_script(&vals, |c| ('\u{4e00}'..='\u{9faf}').contains(&c)))),
        "contains_greek" => Ok(Val::Bool(has_script(&vals, |c| ('\u{0370}'..='\u{03ff}').contains(&c)))),
        "bin" => Ok(Val::Str(format!("{:b}", vals.first().map(|v| v.num() as i64).unwrap_or(0)))),
        "hex" => Ok(Val::Str(format!("{:x}", vals.first().map(|v| v.num() as i64).unwrap_or(0)))),
        "oct" => Ok(Val::Str(format!("{:o}", vals.first().map(|v| v.num() as i64).unwrap_or(0)))),
        "abs" => Ok(Val::Num(vals.first().map(|v| v.num().abs()).unwrap_or(0.0))),
        "power" => {
            let a = vals.first().map(|v| v.num()).unwrap_or(0.0);
            let b = vals.get(1).map(|v| v.num()).unwrap_or(0.0);
            Ok(Val::Num(a.powf(b)))
        }
        "sqrt" => {
            let v = vals.first().map(|v| v.num()).unwrap_or(0.0);
            if v < 0.0 { return rerr(&format!("SQRT of a negative number: {}", crate::val::format_num(v))); }
            Ok(Val::Num(v.sqrt()))
        }
        "log" => {
            let v = vals.first().map(|v| v.num()).unwrap_or(0.0);
            if v <= 0.0 { return rerr(&format!("LOG of a non-positive number: {}", crate::val::format_num(v))); }
            let base = if vals.len() > 1 { vals[1].num() } else { 10.0 };
            if base <= 0.0 { return rerr("LOG of a non-positive base"); }
            Ok(Val::Num(v.ln() / base.ln()))
        }
        "ln" => {
            let v = vals.first().map(|v| v.num()).unwrap_or(0.0);
            if v <= 0.0 { return rerr(&format!("LN of a non-positive number: {}", crate::val::format_num(v))); }
            Ok(Val::Num(v.ln()))
        }
        "exp" => Ok(Val::Num(vals.first().map(|v| v.num()).unwrap_or(0.0).exp())),
        "least" => Ok(Val::Num(vals.iter().map(|v| v.num()).fold(f64::INFINITY, f64::min))),
        "greatest" => Ok(Val::Num(vals.iter().map(|v| v.num()).fold(f64::NEG_INFINITY, f64::max))),
        "pi" => Ok(Val::Num(std::f64::consts::PI)),
        "floor" => Ok(Val::Num(vals.first().map(|v| v.num()).unwrap_or(0.0).floor())),
        "ceil" => Ok(Val::Num(vals.first().map(|v| v.num()).unwrap_or(0.0).ceil())),
        "round" => {
            let v = vals.first().map(|v| v.num()).unwrap_or(0.0);
            let digits = if vals.len() > 1 { vals[1].num() as i32 } else { 0 };
            let f = 10f64.powi(digits);
            Ok(Val::Num((v * f).round() / f))
        }
        "random" => {
            let (a, b) = match vals.len() {
                0 => (0.0, i64::MAX as f64),
                1 => (0.0, vals[0].num()),
                _ => (vals[0].num(), vals[1].num()),
            };
            let r = crate::rand::thread_random_f64();
            Ok(Val::Num((a + r * (b - a)).floor()))
        }
        "current_date" => Ok(Val::Str(DateTime::from_epoch(now_epoch() + crate::dates::tz_offset(now_epoch())).date_string())),
        "current_time" => Ok(Val::Str(epoch_to_local(now_epoch()).time_string())),
        "current_timestamp" => Ok(Val::Str(epoch_to_local(now_epoch()).format())),
        "day" => Ok(Val::Num(vals.first().and_then(|v| v.as_date()).map(|ts| epoch_to_local(ts).day as f64).unwrap_or(0.0))),
        "month" => Ok(Val::Num(vals.first().and_then(|v| v.as_date()).map(|ts| epoch_to_local(ts).month as f64).unwrap_or(0.0))),
        "year" => Ok(Val::Num(vals.first().and_then(|v| v.as_date()).map(|ts| epoch_to_local(ts).year as f64).unwrap_or(0.0))),
        "day_of_week" => Ok(Val::Num(vals.first().and_then(|v| v.as_date()).map(|ts| epoch_to_local(ts).dow() as f64).unwrap_or(0.0))),
        "day_name" => {
            let ts = vals.first().and_then(|v| v.as_date()).unwrap_or(0);
            let d = epoch_to_local(ts);
            let idx = ((d.dow() + 6) % 7) as usize;
            Ok(Val::Str(DAY_NAMES[idx].to_string()))
        }
        "day_of_year" => Ok(Val::Num(vals.first().and_then(|v| v.as_date()).map(|ts| epoch_to_local(ts).doy() as f64).unwrap_or(0.0))),
        "date_add" | "date_sub" => {
            if vals.len() < 2 { return rerr(&format!("{} requires a second argument", canon.replace('_', "_").to_uppercase())); }
            let ts = match vals[0].as_date() { Some(t) => t, None => return Ok(Val::Null) };
            let days = vals[1].num() as i64;
            let sign = if canon == "date_add" { 1 } else { -1 };
            Ok(Val::Date(ts + sign * days * 86400))
        }
        "date_diff" => {
            if vals.len() < 2 { return rerr("DATE_DIFF requires a second argument"); }
            let a = match vals[0].as_date() { Some(t) => t, None => return Ok(Val::Null) };
            let b = match vals[1].as_date() { Some(t) => t, None => return Ok(Val::Null) };
            let da = local_to_epoch(&epoch_to_local(a)) / 86400;
            let db = local_to_epoch(&epoch_to_local(b)) / 86400;
            Ok(Val::Num((da - db) as f64))
        }
        "from_unixtime" => {
            let v = vals.first().map(|v| v.num() as i64).unwrap_or(0);
            Ok(Val::Str(epoch_to_local(v).format()))
        }
        "last_day" => {
            let ts = match vals.first().and_then(|v| v.as_date()) { Some(t) => t, None => return Ok(Val::Null) };
            let d = epoch_to_local(ts);
            let last = days_in_month(d.year, d.month);
            Ok(Val::Str(format!("{:04}-{:02}-{:02}", d.year, d.month, last)))
        }
        "format_size" => {
            let size = vals.first().map(|v| v.num()).unwrap_or(0.0) as u64;
            let spec = vals.get(1).map(|v| v.raw_str()).unwrap_or_default();
            Ok(Val::Str(crate::fmtsize::format_size_spec(size, &spec)))
        }
        "format_time" => {
            let v = vals.first().map(|v| v.num()).unwrap_or(0.0) as u64;
            Ok(Val::Str(crate::fmtsize::format_time(v)))
        }
        "current_uid" => Ok(Val::Num(crate::fsx::current_uid() as f64)),
        "current_gid" => Ok(Val::Num(crate::fsx::current_gid() as f64)),
        "current_user" => Ok(Val::Str(crate::fsx::user_name(crate::fsx::current_uid()))),
        "current_group" => Ok(Val::Str(crate::fsx::group_name(crate::fsx::current_gid()))),
        "contains" => {
            if vals.is_empty() { return Ok(Val::Null); }
            let needle = vals[0].raw_str();
            let data = read_content(ctx.entry)?;
            Ok(Val::Bool(String::from_utf8_lossy(&data).contains(&needle)))
        }
        "coalesce" => {
            for v in &vals {
                if !v.is_null() { return Ok(v.clone()); }
            }
            Ok(Val::Null)
        }
        "has_xattr" | "xattr" | "has_extattr" | "has_acl_entry" | "acl_entry" | "has_default_acl_entry" | "default_acl_entry" | "has_capability" => {
            let arg = vals.first().map(|v| v.raw_str()).unwrap_or_default();
            let list = crate::columns::xattr_list(ctx.entry);
            match canon {
                "has_xattr" => Ok(Val::Bool(list.map(|l| l.iter().any(|(n, _)| n == &arg)).unwrap_or(false))),
                "xattr" => Ok(Val::Str(list.and_then(|l| l.into_iter().find(|(n, _)| n == &arg)).map(|(_, v)| v).unwrap_or_default())),
                "has_extattr" => Ok(Val::Bool(crate::fsx::has_extattr_flag(&ctx.entry.path, &arg).unwrap_or(false))),
                _ => Ok(Val::Null),
            }
        }
        _ => Ok(Val::Null),
    }
}

fn has_script(vals: &[Val], f: impl Fn(char) -> bool) -> bool {
    vals.iter().any(|v| v.raw_str().chars().any(f))
}

fn is_japanese(c: char) -> bool {
    ('\u{3040}'..='\u{30ff}').contains(&c) || ('\u{4e00}'..='\u{9faf}').contains(&c) || ('\u{ff66}'..='\u{ff9d}').contains(&c)
}

pub fn initcap(s: &str) -> String {
    let mut out = String::new();
    let mut new_word = true;
    for c in s.chars() {
        if c.is_alphanumeric() {
            if new_word { out.extend(c.to_uppercase()); new_word = false; } else { out.extend(c.to_lowercase()); }
        } else {
            out.push(c);
            new_word = true;
        }
    }
    out
}

fn read_content(entry: &Entry) -> Result<Vec<u8>, (String, bool)> {
    match std::fs::read(&entry.path) {
        Ok(d) => Ok(d),
        Err(_) => Ok(Vec::new()),
    }
}

// ---------------- aggregates ----------------

#[derive(Clone, Debug, Default)]
pub struct AggState {
    pub count: u64,
    pub sum: f64,
    pub sumsq: f64,
    pub min: f64,
    pub max: f64,
    pub has: bool,
    pub min_str: Option<String>,
    pub max_str: Option<String>,
}

impl AggState {
    pub fn feed(&mut self, v: &Val) {
        self.count += 1;
        self.has = true;
        let n = v.num();
        if !self.has_min_max() { self.min = n; self.max = n; }
        self.min = self.min.min(n);
        self.max = self.max.max(n);
        self.sum += n;
        self.sumsq += n * n;
        match v {
            Val::Str(s) => {
                if self.min_str.is_none() || s < self.min_str.as_ref().unwrap() { self.min_str = Some(s.clone()); }
                if self.max_str.is_none() || s > self.max_str.as_ref().unwrap() { self.max_str = Some(s.clone()); }
            }
            _ => {}
        }
    }
    fn has_min_max(&self) -> bool { false }

    pub fn value(&self, canon: &str) -> Val {
        match canon {
            "count" => Val::Num(self.count as f64),
            "sum" => Val::Num(self.sum),
            "avg" => Val::Num(if self.count == 0 { 0.0 } else { self.sum / self.count as f64 }),
            "min" => Val::Num(if self.has { self.min } else { 0.0 }),
            "max" => Val::Num(if self.has { self.max } else { 0.0 }),
            "var_pop" => {
                if self.count == 0 { return Val::Num(0.0); }
                let mean = self.sum / self.count as f64;
                Val::Num(self.sumsq / self.count as f64 - mean * mean)
            }
            "var_samp" => {
                if self.count == 0 { return Val::Num(0.0); }
                let mean = self.sum / self.count as f64;
                Val::Num((self.sumsq - mean * self.sum) / (self.count as f64 - 1.0))
            }
            "stddev_pop" => {
                if self.count == 0 { return Val::Num(0.0); }
                let mean = self.sum / self.count as f64;
                Val::Num((self.sumsq / self.count as f64 - mean * mean).sqrt())
            }
            "stddev_samp" => {
                if self.count <= 1 { return Val::Num(0.0); }
                let mean = self.sum / self.count as f64;
                Val::Num(((self.sumsq - mean * self.sum) / (self.count as f64 - 1.0)).sqrt())
            }
            _ => Val::Null,
        }
    }
}

pub struct AggEngine {
    pub groups: Vec<AggGroup>,
    pub index: std::collections::HashMap<Vec<String>, usize>,
}

#[derive(Default)]
pub struct AggGroup {
    pub key: Vec<Val>,
    pub aggs: std::collections::HashMap<String, AggState>,
    pub order: usize,
}

impl AggEngine {
    pub fn new() -> AggEngine {
        AggEngine { groups: Vec::new(), index: std::collections::HashMap::new() }
    }
    pub fn group_for(&mut self, key: &[Val]) -> usize {
        let k: Vec<String> = key.iter().map(|v| v.to_str()).collect();
        if let Some(i) = self.index.get(&k) { return *i; }
        let g = AggGroup { key: key.to_vec(), aggs: std::collections::HashMap::new(), order: self.groups.len() };
        self.groups.push(g);
        let i = self.groups.len() - 1;
        self.index.insert(k, i);
        i
    }
}

pub fn agg_key_of(e: &Expr) -> String {
    crate::parse::display_name(e)
}

pub fn collect_aggs(e: &Expr, out: &mut Vec<String>) {
    match e {
        Expr::Func { name, args } => {
            if functions::is_aggregate(name) {
                out.push(agg_key_of(e));
                return;
            }
            for a in args { collect_aggs(a, out); }
        }
        Expr::Arith { l, r, .. } => { collect_aggs(l, out); collect_aggs(r, out); }
        _ => {}
    }
}

pub fn field_aggs(q: &Query) -> Vec<String> {
    let mut v = Vec::new();
    for f in &q.fields { collect_aggs(&f.expr, &mut v); }
    for o in &q.order_by { collect_aggs(&o.expr, &mut v); }
    v
}
