#[derive(Clone, Debug, Default)]
pub struct AggState {
    pub count: u64,
    pub sum: f64,
    pub sumsq: f64,
    pub min: f64,
    pub max: f64,
    pub has: bool,
    pub min_str: Option<String>,
    pub max_str: Option<String>,
}

impl AggState {
    pub fn feed(&mut self, v: &Val) {
        self.count += 1;
        self.has = true;
        let n = v.num();
        if !self.has_min_max() { self.min = n; self.max = n; }
        self.min = self.min.min(n);
        self.max = self.max.max(n);
        self.sum += n;
        self.sumsq += n * n;
        match v {
            Val::Str(s) => {
                if self.min_str.is_none() || s < self.min_str.as_ref().unwrap() { self.min_str = Some(s.clone()); }
                if self.max_str.is_none() || s > self.max_str.as_ref().unwrap() { self.max_str = Some(s.clone()); }
            }
            _ => {}
        }
    }
    fn has_min_max(&self) -> bool { false }

    pub fn value(&self, canon: &str) -> Val {
        match canon {
            "count" => Val::Num(self.count as f64),
            "sum" => Val::Num(self.sum),
            "avg" => Val::Num(if self.count == 0 { 0.0 } else { self.sum / self.count as f64 }),
            "min" => Val::Num(if self.has { self.min } else { 0.0 }),
            "max" => Val::Num(if self.has { self.max } else { 0.0 }),
            "var_pop" => {
                if self.count == 0 { return Val::Num(0.0); }
                let mean = self.sum / self.count as f64;
                Val::Num(self.sumsq / self.count as f64 - mean * mean)
            }
            "var_samp" => {
                if self.count == 0 { return Val::Num(0.0); }
                let mean = self.sum / self.count as f64;
                Val::Num((self.sumsq - mean * self.sum) / (self.count as f64 - 1.0))
            }
            "stddev_pop" => {
                if self.count == 0 { return Val::Num(0.0); }
                let mean = self.sum / self.count as f64;
                Val::Num((self.sumsq / self.count as f64 - mean * mean).sqrt())
            }
            "stddev_samp" => {
                if self.count <= 1 { return Val::Num(0.0); }
                let mean = self.sum / self.count as f64;
                Val::Num(((self.sumsq - mean * self.sum) / (self.count as f64 - 1.0)).sqrt())
            }
            _ => Val::Null,
        }
    }
}

pub struct AggEngine {
    pub groups: Vec<AggGroup>,
    pub index: std::collections::HashMap<Vec<String>, usize>,
}

#[derive(Default)]
pub struct AggGroup {
    pub key: Vec<Val>,
    pub aggs: std::collections::HashMap<String, AggState>,
    pub order: usize,
}

impl AggEngine {
    pub fn new() -> AggEngine {
        AggEngine { groups: Vec::new(), index: std::collections::HashMap::new() }
    }
    pub fn group_for(&mut self, key: &[Val]) -> usize {
        let k: Vec<String> = key.iter().map(|v| v.to_str()).collect();
        if let Some(i) = self.index.get(&k) { return *i; }
        let g = AggGroup { key: key.to_vec(), aggs: std::collections::HashMap::new(), order: self.groups.len() };
        self.groups.push(g);
        let i = self.groups.len() - 1;
        self.index.insert(k, i);
        i
    }
}

pub fn agg_key_of(e: &Expr) -> String {
    crate::parse::display_name(e)
}

pub fn collect_aggs(e: &Expr, out: &mut Vec<String>) {
    match e {
        Expr::Func { name, args } => {
            if functions::is_aggregate(name) {
                out.push(agg_key_of(e));
                return;
            }
            for a in args { collect_aggs(a, out); }
        }
        Expr::Arith { l, r, .. } => { collect_aggs(l, out); collect_aggs(r, out); }
        _ => {}
    }
}

pub fn field_aggs(q: &Query) -> Vec<String> {
    let mut v = Vec::new();
    for f in &q.fields { collect_aggs(&f.expr, &mut v); }
    for o in &q.order_by { collect_aggs(&o.expr, &mut v); }
    v
}
