    t ^ addr.rotate_left(17) ^ (std::process::id() as u64).rotate_left(7)
}

pub fn next_u64() -> u64 {
    STATE.with(|s| {
        let mut x = s.get();
        if x == 0 { x = seed() | 1; }
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        s.set(x);
        x
    })
}

