        format!("{:.*}", precision, x)
    }
}

pub fn format_size_spec(bytes: u64, spec_str: &str) -> String {
    let spec = match parse_spec(spec_str) {
        Ok(s) => s,
        Err(_) => return String::new(),
    };
    let names = unit_names(&spec);
    let div = if spec.decimal { 1000.0 } else { 1024.0 };
    let idx = match spec.unit {
        Some(u) => u,
        None => {
            let mut u = 0usize;
            let mut v = bytes as f64;
            while u + 1 < names.len() && v >= div {
                v /= div;
                u += 1;
            }
            u
        }
    };
    let value = if idx == 0 { bytes as f64 } else { (bytes as f64) / div.powi(idx as i32) };
    let txt = fmt_value(value, spec.precision);
    let sep = if spec.space && idx > 0 { " " } else { "" };
    format!("{}{}{}", txt, sep, names[idx])
}

/// Default (no format specifier) human readable size
pub fn format_size(bytes: u64, spec: &str) -> String {
    if spec.is_empty() {
        if bytes < 1024 {
            return format!("{}B", bytes);
        }
        let mut idx = 0usize;
        let mut v = bytes as f64;
        while idx + 1 < BINARY_UNITS.len() && v >= 1024.0 {
            v /= 1024.0;
            idx += 1;
        }
        return format!("{}{}", fmt_value(v, 2), BINARY_UNITS[idx]);
    }
    format_size_spec(bytes, spec)
}

pub fn format_time(secs: u64) -> String {
    let d = secs / 86400;
    let h = (secs % 86400) / 3600;
    let m = (secs % 3600) / 60;
    let s = secs % 60;
    let mut parts: Vec<String> = Vec::new();
    if d > 0 { parts.push(format!("{}d", d)); }
    if h > 0 { parts.push(format!("{}h", h)); }
    if m > 0 { parts.push(format!("{}m", m)); }
    if s > 0 { parts.push(format!("{}s", s)); }
    if parts.is_empty() { return "0\u{3bc}s".to_string(); }
    parts.join(",")
}
