use std::cell::Cell;
thread_local! {
    static STATE: Cell<u64> = Cell::new(0);
}

fn seed() -> u64 {
    let t = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_nanos() as u64).unwrap_or(12345);
    let addr = &t as *const u64 as u64;
    t ^ addr.rotate_left(17) ^ (std::process::id() as u64).rotate_left(7)
