pub fn next_u64() -> u64 {
    STATE.with(|s| {
        let mut x = s.get();
        if x == 0 { x = seed() | 1; }
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        s.set(x);
        x
    })
}

pub fn thread_random_f64() -> f64 {
    (next_u64() >> 11) as f64 / (1u64 << 53) as f64
}
