    0x8000000080008081, 0x8000000000008080, 0x0000000080000001, 0x8000000080008008,
];

fn keccak_f(state: &mut [u64; 25]) {
    const R: [u32; 24] = [1,3,6,10,15,21,28,36,45,55,2,14,27,41,56,8,25,43,62,18,39,61,20,44];
    const PIL: [usize; 24] = [10,7,11,17,18,3,5,16,8,21,24,4,15,23,19,13,12,2,20,14,22,9,6,1];
    for round in 0..24 {
        // theta
        let mut c = [0u64; 5];
        for x in 0..5 { c[x] = state[x] ^ state[x + 5] ^ state[x + 10] ^ state[x + 15] ^ state[x + 20]; }
        let mut d = [0u64; 5];
        for x in 0..5 {
            d[x] = c[(x + 4) % 5] ^ c[(x + 1) % 5].rotate_left(1);
        }
        for y in 0..5 {
            for x in 0..5 { state[y * 5 + x] ^= d[x]; }
        }
        // rho and pi
        let mut b = [0u64; 25];
        for x in 0..5 {
            for y in 0..5 {
                let idx = y * 5 + x;
                let nidx = x * 5 + ((2 * y + 3 * x) % 5);
                b[nidx] = state[idx].rotate_left(R[(x * 5 + y) % 24]);
            }
        }
        // chi
        for y in 0..5 {
            for x in 0..5 {
                state[y * 5 + x] = b[y * 5 + x] ^ ((!b[y * 5 + (x + 1) % 5]) & b[y * 5 + (x + 2) % 5]);
            }
        }
        // iota
        state[0] ^= RC[round];
    }
}

pub fn sha3_512(data: &[u8]) -> [u8; 64] {
    let rate = 72usize;
    let mut state = [0u64; 25];
    let mut buf = data.to_vec();
    // padding 0x06 ... 0x80
    buf.push(0x06);
    while buf.len() % rate != 0 { buf.push(0); }
    let last = buf.len() - 1;
    buf[last] |= 0x80;
    for block in buf.chunks(rate) {
        for i in 0..rate / 8 {
            let mut w = [0u8; 8];
            w.copy_from_slice(&block[i * 8..i * 8 + 8]);
            state[i] ^= u64::from_le_bytes(w);
        }
        keccak_f(&mut state);
    }
    let mut out = [0u8; 64];
    for i in 0..8 {
        out[i * 8..i * 8 + 8].copy_from_slice(&state[i].to_le_bytes());
    }
    out
}
