pub fn detect(entry: &mut Entry) -> String {
    if entry.is_dir { return "inode/directory".into(); }
    if !entry.is_file && !entry.is_symlink { return String::new(); }
    if let Some(c) = entry.mime.borrow_mut().as_ref() { return c.clone().unwrap_or_default(); }
    let data = match std::fs::read(&entry.path) { Ok(d) => d, Err(_) => { entry.mime.borrow_mut().replace(Some(String::new())); return String::new(); } };
    let m = detect_bytes(&data);
    entry.mime.borrow_mut().replace(Some(m.clone()));
    m
}

pub fn detect_bytes(data: &[u8]) -> String {
    if data.is_empty() { return "text/plain".into(); }
    let head = &data[..data.len().min(4096)];
    for m in BIN_MAGICS {
        if head.len() >= m.off + m.bytes.len() && &head[m.off..m.off + m.bytes.len()] == m.bytes {
            return m.mime.to_string();
        }
    }
    let s = String::from_utf8_lossy(head);
    if looks_like_text(head) {
        for t in TEXT_MAGICS {
            if s.starts_with(t.pat) { return t.mime.to_string(); }
        }
        return "text/plain".into();
    }
    "application/octet-stream".into()
}

pub fn looks_like_text(data: &[u8]) -> bool {
    if data.is_empty() { return true; }
    let n = data.len().min(8192);
    let mut bad = 0u64;
    for &b in &data[..n] {
        if b < 0x08 || (0x0e..=0x1a).contains(&b) || (0x1c..=0x1f).contains(&b) || b == 0x7f {
            bad += 1;
        }
    }
    bad * 100 < n as u64 * 30
}

pub fn is_text_mime(m: &str) -> bool {
    if m.starts_with("text/") { return true; }
    matches!(m, "application/x-shellscript" | "application/x-perl" | "application/x-ruby" | "application/x-awk" | "application/x-php" | "application/x-lua")
}
