// Image / video dimension detection
use crate::fsx::Entry;

pub fn dimensions(entry: &mut Entry) -> (Option<u32>, Option<u32>) {
    let cached_w = entry.width.borrow().clone();
    let cached_h = entry.height.borrow().clone();
    if let (Some(w), Some(h)) = (cached_w, cached_h) { return (w, h); }
    let r = if entry.is_dir { None } else { std::fs::read(&entry.path).ok().map(|d| dims_from_bytes(&d)) };
    let (w, h) = match r { Some(Some((w, h))) => (Some(w), Some(h)), _ => (None, None) };
    *entry.width.borrow_mut() = Some(w);
    *entry.height.borrow_mut() = Some(h);
    (w, h)
}

pub fn dims_from_bytes(d: &[u8]) -> Option<(u32, u32)> {
    if d.len() < 8 { return None; }
    if d.starts_with(b"\x89PNG\r\n\x1a\n") { return png_dims(d); }
    if d.starts_with(b"\xff\xd8\xff") { return jpeg_dims(d); }
    if d.starts_with(b"GIF87a") || d.starts_with(b"GIF89a") {
        if d.len() >= 10 { return Some((u16le(d, 6) as u32, u16le(d, 8) as u32)); }
    }
    if d.starts_with(b"BM") { return bmp_dims(d); }
    if d.starts_with(b"II*\x00") || d.starts_with(b"MM\x00*") { return tiff_dims(d); }
    if d.len() > 12 && &d[0..4] == b"RIFF" && &d[8..12] == b"WEBP" { return webp_dims(d); }
    if d.starts_with(b"\x00\x00\x01\x00") || d.starts_with(b"\x00\x00\x02\x00") {
        if d.len() >= 8 { return Some((d[6] as u32, d[7] as u32)); }
    }
    if d[0] == b'P' && d.len() > 2 && (b'1'..=b'6').contains(&d[1]) { return pnm_dims(d); }
    if d.len() >= 12 && &d[4..8] == b"ftyp" { return mp4_dims(d); }
    None
}

fn u16le(d: &[u8], o: usize) -> u16 { (d[o] as u16) | ((d[o + 1] as u16) << 8) }
fn u32le(d: &[u8], o: usize) -> u32 { u32::from_le_bytes([d[o], d[o+1], d[o+2], d[o+3]]) }
fn u16be(d: &[u8], o: usize) -> u16 { ((d[o] as u16) << 8) | d[o+1] as u16 }
fn u32be(d: &[u8], o: usize) -> u32 { u32::from_be_bytes([d[o], d[o+1], d[o+2], d[o+3]]) }

fn png_dims(d: &[u8]) -> Option<(u32, u32)> {
    // scan chunks for IHDR
    let mut i = 8usize;
    while i + 8 <= d.len() {
        let len = u32be(d, i) as usize;
        if &d[i + 4..i + 8] == b"IHDR" {
            if i + 8 + 13 <= d.len() {
                let w = u32be(d, i + 8);
                let h = u32be(d, i + 12);
                return Some((w, h));
            }
        }
        i += 12 + len;
        if len == 0 { break; }
    }
    None
}

fn jpeg_dims(d: &[u8]) -> Option<(u32, u32)> {
    let mut i = 2usize;
    while i + 4 <= d.len() {
        if d[i] != 0xff { i += 1; continue; }
        let marker = d[i + 1];
        if marker == 0xd8 || marker == 0x01 || (0xd0..=0xd7).contains(&marker) { i += 2; continue; }
        if marker == 0xd9 { break; }
        let len = u16be(d, i + 2) as usize;
        if (0xc0..=0xcf).contains(&marker) && marker != 0xc4 && marker != 0xc8 && marker != 0xcc {
            if i + 2 + 7 <= d.len() {
                let h = u16be(d, i + 5) as u32;
                let w = u16be(d, i + 7) as u32;
                return Some((w, h));
            }
        }
        i += 2 + len;
    }
    None
}

fn bmp_dims(d: &[u8]) -> Option<(u32, u32)> {
    if d.len() < 26 { return None; }
    let hdr = u32le(d, 14);
    if hdr < 12 { return None; }
    if hdr == 12 {
        let w = u16le(d, 18) as u32;
        let h = u16le(d, 20) as u32;
        return Some((w, h));
    }
    let w = u32le(d, 18);
    let hraw = u32le(d, 22) as i32;
    Some((w, hraw.unsigned_abs()))
}

fn tiff_dims(d: &[u8]) -> Option<(u32, u32)> {
    let le = d[0] == b'I';
    if d.len() < 8 { return None; }
    let ifd = if le { u32le(d, 4) as usize } else { u32be(d, 4) as usize };
    if ifd + 2 > d.len() { return None; }
    let n = if le { u16le(d, ifd) as usize } else { u16be(d, ifd) as usize };
    let mut w = None;
    let mut h = None;
    for i in 0..n {
        let off = ifd + 2 + i * 12;
        if off + 12 > d.len() { break; }
        let tag = if le { u16le(d, off) } else { u16be(d, off) };
        let typ = if le { u16le(d, off + 2) } else { u16be(d, off + 2) };
        let val = if le { u32le(d, off + 8) } else { u32be(d, off + 8) };
        let v = match typ {
            3 => if le { (val & 0xffff) as u32 } else { (val >> 16) as u32 },
            4 => val,
            _ => val,
        };
        if tag == 256 { w = Some(v); }
        if tag == 257 { h = Some(v); }
    }
    match (w, h) { (Some(a), Some(b)) => Some((a, b)), _ => None }
}

fn webp_dims(d: &[u8]) -> Option<(u32, u32)> {
    if d.len() < 30 { return None; }
    let fourcc = &d[12..16];
    if fourcc == b"VP8 " {
        // lossy: after the chunk header (8 bytes) -> 3 bytes frame tag, then 3 bytes sync, then w/h
        if d.len() >= 30 {
            let w = (u16le(d, 26) & 0x3fff) as u32;
            let h = (u16le(d, 28) & 0x3fff) as u32;
            return Some((w, h));
        }
    } else if fourcc == b"VP8L" {
        if d.len() >= 25 {
            let bits = u32le(d, 21);
            let w = (bits & 0x3fff) + 1;
            let h = ((bits >> 14) & 0x3fff) + 1;
            return Some((w, h));
        }
    } else if fourcc == b"VP8X" {
        if d.len() >= 30 {
            let w = (d[24] as u32) | ((d[25] as u32) << 8) | ((d[26] as u32) << 16);
            let h = (d[27] as u32) | ((d[28] as u32) << 8) | ((d[29] as u32) << 16);
            return Some((w + 1, h + 1));
        }
    }
    None
}

fn pnm_dims(d: &[u8]) -> Option<(u32, u32)> {
    // parse header: P<n> whitespace width height maxval
    let mut i = 2usize;
    let mut vals: Vec<u32> = Vec::new();
    let mut cur = String::new();
    let mut comment = false;
    while i < d.len() && vals.len() < 2 {
        let c = d[i] as char;
        if comment {
            if c == '\n' { comment = false; }
            i += 1;
            continue;
        }
        if c == '#' { comment = true; i += 1; continue; }
        if c.is_whitespace() {
            if !cur.is_empty() { if let Ok(v) = cur.parse::<u32>() { vals.push(v); } cur.clear(); }
        } else { cur.push(c); }
        i += 1;
    }
    if vals.len() >= 2 { return Some((vals[0], vals[1])); }
    None
}

fn mp4_dims(d: &[u8]) -> Option<(u32, u32)> {
    // walk boxes looking for tkhd or the video sample description
    let mut i = 0usize;
    while i + 8 <= d.len() {
        let size = u32be(d, i) as usize;
        if size < 8 { break; }
        let ty = &d[i + 4..i + 8];
        if ty == b"moov" || ty == b"trak" || ty == b"mdia" || ty == b"minf" || ty == b"stbl" {
            if let Some(r) = mp4_dims(&d[i + 8..(i + size).min(d.len())]) { return Some(r); }
        } else if ty == b"tkhd" {
            if i + 8 + 84 <= d.len() {
                let ver = d[i + 8];
                let off = if ver == 1 { i + 8 + 4 + 16 + 4 + 8 + 8 + 4 + 60 } else { i + 8 + 4 + 8 + 4 + 8 + 4 + 52 };
                if off + 8 <= d.len() {
                    let w = u32be(d, off) >> 16;
                    let h = u32be(d, off + 4) >> 16;
                    if w > 0 && h > 0 { return Some((w, h)); }
                }
            }
        } else if ty == b"avc1" || ty == b"mp4v" || ty == b"hvc1" || ty == b"hev1" {
            if i + 8 + 32 <= d.len() {
                let w = u16be(d, i + 8 + 24) as u32;
                let h = u16be(d, i + 8 + 26) as u32;
                if w > 0 && h > 0 { return Some((w, h)); }
            }
        }
        i += size;
    }
    None
}
