// Minimal MP3 metadata parsing (ID3v1/v2 tags plus MPEG frame info)
use crate::fsx::{Entry, Tags};

pub struct Mp3Info {
    pub duration: Option<f64>,
    pub bitrate: Option<u32>,
    pub freq: Option<u32>,
    pub tags: Tags,
    pub width: Option<u32>,
    pub height: Option<u32>,
}

impl Default for Mp3Info { fn default() -> Self { Mp3Info { duration: None, bitrate: None, freq: None, tags: Tags::default(), width: None, height: None } } }

const BITRATES_V1L3: [u32; 16] = [0,32,40,48,56,64,80,96,112,128,160,192,224,256,320,0];
const BITRATES_V1L2: [u32; 16] = [0,32,48,56,64,80,96,112,128,160,192,224,256,320,384,0];
const BITRATES_V1L1: [u32; 16] = [0,32,64,96,128,160,192,224,256,288,320,352,384,416,448,0];
const BITRATES_V2: [u32; 16] = [0,8,16,24,32,40,48,56,64,80,96,112,128,144,160,0];
const RATES_V1: [u32; 4] = [44100,48000,32000,0];
const RATES_V2: [u32; 4] = [22050,24000,16000,0];

pub fn info(entry: &mut Entry) -> Mp3Info {
    let cached_d = entry.duration.borrow().clone();
    let cached_b = entry.bitrate.borrow().clone();
    let cached_f = entry.freq.borrow().clone();
    let cached_t = entry.tags.borrow().clone();
    if cached_d.is_some() && cached_b.is_some() && cached_f.is_some() && cached_t.is_some() {
        let t = cached_t.unwrap_or_default();
        return Mp3Info { duration: cached_d.unwrap(), bitrate: cached_b.unwrap(), freq: cached_f.unwrap(), tags: t, width: None, height: None };
    }
    let data = if entry.is_dir { Vec::new() } else { std::fs::read(&entry.path).unwrap_or_default() };
    let r = parse(&data);
    *entry.duration.borrow_mut() = Some(r.duration);
    *entry.bitrate.borrow_mut() = Some(r.bitrate);
    *entry.freq.borrow_mut() = Some(r.freq);
    *entry.tags.borrow_mut() = Some(r.tags.clone());
    Mp3Info { duration: r.duration, bitrate: r.bitrate, freq: r.freq, tags: r.tags, width: None, height: None }
}

fn parse(data: &[u8]) -> Mp3Info {
    let mut out = Mp3Info::default();
    let mut audio_start = 0usize;
    let mut tag_size = 0usize;
    if data.len() > 10 && &data[0..3] == b"ID3" {
        let ver = data[3];
        let flags = data[5];
        let sz = ((data[6] as usize & 0x7f) << 21) | ((data[7] as usize & 0x7f) << 14) | ((data[8] as usize & 0x7f) << 7) | (data[9] as usize & 0x7f);
        tag_size = 10 + sz;
        audio_start = tag_size;
        if flags & 0x10 != 0 { audio_start += 10; }
        parse_id3v2(&data[10..(10 + sz).min(data.len())], ver, &mut out.tags);
    }
    if out.tags.title.is_none() && data.len() >= 128 {
        let tail = &data[data.len() - 128..];
        if &tail[0..3] == b"TAG" {
            out.tags.title = Some(trim_nul(&tail[3..33]));
            out.tags.artist = Some(trim_nul(&tail[33..63]));
            out.tags.album = Some(trim_nul(&tail[63..93]));
            out.tags.year = Some(trim_nul(&tail[93..97]).parse::<u32>().unwrap_or(0));
            out.tags.genre = Some(genre_name(tail[127] as usize));
        }
    }
    // find the first frame header
    let mut i = audio_start;
    let mut found = false;
    while i + 4 <= data.len() {
        if data[i] == 0xff && (data[i + 1] & 0xe0) == 0xe0 {
            let hdr = &data[i..i + 4];
            let ver = (hdr[1] >> 3) & 0x3;
            let layer = (hdr[1] >> 1) & 0x3;
            let br_idx = (hdr[2] >> 4) & 0xf;
            let sr_idx = (hdr[2] >> 2) & 0x3;
            let padding = (hdr[2] >> 1) & 1;
            let bitrate = match (ver, layer) {
                (3, 3) => BITRATES_V1L1[br_idx as usize],
                (3, 2) => BITRATES_V1L2[br_idx as usize],
                (3, 1) => BITRATES_V1L3[br_idx as usize],
                (_, 3) => BITRATES_V2[br_idx as usize] * 2,
                (_, 2) => BITRATES_V2[br_idx as usize] * 2,
                (_, 1) => BITRATES_V2[br_idx as usize],
                _ => 0,
            };
            let rates = if ver == 3 { RATES_V1 } else { RATES_V2 };
            let mut sr = rates[sr_idx as usize];
            if ver == 2 { sr /= 2; }
            if ver == 0 { sr /= 4; }
            if bitrate > 0 && sr > 0 {
                out.bitrate = Some(bitrate);
                out.freq = Some(sr);
                let frame_len = match layer {
                    3 => 144 * bitrate * 1000 / sr + padding as usize,
                    2 => 144 * bitrate * 1000 / sr + padding as usize,
                    _ => (12 * bitrate * 1000 / sr + padding as usize) * 4,
                };
                let samples = match layer { 1 => 384, 2 => 1152, _ => 1152 };
                // count frames
                let mut p = i;
                let mut frames = 0u64;
                while p + 4 <= data.len() {
                    if data[p] == 0xff && (data[p + 1] & 0xe0) == 0xe0 {
                        let b2 = data[p + 2];
                        let pad = if (b2 >> 1) & 1 == 1 { 1 } else { 0 };
                        let fl = match layer {
                            1 => (12 * bitrate * 1000 / sr + pad) * 4,
                            _ => 144 * bitrate * 1000 / sr + pad,
                        };
                        if fl == 0 { break; }
                        frames += 1;
                        p += fl;
                    } else { p += 1; }
                }
                out.duration = Some(frames as f64 * samples as f64 / sr as f64);
                found = true;
            }
            break;
        }
        i += 1;
    }
    if !found {
        // fall back to a bitrate estimate
        let audio_len = data.len().saturating_sub(audio_start);
        if audio_len > 0 && audio_start > 0 {
            // assume 128kbps
            out.bitrate = Some(128);
            out.duration = Some(audio_len as f64 * 8.0 / (128.0 * 1000.0));
        }
    }
    out
}

fn trim_nul(b: &[u8]) -> String {
    let s: Vec<u8> = b.iter().copied().take_while(|c| *c != 0).collect();
    String::from_utf8_lossy(&s).trim().to_string()
}

const GENRES: [&str; 80] = ["Blues","ClassicRock","Country","Dance","Disco","Funk","Grunge","HipHop","Jazz","Metal","NewAge","Oldies","Other","Pop","R&B","Rap","Reggae","Rock","Techno","Industrial","Alternative","Ska","DeathMetal","Pranks","Soundtrack","EuroTechno","Ambient","TripHop","Vocal","Jazz&Funk","Fusion","Trance","Classical","Instrumental","Acid","House","Game","SoundClip","Bible","Rock/Pop","Gangsta","Video","Musical","RockContemporary","Club","Tango","Samba","Folklore","Ballad","PowerBallad","RhythmicSoul","Freestyle","Duet","PunkRock","DrumSolo","Acapella","EuroHouse","DanceHall","Goa","Drum&Bass","Club-House","Proto-Punk","Psychedelic","Experimental","ElectroPop","ModernCountry","Silva","BluesCore","Astral","ElectroJazz","NationalPop","IndustrialAlt","LoFiHipHop","TerrorCore","JazzCore","MathRock","DigitalHardcore","FusionRock","JazzFusion"];

pub fn genre_name(i: usize) -> String {
    GENRES.get(i).map(|s| s.to_string()).unwrap_or_default()
}

fn parse_id3v2(d: &[u8], ver: u8, tags: &mut Tags) {
    let mut i = 0usize;
    let is_v2_2 = ver == 2;
    while i + 10 <= d.len() {
        if d[i] == 0 { break; }
        let id = if is_v2_2 {
            String::from_utf8_lossy(&d[i..i + 3]).to_string()
        } else {
            String::from_utf8_lossy(&d[i..i + 4]).to_string()
        };
        let size = if is_v2_2 {
            ((d[i + 3] as usize) << 16) | ((d[i + 4] as usize) << 8) | (d[i + 5] as usize)
        } else if ver == 4 {
            ((d[i + 4] as usize & 0x7f) << 21) | ((d[i + 5] as usize & 0x7f) << 14) | ((d[i + 6] as usize & 0x7f) << 7) | (d[i + 7] as usize & 0x7f)
        } else {
            u32::from_be_bytes([d[i + 4], d[i + 5], d[i + 6], d[i + 7]]) as usize
        };
        let hdr_len = if is_v2_2 { 6 } else { 10 };
        if size == 0 || i + hdr_len + size > d.len() { break; }
        let content = &d[i + hdr_len..i + hdr_len + size];
        let text = decode_text(content);
        match id.as_str() {
            "TIT2" | "TT2" => tags.title = Some(text),
            "TPE1" | "TP1" => tags.artist = Some(text),
            "TALB" | "TAL" => tags.album = Some(text),
            "TCON" | "TCO" => tags.genre = Some(clean_genre(&text)),
            "TYER" | "TDRC" | "TYE" => tags.year = Some(text.trim().parse::<u32>().unwrap_or(0)),
            _ => {}
        }
        i += hdr_len + size;
    }
}

fn clean_genre(s: &str) -> String {
    let t = s.trim();
    if let Some(p) = t.find(|c: char| !c.is_ascii_digit()) {
        if p > 0 {
            let idx: usize = t[..p].parse().unwrap_or(0);
            let rest = t[p..].trim_start_matches(|c: char| c == '(' || c == ')').trim().to_string();
            if rest.is_empty() { return genre_name(idx); }
            return rest;
        }
    }
    if let Ok(idx) = t.parse::<usize>() { return genre_name(idx); }
    t.to_string()
}

fn decode_text(d: &[u8]) -> String {
    if d.is_empty() { return String::new(); }
    match d[0] {
        0 => String::from_utf8_lossy(&d[1..]).trim_matches('\0').to_string(),
        1 => {
            if d.len() >= 3 && d[1] == 0xff && d[2] == 0xfe {
                let s: Vec<u16> = d[3..].chunks(2).filter(|c| c.len() == 2).map(|c| u16::from_le_bytes([c[0], c[1]])).collect();
                String::from_utf16_lossy(&s).trim_matches('\0').to_string()
            } else if d.len() >= 3 && d[1] == 0xfe && d[2] == 0xff {
                let s: Vec<u16> = d[3..].chunks(2).filter(|c| c.len() == 2).map(|c| u16::from_be_bytes([c[0], c[1]])).collect();
