const BITRATES_V1L1: [u32; 16] = [0,32,64,96,128,160,192,224,256,288,320,352,384,416,448,0];
const BITRATES_V2: [u32; 16] = [0,8,16,24,32,40,48,56,64,80,96,112,128,144,160,0];
const RATES_V1: [u32; 4] = [44100,48000,32000,0];
const RATES_V2: [u32; 4] = [22050,24000,16000,0];

