    let cached_d = entry.duration.borrow().clone();
    let cached_b = entry.bitrate.borrow().clone();
    let cached_f = entry.freq.borrow().clone();
    let cached_t = entry.tags.borrow().clone();
    if cached_d.is_some() && cached_b.is_some() && cached_f.is_some() && cached_t.is_some() {
        let t = cached_t.unwrap_or_default();
        return Mp3Info { duration: cached_d.unwrap(), bitrate: cached_b.unwrap(), freq: cached_f.unwrap(), tags: t, width: None, height: None };
    }
    let data = if entry.is_dir { Vec::new() } else { std::fs::read(&entry.path).unwrap_or_default() };
    let r = parse(&data);
    *entry.duration.borrow_mut() = Some(r.duration);
    *entry.bitrate.borrow_mut() = Some(r.bitrate);
    *entry.freq.borrow_mut() = Some(r.freq);
    *entry.tags.borrow_mut() = Some(r.tags.clone());
