                        let pad = if (b2 >> 1) & 1 == 1 { 1 } else { 0 };
                        let fl = match layer {
                            1 => (12 * bitrate * 1000 / sr + pad) * 4,
                            _ => 144 * bitrate * 1000 / sr + pad,
                        };
                        if fl == 0 { break; }
                        frames += 1;
                        p += fl;
                    } else { p += 1; }
                }
                out.duration = Some(frames as f64 * samples as f64 / sr as f64);
                found = true;
            }
