    t.to_string()
}

fn decode_text(d: &[u8]) -> String {
    if d.is_empty() { return String::new(); }
    match d[0] {
        0 => String::from_utf8_lossy(&d[1..]).trim_matches('\0').to_string(),
        1 => {
            if d.len() >= 3 && d[1] == 0xff && d[2] == 0xfe {
                let s: Vec<u16> = d[3..].chunks(2).filter(|c| c.len() == 2).map(|c| u16::from_le_bytes([c[0], c[1]])).collect();
                String::from_utf16_lossy(&s).trim_matches('\0').to_string()
            } else if d.len() >= 3 && d[1] == 0xfe && d[2] == 0xff {
