            }
        }
        2 => {
            let s: Vec<u16> = d[1..].chunks(2).filter(|c| c.len() == 2).map(|c| u16::from_be_bytes([c[0], c[1]])).collect();
            String::from_utf16_lossy(&s).trim_matches('\0').to_string()
        }
        3 => String::from_utf8_lossy(&d[1..]).trim_matches('\0').to_string(),
        _ => String::from_utf8_lossy(d).to_string(),
    }
}
