            }
        }
    }
    if let Some(v) = map.get("no_color") { cfg.no_color = v == "true"; }
    if let Some(v) = map.get("gitignore") { cfg.gitignore = v == "true"; }
    if let Some(v) = map.get("hgignore") { cfg.hgignore = v == "true"; }
    if let Some(v) = map.get("dockerignore") { cfg.dockerignore = v == "true"; }
    if let Some(v) = map.get("us_dates") { cfg.us_dates = v == "true"; }
    if let Some(v) = map.get("check_for_updates") { cfg.check_for_updates = v == "true"; }
    if let Some(v) = map.get("default_file_size_format") { cfg.default_file_size_format = v; }
    for (k, target) in [
        ("is_zip_archive", 0), ("is_archive", 1), ("is_audio", 2), ("is_book", 3),
        ("is_doc", 4), ("is_font", 5), ("is_image", 6), ("is_source", 7), ("is_video", 8),
    ] {
        if let Some(v) = map.get(k) {
            let items: Vec<String> = v.split('\u{1}').map(|s| s.to_string()).collect();
            match target {
                0 => cfg.is_zip_archive = items,
                1 => cfg.is_archive = items,
                2 => cfg.is_audio = items,
                3 => cfg.is_book = items,
                4 => cfg.is_doc = items,
                5 => cfg.is_font = items,
                6 => cfg.is_image = items,
                7 => cfg.is_source = items,
                _ => cfg.is_video = items,
            }
        }
    }
    cfg
}

fn render(cfg: &Config) -> String {
    fn arr(v: &[String]) -> String {
        let items: Vec<String> = v.iter().map(|s| format!("    \"{}\",", s)).collect();
        format!("[\n{}\n]", items.join("\n"))
    }
    let mut s = String::new();
    s.push_str(&format!("no_color = {}\n", cfg.no_color));
    s.push_str(&format!("gitignore = {}\n", cfg.gitignore));
    s.push_str(&format!("hgignore = {}\n", cfg.hgignore));
    s.push_str(&format!("dockerignore = {}\n", cfg.dockerignore));
    s.push_str(&format!("is_zip_archive = {}\n", arr(&cfg.is_zip_archive)));
    s.push_str(&format!("is_archive = {}\n", arr(&cfg.is_archive)));
    s.push_str(&format!("is_audio = {}\n", arr(&cfg.is_audio)));
    s.push_str(&format!("is_book = {}\n", arr(&cfg.is_book)));
    s.push_str(&format!("is_doc = {}\n", arr(&cfg.is_doc)));
    s.push_str(&format!("is_font = {}\n", arr(&cfg.is_font)));
    s.push_str(&format!("is_image = {}\n", arr(&cfg.is_image)));
    s.push_str(&format!("is_source = {}\n", arr(&cfg.is_source)));
    s.push_str(&format!("is_video = {}\n", arr(&cfg.is_video)));
    s.push_str(&format!("default_file_size_format = \"{}\"\n", cfg.default_file_size_format));
    s.push_str(&format!("us_dates = {}\n", cfg.us_dates));
    s.push_str(&format!("check_for_updates = {}\n", cfg.check_for_updates));
    s
}

pub fn default_path() -> std::path::PathBuf {
    let home = std::env::var("HOME").unwrap_or_else(|_| "/root".into());
    std::path::PathBuf::from(home).join(".config/fselect/config.toml")
}
