// Minimal ZIP reader (central directory only)
pub struct ZipEntry {
    pub name: String,
    pub size: u64,
    pub is_dir: bool,
}

pub fn parse_zip(data: &[u8]) -> Option<Vec<ZipEntry>> {
    // locate the EOCD record
    if data.len() < 22 { return None; }
    let mut eocd = None;
    let start = if data.len() > 66000 { data.len() - 66000 } else { 0 };
    let mut i = data.len() - 22;
    while i > start {
        if &data[i..i + 4] == b"PK\x05\x06" {
            eocd = Some(i);
            break;
        }
        if i == 0 { break; }
        i -= 1;
    }
    let eocd = eocd?;
    let n = u16(data, eocd + 10) as usize;
    let cd_off = u32(data, eocd + 16) as usize;
    if cd_off >= data.len() { return None; }
    let mut out = Vec::new();
    let mut p = cd_off;
    for _ in 0..n {
        if p + 46 > data.len() || &data[p..p + 4] != b"PK\x01\x02" { break; }
        let name_len = u16(data, p + 28) as usize;
        let extra_len = u16(data, p + 30) as usize;
        let comment_len = u16(data, p + 32) as usize;
        let size = u32(data, p + 24) as u64;
        let attr = u16(data, p + 38);
        if p + 46 + name_len > data.len() { break; }
        let name = String::from_utf8_lossy(&data[p + 46..p + 46 + name_len]).to_string();
        let is_dir = name.ends_with('/') || (attr & 0x10 != 0);
        out.push(ZipEntry { name, size, is_dir });
        p += 46 + name_len + extra_len + comment_len;
    }
    Some(out)
}

fn u16(d: &[u8], o: usize) -> u16 { (d[o] as u16) | ((d[o + 1] as u16) << 8) }
fn u32(d: &[u8], o: usize) -> u32 { u32::from_le_bytes([d[o], d[o+1], d[o+2], d[o+3]]) }
