fn parse_value(line: &str) -> Option<String> {
    let mut in_str = false;
    let mut out = String::new();
    for c in line.chars() {
        match c {
            '"' => { in_str = !in_str; if !in_str && !out.is_empty() { return Some(out.clone()); } }
            ',' | ']' if !in_str => return Some(out.clone()),
            _ if in_str => out.push(c),
            ' ' | '\t' | '=' if !in_str && out.is_empty() => continue,
            _ if !in_str => out.push(c),
            _ => {}
        }
    }
    if out.is_empty() { None } else { Some(out) }
}

pub fn load(path: Option<&str>) -> Config {
    let mut cfg = Config::default();
    let candidate = match path {
        Some(p) => std::path::PathBuf::from(p),
        None => default_path(),
    };
    let mut text = None;
    if let Some(p) = candidate.to_str() {
        match std::fs::read_to_string(p) {
            Ok(s) => text = Some(s),
            Err(_) => {
                if path.is_some() {
                    println!("Could not open config file. Using default settings.");
                }
            }
        }
    }
    if text.is_none() {
        // look next to the executable
        if let Ok(exe) = std::env::current_exe() {
            if let Some(dir) = exe.parent() {
                for name in ["config.toml", "fselect.toml"] {
                    let p = dir.join(name);
                    if let Ok(s) = std::fs::read_to_string(&p) { text = Some(s); break; }
                }
            }
        }
    }
    if text.is_none() {
        // create a new config file with defaults
        let s = render(&cfg);
        if let Some(p) = candidate.to_str() {
            if let Some(dir) = candidate.parent() { let _ = std::fs::create_dir_all(dir); }
            let _ = std::fs::write(p, s);
        }
        return cfg;
    }
    let t = text.unwrap();
    let mut map: HashMap<String, String> = HashMap::new();
    let mut key = String::new();
    for line in t.lines() {
        let l = line.trim();
        if l.is_empty() || l.starts_with('#') { continue; }
        if let Some(eq) = l.find('=') {
            key = l[..eq].trim().to_string();
            let rest = l[eq + 1..].trim();
            if rest.starts_with('[') {
                // array: collect until ']'
                let mut buf = rest.to_string();
                while !buf.contains(']') { key = key.clone(); break; }
                let mut items = Vec::new();
                let mut cur = String::new();
                let mut instr = false;
                for c in buf.chars() {
