                        '"' => { instr = !instr; }
                        ',' if !instr => { if !cur.is_empty() { items.push(cur.clone()); cur.clear(); } }
                        '[' | ']' if !instr => {}
                        _ if instr => cur.push(c),
                        _ => {}
                    }
