// Directory traversal
use crate::parse::{Root, RootOpts};
use crate::fsx::Entry;
use crate::rx::Regex;
use std::collections::HashSet;
use std::path::{Path, PathBuf};

pub struct TsErr(pub String);

fn expand_tilde(p: &str) -> String {
    if p == "~" {
        return std::env::var("HOME").unwrap_or_else(|_| p.to_string());
    }
    if let Some(rest) = p.strip_prefix("~/") {
        let home = std::env::var("HOME").unwrap_or_default();
        return format!("{}/{}", home, rest);
    }
    p.to_string()
}

fn mk_entry(path: &Path, name: &str, depth: u32, root: usize, root_path: &str, follow: bool, is_link: bool) -> Entry {
    let md_link = std::fs::symlink_metadata(path).ok();
    let md = if follow { std::fs::metadata(path).ok().or(md_link.clone()) } else { md_link.clone() };
    let md_ref = md.as_ref();
    let md_l = md_link.as_ref();
    let ft_l = md_l.map(|m| m.file_type()).ok();
    let ft = md_ref.map(|m| m.file_type());
    let is_symlink = ft_l.map(|t| t.is_symlink()).unwrap_or(false) || is_link;
    let mut e = Entry::default();
    e.path = path.to_path_buf();
    e.name = name.to_string();
    e.depth = depth;
    e.root = root;
    e.root_path = root_path.to_string();
    e.is_symlink = is_symlink;
    e.exists = md_ref.is_some();
    if let Some(m) = md_ref {
        e.is_dir = m.is_dir();
        e.is_file = m.is_file();
        e.size = Some(m.len());
        e.mode = m.mode() & 0o7777;
        e.ftype = if m.is_dir() { 2 } else if m.is_file() { 1 } else if m.file_type().is_fifo() { 4 } else if m.file_type().is_char_device() { 5 } else if m.file_type().is_block_device() { 6 } else if m.file_type().is_socket() { 7 } else { 1 };
        e.is_pipe = m.file_type().is_fifo();
        e.is_char = m.file_type().is_char_device();
        e.is_block = m.file_type().is_block_device();
        e.is_socket = m.file_type().is_socket();
        e.uid = m.uid();
        e.gid = m.gid();
        e.atime = m.atime();
        e.mtime = m.mtime();
        e.ctime = m.ctime();
        match m.created() {
            Ok(t) => { e.btime = Some(t); }
            Err(_) => { e.btime = Some(m.ctime()); }
        }
        e.inode = m.ino();
        e.blocks = m.blocks();
        e.hardlinks = m.nlink();
        e.device = m.dev();
        e.rdev = m.rdev();
    } else {
        // dangling symlink: no stat info
        e.is_file = false;
        e.is_dir = false;
    }
    e
}

fn is_zip_archive_name(name: &str) -> bool {
    let cfg = crate::cfg::config();
    let ext = crate::columns::ext_of(name);
    if ext.is_empty() { return false; }
    let needle = format!(".{}", ext.to_lowercase());
    cfg.is_zip_archive.iter().any(|e| e.to_lowercase() == needle)
}

fn expand_regexp(path: &str) -> Vec<String> {
    let p = expand_tilde(path);
    let (dir, pat) = match p.rfind('/') {
        Some(i) => (p[..i].to_string(), p[i + 1..].to_string()),
        None => (String::new(), p.clone()),
    };
    if pat.is_empty() { return vec![p]; }
    let dirpath = if dir.is_empty() { PathBuf::from(".") } else { PathBuf::from(&dir) };
    let re = match Regex::compile(&format!("^{}$", pat), false) {
        Ok(r) => r,
        Err(_) => return Vec::new(),
    };
    let mut out = Vec::new();
    if let Ok(rd) = std::fs::read_dir(&dirpath) {
        let mut names: Vec<String> = Vec::new();
        for e in rd.flatten() {
            names.push(e.file_name().to_string_lossy().to_string());
        }
        for n in names {
            if re.is_match(&n) {
                if dir.is_empty() { out.push(n); } else { out.push(format!("{}/{}", dir, n)); }
            }
        }
    }
    if out.is_empty() {
        if pat.contains('*') || pat.contains('?') {
            return Vec::new();
        }
        return vec![p];
    }
    out
}

pub struct Walker {
    pub roots: Vec<Root>,
    pub errs: Vec<TsErr>,
    pub cfg_ignore: crate::cfg::Config,
}

pub fn traverse(roots: &[Root]) -> Result<Vec<Entry>, TsErr> {
    let mut out: Vec<Entry> = Vec::new();
    let mut visited: HashSet<String> = HashSet::new();
    for (ri, r) in roots.iter().enumerate() {
        let follow = r.opts.symlinks;
        let mut paths: Vec<String> = Vec::new();
        if r.opts.regexp {
            paths = expand_regexp(&r.path);
        } else {
            paths.push(expand_tilde(&r.path));
        }
        for p0 in paths {
            let p = PathBuf::from(&p0);
            let canon = match std::fs::canonicalize(&p) {
                Ok(c) => c,
                Err(e) => return Err(TsErr(format!("could not canonicalize path: {}", e))),
            };
            let meta = match std::fs::metadata(&canon) {
                Ok(m) => m,
                Err(e) => return Err(TsErr(format!("{}", e))),
            };
            if !meta.is_dir() {
                match std::fs::read_dir(&canon) {
                    Ok(_) => {}
                    Err(e) => return Err(TsErr(format!("{}", e))),
                }
                continue;
            }
            visited.clear();
            visited.insert(canon.to_string_lossy().to_string());
            let root_path_str = canon.to_string_lossy().to_string();
            // the path used for relative computation is the path as given
            let root_as_given = p0.clone();
            let mut queue: Vec<(PathBuf, u32, bool)> = Vec::new();
            queue.push((p.clone(), 0, false));
            if r.opts.dfs {
                // depth first: use the queue as a stack
                while let Some((dir, depth, was_symlink)) = queue.pop() {
                    let base = if was_symlink {
                        match std::fs::canonicalize(&dir) { Ok(c) => c, Err(_) => dir.clone() }
                    } else { dir.clone() };
                    let mut children: Vec<(PathBuf, String, u8)> = Vec::new();
                    let rd = match std::fs::read_dir(&base) {
                        Ok(r) => r,
                        Err(e) => { return Err(TsErr(format!("{}", e))); }
                    };
                    for ent in rd.flatten() {
                        let name = ent.file_name().to_string_lossy().to_string();
                        children.push((ent.path(), name, 0));
                    }
                    // reverse so popping yields readdir order
                    children.reverse();
                    for (cp, name, _) in children {
                        process_entry(&mut out, &mut visited, &cp, &name, depth + 1, ri, &root_as_given, follow, r, false, queue_len_marker(&queue));
                        // push directories
                        let link = is_symlink_path(&cp);
                        let is_dir = if follow { std::fs::metadata(&cp).map(|m| m.is_dir()).unwrap_or(false) } else { std::fs::symlink_metadata(&cp).map(|m| m.is_dir()).unwrap_or(false) };
                        if is_dir {
                            let key = std::fs::canonicalize(&cp).map(|c| c.to_string_lossy().to_string()).unwrap_or_default();
                            if !visited.contains(&key) {
                                queue.push((cp.clone(), depth + 1, link));
                            }
                        }
                    }
                }
            } else {
                let mut qi = 0usize;
                while qi < queue.len() {
                    let (dir, depth, was_symlink) = queue[qi].clone();
                    qi += 1;
                    let base = if was_symlink {
                        match std::fs::canonicalize(&dir) { Ok(c) => c, Err(_) => dir.clone() }
                    } else { dir.clone() };
                    let key = base.to_string_lossy().to_string();
                    if visited.contains(&key) && depth != 0 {
                        continue;
                    }
                    visited.insert(key);
                    let rd = match std::fs::read_dir(&base) {
                        Ok(r) => r,
                        Err(e) => { return Err(TsErr(format!("{}", e))); }
                    };
                    for ent in rd.flatten() {
                        let name = ent.file_name().to_string_lossy().to_string();
                        let cp = base.join(&name);
                        let link = is_symlink_path(&cp);
                        let is_dir = if follow {
                            std::fs::metadata(&cp).map(|m| m.is_dir()).unwrap_or(false)
                        } else {
