// .dockerignore style ignore patterns
use crate::rx::Regex;

pub struct IgErr(pub String);

fn conv(pat: &str) -> String {
    let mut out = String::new();
    for c in pat.chars() {
        match c {
            '*' => out.push_str(".*"),
            '?' => out.push('.'),
            other => {
                if "\\.+()[]{}|^$#".contains(other) { out.push('\\'); }
                out.push(other);
            }
        }
    }
    out
}

pub fn compile(patterns: &str) -> Result<Vec<Regex>, IgErr> {
    let mut out = Vec::new();
    for line in patterns.lines() {
        let l = line.trim();
        if l.is_empty() || l.starts_with('#') { continue; }
        let anchored = l.starts_with('/');
        let dir_only = l.ends_with('/');
        let p = l.trim_start_matches('/').trim_end_matches('/');
        if p.is_empty() { continue; }
        if p.starts_with('(') || p.starts_with(')') || p.starts_with('[') || p.starts_with('{')
            || p.starts_with('\\') || p.starts_with('!') || p.starts_with('/') {
            return Err(IgErr(p.to_string()));
        }
        let body = conv(p);
        let prefix = if p.contains('/') { "^".to_string() } else { "(?:^|/)".to_string() };
        let suffix = if dir_only { "/".to_string() } else { "(?:/|$)".to_string() };
        match Regex::compile(&format!("{}{}{}", prefix, body, suffix), false) {
            Ok(r) => out.push(r),
            Err(_) => return Err(IgErr(p.to_string())),
        }
    }
    Ok(out)
}

pub fn is_ignored(patterns: &str, rel: &str) -> bool {
    match compile(patterns) {
        Ok(list) => list.iter().any(|r| r.is_match(rel)),
        Err(_) => false,
    }
}
