// Directory traversal
use crate::parse::{Root};
use crate::fsx::Entry;
use std::collections::HashSet;
use std::path::{Path, PathBuf};

pub struct TsErr(pub String);

fn expand_tilde(p: &str) -> String {
    if p == "~" { return std::env::var("HOME").unwrap_or_else(|_| p.to_string()); }
    if let Some(rest) = p.strip_prefix("~/") {
        let home = std::env::var("HOME").unwrap_or_default();
        return format!("{}/{}", home, rest);
    }
    p.to_string()
}

pub fn mk_entry(path: &Path, name: &str, depth: u32, root: usize, root_path: &str, follow: bool) -> Entry {
    let md_link = std::fs::symlink_metadata(path).ok();
    let md = if follow { std::fs::metadata(path).ok().or_else(|| md_link.clone()) } else { md_link.clone() };
    let md_ref = md.as_ref();
    let md_l = md_link.as_ref();
    let is_symlink = md_l.map(|m| m.file_type().is_symlink()).unwrap_or(false);
    let mut e = Entry::default();
    e.path = path.to_path_buf();
    e.name = name.to_string();
    e.depth = depth;
    e.root = root;
    e.root_path = root_path.to_string();
    e.is_symlink = is_symlink;
    e.exists = md_ref.is_some();
    if let Some(m) = md_ref {
        let ft = m.file_type();
        e.is_dir = m.is_dir();
        e.is_file = m.is_file();
        e.size = Some(m.len());
        e.mode = m.mode() & 0o7777;
        e.ftype = if m.is_dir() { 2 } else if m.is_file() { 1 } else if ft.is_fifo() { 4 } else if ft.is_char_device() { 5 } else if ft.is_block_device() { 6 } else if ft.is_socket() { 7 } else { 1 };
        e.is_pipe = ft.is_fifo();
        e.is_char = ft.is_char_device();
        e.is_block = ft.is_block_device();
        e.is_socket = ft.is_socket();
        e.uid = m.uid();
        e.gid = m.gid();
        e.atime = m.atime();
        e.mtime = m.mtime();
        e.ctime = m.ctime();
        e.btime = Some(m.created().unwrap_or_else(|_| std::time::SystemTime::from(std::time::UNIX_EPOCH)).duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs() as i64).unwrap_or(m.ctime()));
        e.inode = m.ino();
        e.blocks = m.blocks();
        e.hardlinks = m.nlink();
        e.device = m.dev();
        e.rdev = m.rdev();
    }
    e
}

fn is_zip_archive_name(name: &str) -> bool {
    let cfg = crate::cfg::config();
    let ext = crate::columns::ext_of(name);
    if ext.is_empty() { return false; }
    let needle = format!(".{}", ext.to_lowercase());
    cfg.is_zip_archive.iter().any(|e| e.to_lowercase() == needle)
}

fn expand_regexp(path: &str) -> Vec<String> {
    let p = expand_tilde(path);
    let (dir, pat) = match p.rfind('/') {
        Some(i) => (p[..i].to_string(), p[i + 1..].to_string()),
        None => (String::new(), p.clone()),
    };
    if pat.is_empty() { return vec![p]; }
    let dirpath = if dir.is_empty() { PathBuf::from(".") } else { PathBuf::from(&dir) };
    let re = match crate::rx::Regex::compile(&format!("^{}$", pat), false) {
        Ok(r) => r,
        Err(_) => return Vec::new(),
    };
    let mut out = Vec::new();
    if let Ok(rd) = std::fs::read_dir(&dirpath) {
        let mut names: Vec<String> = Vec::new();
        for e in rd.flatten() { names.push(e.file_name().to_string_lossy().to_string()); }
        for n in names {
            if re.is_match(&n) {
                if dir.is_empty() { out.push(n); } else { out.push(format!("{}/{}", dir, n)); }
            }
        }
    }
    if out.is_empty() {
        if pat.contains('*') || pat.contains('?') { return Vec::new(); }
        return vec![p];
    }
    out
}

struct Node { path: PathBuf, depth: u32, was_symlink: bool }

pub fn traverse(roots: &[Root]) -> Result<Vec<Entry>, TsErr> {
    let mut out: Vec<Entry> = Vec::new();
    for (ri, r) in roots.iter().enumerate() {
        let follow = r.opts.symlinks;
        let paths: Vec<String> = if r.opts.regexp { expand_regexp(&r.path) } else { vec![expand_tilde(&r.path)] };
        for p0 in paths {
            let p = PathBuf::from(&p0);
            let canon = match std::fs::canonicalize(&p) {
                Ok(c) => c,
