            while let Some(node) = if dfs { stack.pop() } else { if stack.is_empty() { None } else { Some(stack.remove(0)) } } {
                let base = if node.was_symlink {
                    match std::fs::canonicalize(&node.path) { Ok(c) => c, Err(_) => node.path.clone() }
                } else { node.path.clone() };
                let key = base.to_string_lossy().to_string();
                if node.depth > 0 && visited.contains(&key) { continue; }
                visited.insert(key);
                let rd = match std::fs::read_dir(&base) {
                    Ok(r) => r,
                    Err(e) => return Err(TsErr(format!("{}", e))),
                };
                let mut children: Vec<(PathBuf, String)> = Vec::new();
                for ent in rd.flatten() {
                    children.push((ent.path(), ent.file_name().to_string_lossy().to_string()));
                }
                if dfs { children.reverse(); }
                for (cp, name) in children {
                    if let Some(pat) = &ignore_patterns {
                        let rel = match cp.strip_prefix(&canon) {
                            Ok(rp) => rp.to_string_lossy().to_string(),
                            Err(_) => name.clone(),
                        };
                        if crate::ignore::is_ignored(pat, &rel) { continue; }
                    }
                    let link = std::fs::symlink_metadata(&cp).map(|m| m.file_type().is_symlink()).unwrap_or(false);
                    let is_dir = if follow {
                        std::fs::metadata(&cp).map(|m| m.is_dir()).unwrap_or(false)
                    } else {
                        std::fs::symlink_metadata(&cp).map(|m| m.is_dir()).unwrap_or(false)
                    };
                    if let Some(md) = r.opts.maxdepth {
                        if depth_of(&node) + 1 > md { continue; }
                    }
                    let d = depth_of(&node) + 1;
                    let min_ok = match r.opts.mindepth { Some(m) => d >= m, None => true };
                    if min_ok {
                        let e = mk_entry(&cp, &name, d, ri, &root_as_given, follow);
                        out.push(e.clone());
                        if r.opts.archives && e.is_file && is_zip_archive_name(&e.name) {
                            emit_zip(out, &e, ri, &root_as_given, d);
                        }
                    }
                    if is_dir {
                        stack.push(Node { path: cp.clone(), depth: d, was_symlink: link });
                    }
                }
            }
        }
    }
    Ok(out)
}

fn depth_of(n: &Node) -> u32 { n.depth }

fn emit_zip(out: &mut Vec<Entry>, e: &Entry, ri: usize, root_as_given: &str, depth: u32) {
    if let Ok(data) = std::fs::read(&e.path) {
        if let Some(entries) = crate::zip::parse_zip(&data) {
            let arch = format!("[{}]", e.path.to_string_lossy());
            for z in entries {
                let mut ze = Entry::default();
                let zpath = PathBuf::from(&z.name);
                let zname = zpath.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_else(|| z.name.clone());
                ze.path = zpath;
                ze.name = zname;
                ze.depth = depth + 1;
                ze.root = ri;
                ze.root_path = root_as_given.to_string();
                ze.size = Some(z.size);
                ze.is_dir = z.is_dir;
                ze.is_file = !z.is_dir;
                ze.archive = Some(arch.clone());
                ze.mode = if z.is_dir { 0o755 } else { 0o644 };
                ze.ftype = if z.is_dir { 2 } else { 1 };
                out.push(ze);
            }
        }
    }
}
