// LS_COLORS handling
use crate::fsx::Entry;

pub const DEFAULT_LS_COLORS: &str = "rs=0:di=01;34:ln=01;36:mh=00:pi=33:so=01;35:do=01;35:bd=01;33:cd=01;33:or=01;31:mi=00:su=37;41:sg=30;43:ca=30;41:tw=30;42:ow=34;42:st=37;44:ex=01;32:*.tar=01;31:*.tgz=01;31:*.zip=01;31:*.gz=01;31:*.7z=01;31:*.jpg=01;35:*.jpeg=01;35:*.png=01;35:*.gif=01;35:*.mp3=00;36:*.mp4=00;32";

pub fn lookup(ls: &str, entry: &Entry) -> Option<String> {
    // type based entries first
    let type_code = if entry.is_dir { Some("di") }
    else if entry.is_symlink { Some("ln") }
    else if entry.is_pipe { Some("pi") }
    else if entry.is_socket { Some("so") }
    else if entry.is_block { Some("bd") }
    else if entry.is_char { Some("cd") }
    else if entry.is_file && entry.mode & 0o111 != 0 { Some("ex") }
    else { None };
    let mut ext_match: Option<String> = None;
    for part in ls.split(':') {
        let part = part.trim();
        if part.is_empty() { continue; }
        let (k, v) = match part.split_once('=') { Some(p) => p, None => continue };
        if let Some(tc) = type_code {
            if k == tc { return Some(v.to_string()); }
        }
        if ext_match.is_none() && k.starts_with('*') {
            let pat = &k[1..];
            let name = &entry.name;
            if pat.starts_with('.') {
                if name.ends_with(pat) { ext_match = Some(v.to_string()); }
            } else {
                // simple suffix wildcard
                if name.ends_with(pat) || name.contains(pat) { ext_match = Some(v.to_string()); }
            }
        }
    }
    if type_code.is_some() {
        // directory/symlink/etc entries take precedence over extension patterns
        return None;
    }
    ext_match
}

pub fn paint(s: &str, code: &str) -> String {
    format!("\x1b[{}m{}\x1b[0m", code, s)
}
