// fselect - find files with SQL-like queries
mod b64;
mod cfg;
mod colors;
mod columns;
mod dates;
mod eval;
mod fmtsize;
mod fsx;
mod functions;
mod hash;
mod ignore;
mod img;
mod mime;
mod mp3;
mod output;
mod parse;
mod rand;
mod rx;
mod tokenize;
mod traverse;
mod val;
mod zip;
mod interactive;
mod help;

use cfg::Config;
use parse::{Cond, Expr, Field, Format, Query, Root, OrderKey};
use val::Val;
use fsx::Entry;
use std::io::Write;

pub struct Opts {
    pub no_color: bool,
    pub no_errors: bool,
    pub us_dates: bool,
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let mut no_color = false;
    let mut no_errors = false;
    let mut us_dates = false;
    let mut config_path: Option<String> = None;
    let mut interactive = false;
    let mut query_parts: Vec<String> = Vec::new();
    let mut i = 0usize;
    let mut first = true;
    while i < args.len() {
        let a = &args[i];
        if first {
            let la = a.to_lowercase();
            if la.contains("help") {
                help::print_full(no_color);
                std::process::exit(0);
            }
            if la == "-v" || la.contains("version") {
                help::print_version(no_color);
                std::process::exit(0);
            }
            first = false;
        }
        let la = a.to_lowercase();
        if la == "-i" || la == "--interactive" || la == "/i" {
            interactive = true;
            i += 1;
            continue;
        }
        if la == "-c" || la == "--config" || la == "/config" {
            i += 1;
            if i >= args.len() {
                eprintln!("Error: --config requires a path argument");
                std::process::exit(2);
            }
            config_path = Some(args[i].clone());
            i += 1;
            continue;
        }
        if la == "--nocolor" || la == "--no-color" || la == "/nocolor" {
            no_color = true;
            i += 1;
            continue;
        }
        if la == "--no-errors" {
            no_errors = true;
            i += 1;
            continue;
        }
        if la == "--us-dates" {
            us_dates = true;
            i += 1;
            continue;
        }
        query_parts.push(a.clone());
        i += 1;
    }
    let cfg = std::sync::Arc::new(cfg::load(config_path.as_deref()));
    if !no_color {
        no_color = cfg.no_color || std::env::var_os("NO_COLOR").is_some();
    }
    if !us_dates { us_dates = cfg.us_dates; }
    let _ = std::sync::Arc::into_raw(cfg);
    // store config globally
    let cfg_ref = cfg::load(config_path.as_deref());
    let _ = cfg::GLOBAL.set(cfg_ref);
    if interactive {
        interactive::run(no_color, no_errors, us_dates);
        return;
    }
    if query_parts.is_empty() {
        help::print_short(no_color);
        std::process::exit(0);
    }
    let query = query_parts.join(" ");
    let opts = Opts { no_color, no_errors, us_dates };
    match run_query_text(&query, &opts) {
        Ok(()) => {}
        Err(e) => {
            let code = e.code;
            if !no_errors { e.report(); }
            std::process::exit(code);
        }
    }
}

pub enum RunErr {
    Query(String),
    Io(String),
}

impl RunErr {
    fn code(&self) -> i32 {
        match self { RunErr::Query(_) => 2, RunErr::Io(_) => 1 }
    }
    fn report(&self) {
        match self {
            RunErr::Query(m) => {
                if crate::cfg::config().no_color || std::env::var_os("NO_COLOR").is_some() {
                    eprintln!("query: {}", m);
                } else {
                    eprintln!("\x1b[33mquery\x1b[0m: {}", m);
                }
            }
            RunErr::Io(m) => {
                eprintln!("\x1b[33m{}\x1b[0m: {}", crate::ctx_err::PREFIX, m);
            }
        }
    }
}

pub fn run_query_text(text: &str, opts: &Opts) -> Result<(), RunErr> {
    let q = match parse::parse_text(text) {
        Ok(q) => q,
        Err(e) => return Err(RunErr::Query(e.0)),
    };
    run(&q, opts, text)
}

struct CtxErr { prefix: String }
impl CtxErr { }

/// Runs a parsed query. Errors during traversal/evaluation are collected and reported.
fn run(q: &Query, opts: &Opts, query_text: &str) -> Result<(), RunErr> {
    let mut fields: Vec<Field> = Vec::new();
    for f in &q.fields {
        match &f.expr {
            Expr::Col { name } if name == "*" => {
                for c in ["mode", "user", "group", "size", "modified", "path"] {
                    fields.push(Field { expr: Expr::Col { name: c.to_string() }, display: crate::parse::display_name(&Expr::Col { name: c.to_string() }) });
                }
            }
            other => fields.push(Field { expr: other.clone(), display: f.display.clone() }),
        }
    }
    let mut rows = match traverse::traverse(&q.roots) {
        Ok(r) => r,
        Err(e) => {
            crate::ctx_err::PREFIX.clear();
            crate::ctx_err::PREFIX.push_str(&last_root_path(&q.roots));
            return Err(RunErr::Io(e.0));
        }
    };
    // record the root alias per row
    for e in rows.iter_mut() {
        if let Some(a) = q.roots.get(e.root).and_then(|r| r.opts.alias.clone()) {
            e.root_alias = a;
        }
    }
    // filter
    let mut kept: Vec<usize> = Vec::new();
    for idx in 0..rows.len() {
