                eprintln!("Error: --config requires a path argument");
                std::process::exit(2);
            }
            config_path = Some(args[i].clone());
            i += 1;
            continue;
        }
        if la == "--nocolor" || la == "--no-color" || la == "/nocolor" {
            no_color = true;
            i += 1;
            continue;
        }
        if la == "--no-errors" {
            no_errors = true;
            i += 1;
            continue;
        }
        if la == "--us-dates" {
