}

pub fn run_query_text(text: &str, opts: &Opts) -> i32 {
    let q = match parse::parse_text(text) {
        Ok(q) => q,
        Err(e) => {
            report_err("query", &e.0);
            return 2;
        }
    };
    run(&q, opts, text)
}

struct OutRow {
    vals: Vec<Val>,
    order: Vec<Val>,
    color: Option<String>,
    color_name: String,
}

fn run(q: &Query, opts: &Opts, query_text: &str) -> i32 {
    let mut fields: Vec<Field> = Vec::new();
    for f in &q.fields {
        match &f.expr {
            Expr::Col { name } if name == "*" => {
                for c in ["mode", "user", "group", "size", "modified", "path"] {
                    let e = Expr::Col { name: c.to_string() };
                    fields.push(Field { display: parse::display_name(&e), expr: e });
                }
            }
            other => fields.push(Field { expr: other.clone(), display: f.display.clone() }),
        }
    }
    let mut rows = match traverse::traverse(&q.roots) {
        Ok(r) => r,
        Err(e) => {
            let p = q.roots.first().map(|r| r.path.clone()).unwrap_or_default();
            report_err(&p, &e.0);
            return 1;
        }
    };
    for e in rows.iter_mut() {
        if let Some(a) = q.roots.get(e.root).and_then(|r| r.opts.alias.clone()) {
            e.root_alias = a.clone();
        }
    }
    // filter
    let mut kept: Vec<usize> = Vec::new();
    for idx in 0..rows.len() {
        let mut ctx = eval::EvalCtx {
            entry: &mut rows[idx],
            err_prefix: String::new(),
            us_dates: opts.us_dates,
            alias: None,
            cwd: std::path::PathBuf::new(),
        };
        ctx.err_prefix = rows[idx].path.to_string_lossy().to_string();
        let ok = match &q.cond {
            None => true,
            Some(c) => eval_cond_full(c, &mut ctx),
        };
        if ok { kept.push(idx); }
    }
    // aggregation
    let agg_keys = eval::field_aggs_fields(&fields, &q.order_by);
    let has_agg = q.fields.iter().any(|f| parse::contains_agg(&f.expr));
    let mut out: Vec<OutRow> = Vec::new();
    if has_agg {
        let mut engine = eval::AggEngine::new();
        for &idx in &kept {
            let mut ctx = eval::EvalCtx {
                entry: &mut rows[idx],
                err_prefix: rows[idx].path.to_string_lossy().to_string(),
                us_dates: opts.us_dates,
                alias: None,
                cwd: std::path::PathBuf::new(),
            };
            let mut key: Vec<Val> = Vec::new();
            for g in &q.group_by {
                match eval::eval(g, &mut ctx) {
                    Ok(v) => key.push(v),
                    Err((m, p)) => { report_err(&ctx.err_prefix, &m); let _ = p; key.push(Val::Null); }
                }
            }
            let gi = engine.group_for(&key);
            for k in &agg_keys {
                // evaluate the aggregate argument for this row
                let arg_val = agg_arg_value(k, &fields, &q.order_by, &mut ctx);
                let st = engine.groups[gi].aggs.entry(k.clone()).or_default();
                match arg_val {
                    Some(v) => st.feed(&v),
                    None => { st.count += 1; st.has = true; }
                }
            }
        }
        // build output rows
        for gi in 0..engine.groups.len() {
            let g = &engine.groups[gi];
            let mut vals: Vec<Val> = Vec::new();
            for f in &fields {
                let dn = parse::display_name(&f.expr);
                if let Some(pos) = q.group_by.iter().position(|ge| parse::display_name(ge) == dn) {
                    vals.push(g.key.get(pos).cloned().unwrap_or(Val::Null));
                } else if parse::contains_agg(&f.expr) {
                    let k = parse::display_name(&f.expr);
                    vals.push(g.aggs.get(&k).map(|s| s.value(agg_canon(&f.expr))).unwrap_or(Val::Null));
                } else {
                    vals.push(Val::Null);
            }
            }
            let mut order: Vec<Val> = Vec::new();
            for o in &q.order_by {
                let dn = parse::display_name(&o.expr);
                if let Some(pos) = q.group_by.iter().position(|ge| parse::display_name(ge) == dn) {
                    order.push(g.key.get(pos).cloned().unwrap_or(Val::Null));
                } else if parse::contains_agg(&o.expr) {
                    let k = parse::display_name(&o.expr);
                    order.push(g.aggs.get(&k).map(|s| s.value(agg_canon(&o.expr))).unwrap_or(Val::Null));
                } else {
                    order.push(Val::Null);
                }
            }
            out.push(OutRow { vals, order, color: None, color_name: String::new() });
        }
    } else {
        for &idx in &kept {
            let mut vals: Vec<Val> = Vec::new();
            let mut skip = false;
            {
                let mut ctx = eval::EvalCtx {
                    entry: &mut rows[idx],
                    err_prefix: rows[idx].path.to_string_lossy().to_string(),
                    us_dates: opts.us_dates,
                    alias: None,
                    cwd: std::path::PathBuf::new(),
                };
                for f in &fields {
                    match eval::eval(&f.expr, &mut ctx) {
                        Ok(v) => vals.push(v),
                        Err((m, use_path)) => {
                            let pre = if use_path { ctx.err_prefix.clone() } else { "expression".to_string() };
                            report_err(&pre, &m);
                            skip = true;
                            break;
                        }
                    }
                }
                if !skip {
                    let mut order: Vec<Val> = Vec::new();
                    for o in &q.order_by {
                        match eval::eval(&o.expr, &mut ctx) {
                            Ok(v) => order.push(v),
                            Err((m, use_path)) => {
                                let pre = if use_path { ctx.err_prefix.clone() } else { "expression".to_string() };
                                report_err(&pre, &m);
                                order.push(Val::Null);
                            }
                        }
                    }
                    let (c, cn) = if opts.no_color || std::env::var_os("NO_COLOR").is_some() || !is_tty() {
                        (None, String::new())
                    } else {
                        let col = output::color_for(&rows[idx]);
                        let nm = rows[idx].name.clone();
                        (col, nm)
                    };
                    out.push(OutRow { vals, order, color: c, color_name: cn });
                }
            }
        }
    }
    // ordering
    if !q.order_by.is_empty() {
        let mut idxs: Vec<usize> = (0..out.len()).collect();
        idxs.sort_by(|a, b| {
            let ra = &out[*a];
            let rb = &out[*b];
            for (i, k) in q.order_by.iter().enumerate() {
                let va = ra.order.get(i).unwrap_or(&Val::Null);
                let vb = rb.order.get(i).unwrap_or(&Val::Null);
                let cmp = cmp_vals(va, vb);
                let c = if k.desc { cmp.reverse() } else { cmp };
                if c != std::cmp::Ordering::Equal { return c; }
            }
            std::cmp::Ordering::Equal
        });
        let mut newout: Vec<OutRow> = Vec::new();
        for i in idxs { newout.push(swap_take(&mut out, i)); }
        out = newout;
    }
    // limit / offset
    let mut start = q.offset as usize;
    if start > out.len() { start = out.len(); }
    let mut end = out.len();
    if q.limit > 0 { end = (start + q.limit as usize).min(out.len()); }
    let slice = &out[start..end];
    write_output(slice, &fields, q.format, opts, query_text);
    if ERRORS.load(Ordering::Relaxed) { 1 } else { 0 }
}

fn swap_take(v: &mut Vec<OutRow>, i: usize) -> OutRow {
    let mut it = v.swap_remove(i);
    std::mem::swap(&mut it, &mut OutRow { vals: Vec::new(), order: Vec::new(), color: None, color_name: String::new() });
    // swap_remove loses order stability; rebuild via remove instead
    unreachable!()
}

fn is_tty() -> bool {
    unsafe { libc_isatty(1) == 1 }
}

extern "C" { fn isatty(fd: i32) -> i32; }

pub fn cmp_vals(a: &Val, b: &Val) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    match (a, b) {
        (Val::Num(x), Val::Num(y)) => x.partial_cmp(y).unwrap_or(Ordering::Equal),
        (Val::Str(x), Val::Str(y)) => x.cmp(y),
        (Val::Date(x), Val::Date(y)) => x.cmp(y),
        (Val::Bool(x), Val::Bool(y)) => x.cmp(y),
        (Val::Null, Val::Null) => Ordering::Equal,
        _ => {
            let ra = type_rank(a);
            let rb = type_rank(b);
            ra.cmp(&rb)
        }
    }
}

fn type_rank(v: &Val) -> u8 {
    match v {
        Val::Null => 0,
        Val::Bool(_) => 1,
        Val::Num(_) => 2,
        Val::Str(_) => 3,
        Val::Date(_) => 4,
    }
}

fn agg_canon(e: &Expr) -> String {
    match e {
        Expr::Func { name, .. } => crate::functions::canonical(name).to_string(),
        _ => String::new(),
    }
}

/// Value of the argument of an aggregate with the given display name, evaluated for the current row
fn agg_arg_value(key: &str, fields: &[Field], order: &[parse::OrderKey], ctx: &mut eval::EvalCtx) -> Option<Val> {
    for f in fields {
        if parse::display_name(&f.expr) == key {
            if let Expr::Func { name, args } = &f.expr {
                if crate::functions::canonical(name) == "count" {
                    if args.is_empty() || matches!(args[0], Expr::Col { name: ref n } if n == "*") {
                        return None;
                    }
                    return eval::eval(&args[0], ctx).ok();
                }
                if let Some(a) = args.first() {
                    return eval::eval(a, ctx).ok();
                }
                return None;
            }
        }
    }
    for o in order {
        if parse::display_name(&o.expr) == key {
            if let Expr::Func { name, args } = &o.expr {
                if crate::functions::canonical(name) == "count" {
                    return None;
                }
                if let Some(a) = args.first() {
                    return eval::eval(a, ctx).ok();
                }
                return None;
            }
        }
    }
    None
}

fn eval_cond_full(c: &Cond, ctx: &mut eval::EvalCtx) -> bool {
    match eval::eval_cond(c, ctx) {
        Ok(b) => b,
        Err((m, use_path)) => {
            let pre = if use_path { ctx.err_prefix.clone() } else { "expression".to_string() };
            report_err(&pre, &m);
            false
        }
    }
}

fn write_output(rows: &[OutRow], fields: &[Field], format: Format, opts: &Opts, query_text: &str) {
    let stdout = std::io::stdout();
    let mut w = stdout.lock();
    let names: Vec<String> = fields.iter().map(|f| f.display.clone()).collect();
    match format {
        Format::Tabs | Format::Lines => {
            let sep = if format == Format::Tabs { "\t" } else { "\n" };
            for r in rows {
                let mut line = String::new();
                for (i, v) in r.vals.iter().enumerate() {
                    if i > 0 { line.push_str(sep); }
                    let s = v.to_str();
                    if i == 0 && !s.is_empty() {
                        if let Some(c) = &r.color {
                            line.push_str(&crate::colors::paint(&s, c));
                            continue;
                        }
                    }
                    line.push_str(&s);
                }
                let _ = writeln!(w, "{}", line);
            }
        }
        Format::List => {
            for r in rows {
                for v in &r.vals {
                    let _ = w.write_all(v.to_str().as_bytes());
                    let _ = w.write_all(&[0]);
                }
            }
        }
        Format::Csv => {
            for r in rows {
                let parts: Vec<String> = r.vals.iter().map(|v| output::csv_field(&v.to_str())).collect();
                let _ = writeln!(w, "{}", parts.join(","));
            }
        }
        Format::Json => {
            let mut items: Vec<String> = Vec::new();
            for r in rows {
                let mut pairs: Vec<(String, String)> = Vec::new();
                for (i, v) in r.vals.iter().enumerate() {
                    let k = names.get(i).cloned().unwrap_or_default();
                    pairs.push((k, v.to_str()));
                }
                pairs.sort_by(|a, b| a.0.cmp(&b.0));
                let obj: Vec<String> = pairs.iter().map(|(k, v)| format!("\"{}\":\"{}\"", output::json_escape(k), output::json_escape(v))).collect();
                items.push(format!("{{{}}}", obj.join(",")));
            }
            let _ = write!(w, "[{}]", items.join(","));
            let _ = w.flush();
        }
        Format::Html => {
            let cols = fields.len();
            let mut s = String::new();
            s.push_str("<html><head><title>");
            s.push_str(&output::html_escape(query_text));
            s.push_str("</title></head><body><table><tr><th colspan=\"");
            s.push_str(&cols.to_string());
            s.push_str("\">");
            s.push_str(&output::html_escape(query_text));
            s.push_str("</th></tr>");
            for r in rows {
                s.push_str("<tr>");
                for v in &r.vals {
                    s.push_str("<td>");
                    s.push_str(&output::html_escape(&v.to_str()));
                    s.push_str("</td>");
                }
                s.push_str("</tr>");
            }
            s.push_str("</table></body></html>");
            let _ = write!(w, "{}", s);
            let _ = w.flush();
        }
    }
}
RSEOF
echo ok

