                            continue;
                        }
                    }
                    line.push_str(&s);
                }
                let _ = writeln!(w, "{}", line);
            }
        }
        Format::List => {
            for r in rows {
                for v in &r.vals {
                    let _ = w.write_all(v.to_str().as_bytes());
                    let _ = w.write_all(&[0]);
                }
            }
        }
        Format::Csv => {
            for r in rows {
                let parts: Vec<String> = r.vals.iter().map(|v| output::csv_field(&v.to_str())).collect();
                let _ = writeln!(w, "{}", parts.join(","));
            }
        }
        Format::Json => {
            let mut items: Vec<String> = Vec::new();
