// Interactive mode
use std::io::{BufRead, Write};

pub fn run() {
    let stdin = std::io::stdin();
    let mut reader = stdin.lock();
    let mut errors = true;
    let mut cwd = std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("."));
    let mut buf = String::new();
