                println!("CTRL-D");
                break;
            }
        }
        let line = buf.trim_end_matches(['\n', '\r']).to_string();
        let trimmed = line.trim();
        if trimmed.eq_ignore_ascii_case("exit") || trimmed.eq_ignore_ascii_case("quit") {
            break;
        }
        if trimmed == "pwd" {
            println!("{}", cwd.display());
            continue;
