            } else {
                errors = true;
                println!("Errors are \x1b[33mON\x1b[0m");
            }
            continue;
        }
        if trimmed.is_empty() {
            // empty query still parses (and fails)
        }
        crate::main::run_line(&line, errors, &cwd);
    }
}

