    let mut ops: Vec<char> = Vec::new();
    let mut txts: Vec<String> = Vec::new();
    let mut cur = String::new();
    for piece in pieces {
        if piece.chars().count() == 1 && "+-*/%".contains(&piece) {
            ops.push(piece.chars().next().unwrap());
            if !cur.is_empty() { txts.push(cur.clone()); cur.clear(); }
        } else {
            cur.push_str(&piece);
        }
    }
    if !cur.is_empty() { txts.push(cur); }
    if txts.is_empty() { return None; }
    // validate operands
    for t in &txts {
        if t.is_empty() {
            // empty operand only allowed as the very first (leading operator)
            if !txts.is_empty() && txts[0].is_empty() && txts.len() > 1 {
                continue;
            }
            return None;
        }
        let low = t.to_lowercase();
        if !(t.parse::<f64>().is_ok() || crate::columns::is_column(&low) || low == "true" || low == "false"
