        // leading operator: empty left operand
        let mut out: Vec<(char, String)> = Vec::new();
        out.push((ops[0], String::new()));
        out.push((ops[0], txts[1].clone()));
        for i in 1..txts.len() - 1 {
            out.push((ops[i], txts[i + 1].clone()));
        }
        // re-shift: entry i holds the operator applied to entry i (see eval order)
        let mut res: Vec<(char, String)> = Vec::new();
