{"command": "cd /workspace && timeout 60 python3 - <<'PY'
import math
def sqrt_frac64(p):
    shift=128
    r = math.isqrt(p << (2*shift))
    whole = r >> shift
    return (r - (whole << shift)) >> (shift-64)
def cbrt_frac64(p):
    shift=128
    n = p << (3*shift)
    x = 1 << (shift+2)
    while True:
        y = (2*x + n//(x*x))//3
        if y >= x: break
        x = y
    whole = x >> shift
    return (x - (whole << shift)) >> (shift-64)
def primes(n):
    ps=[]; x=2
    while len(ps)<n:
        if all(x%p for p in ps if p*p<=x): ps.append(x)
        x+=1
    return ps
hs=[sqrt_frac64(p) for p in primes(8)]
ks=[cbrt_frac64(p) for p in primes(80)]
print("H:")
for i in range(0,8,4): print("        " + ", ".join("0x%016x"%v for v in hs[i:i+4]) + ",")
print("K:")
for i in range(0,80,4): print("        " + ",".join("0x%016x"%v for v in ks[i:i+4]) + ",")
# generate a rust file for the sha512 h and k
with open('/tmp/k512.rs','w') as f:
    f.write("    let mut h: [u64; 8] = [\n")
    for i in range(0,8,4):
        f.write("        " + ", ".join("0x%016x"%v for v in hs[i:i+4]) + ",\n")
    f.write("    ];\n")
    f.write("    let k: [u64; 80] = [\n")
    for i in range(0,80,4):
        f.write("        " + ",".join("0x%016x"%v for v in ks[i:i+4]) + ",\n")
    f.write("    ];\n")
print("written /tmp/k512.rs")
