new = '''pub fn traverse(roots: &[Root]) -> Result<Vec<Entry>, TsErr> {
    let mut out: Vec<Entry> = Vec::new();
    for (ri, r) in roots.iter().enumerate() {
        let follow = r.opts.symlinks;
        let paths: Vec<String> = if r.opts.regexp { expand_regexp(&r.path) } else { vec![expand_tilde(&r.path)] };
        for p0 in paths {
            let p = PathBuf::from(&p0);
            let canon = match std::fs::canonicalize(&p) {
                Ok(c) => c,
                Err(e) => return Err(TsErr(format!("could not canonicalize path: {}", e))),
            };
            let meta = match std::fs::metadata(&canon) {
                Ok(m) => m,
                Err(e) => return Err(TsErr(format!("{}", e))),
            };
            if !meta.is_dir() {
                if let Err(e) = std::fs::read_dir(&canon) { return Err(TsErr(format!("{}", e))); }
                continue;
            }
            let ignore_patterns: Option<String> = if r.opts.dockerignore || crate::cfg::config().dockerignore {
                match std::fs::read_to_string(canon.join(".dockerignore")) {
                    Ok(s) => Some(s),
                    Err(_) => None,
                }
            } else { None };
            if let Some(pat) = &ignore_patterns {
                if let Err(e) = crate::ignore::compile(pat) {
                    return Err(TsErr(format!("Error creating regex while parsing .dockerignore glob: {}", e.0)));
                }
            }
            let mut visited: HashSet<String> = HashSet::new();
            visited.insert(canon.to_string_lossy().to_string());
            let root_as_given = p0.clone();
            let root_children = read_children(&canon)?;
            if r.opts.dfs {
                let mut frames: Vec<(Vec<(PathBuf, String)>, usize)> = vec![(root_children, 0)];
                while let Some(frame) = frames.last_mut() {
                    if frame.1 >= frame.0.len() { frames.pop(); continue; }
                    let (cp, name) = frame.0[frame.1].clone();
                    frame.1 += 1;
                    if handle_child(&mut out, &mut visited, &cp, &name, frames.len(), ri, &root_as_given, follow, r, &ignore_patterns)? {
                        let base2 = if is_symlink_path(&cp) {
                            match std::fs::canonicalize(&cp) { Ok(c) => c, Err(_) => cp.clone() }
                        } else { cp.clone() };
                        let ch = read_children(&base2)?;
                        frames.push((ch, 0));
                    }
                }
            } else {
                let mut queue: Vec<(PathBuf, String, u32, bool)> = Vec::new();
                for (cp, name) in root_children {
                    queue.push((cp, name, 1, false));
                }
                let mut qi = 0usize;
                while qi < queue.len() {
                    let (cp, name, depth, was_symlink) = queue[qi].clone();
                    qi += 1;
                    let base2 = if was_symlink {
                        match std::fs::canonicalize(&cp) { Ok(c) => c, Err(_) => cp.clone() }
                    } else { cp.clone() };
                    let key = base2.to_string_lossy().to_string();
                    if visited.contains(&key) { continue; }
                    visited.insert(key.clone());
                    let children = read_children(&base2)?;
                    for (cc, cn) in children {
                        if let Some(pat) = &ignore_patterns {
                            let rel = match std::path::Path::new(&base2).join(&cn).strip_prefix(&canon) {
                                Ok(rp) => rp.to_string_lossy().to_string(),
                                Err(_) => cn.clone(),
                            };
                            if crate::ignore::is_ignored(pat, &rel) { continue; }
                        }
                        let link = is_symlink_path(&std::path::Path::new(&base2).join(&cn));
                        let child_path = std::path::Path::new(&base2).join(&cn);
                        let is_dir = if follow {
                            std::fs::metadata(&child_path).map(|m| m.is_dir()).unwrap_or(false)
                        } else {
                            std::fs::symlink_metadata(&child_path).map(|m| m.is_dir()).unwrap_or(false)
                        };
                        if let Some(md) = r.opts.maxdepth {
                            if depth + 1 > md { continue; }
                        }
                        let min_ok = match r.opts.mindepth { Some(m) => depth + 1 >= m, None => true };
                        if min_ok {
                            let e = mk_entry(&child_path, &cn, depth + 1, ri, &root_as_given, follow);
                            out.push(e.clone());
                            if r.opts.archives && e.is_file && is_zip_archive_name(&e.name) {
                                emit_zip(&mut out, &e, ri, &root_as_given, depth + 1);
                            }
                        }
                        if is_dir {
                            queue.push((child_path.clone(), cn.clone(), depth + 1, link));
                        }
                    }
                }
            }
        }
    }
    Ok(out)
}

fn read_children(dir: &Path) -> Result<Vec<(PathBuf, String)>, TsErr> {
    let rd = match std::fs::read_dir(dir) {
        Ok(r) => r,
        Err(e) => return Err(TsErr(format!("{}", e))),
    };
    let mut v = Vec::new();
    for ent in rd.flatten() {
        v.push((ent.path(), ent.file_name().to_string_lossy().to_string()));
    }
    Ok(v)
}

/// Process a single entry; returns true when it is a directory that should be descended into
fn handle_child(out: &mut Vec<Entry>, visited: &mut HashSet<String>, cp: &Path, name: &str, depth: usize, ri: usize, root_as_given: &str, follow: bool, r: &Root, ignore_patterns: &Option<String>) -> Result<bool, TsErr> {
    if let Some(pat) = ignore_patterns {
        let canon = std::fs::canonicalize(cp).unwrap_or_else(|_| cp.to_path_buf());
        let _ = canon;
    }
    let link = is_symlink_path(cp);
    let is_dir = if follow {
        std::fs::metadata(cp).map(|m| m.is_dir()).unwrap_or(false)
    } else {
        std::fs::symlink_metadata(cp).map(|m| m.is_dir()).unwrap_or(false)
    };
    if let Some(md) = r.opts.maxdepth {
        if depth as u32 + 1 > md { return Ok(false); }
    }
    let min_ok = match r.opts.mindepth { Some(m) => depth as u32 + 1 >= m, None => true };
    if min_ok {
        let e = mk_entry(cp, name, depth as u32 + 1, ri, root_as_given, follow);
        out.push(e.clone());
        if r.opts.archives && e.is_file && is_zip_archive_name(&e.name) {
            emit_zip(out, &e, ri, root_as_given, depth as u32 + 1);
        }
    }
    Ok(is_dir)
}

