new = '''/// Parse a date in the "human readable" style (chrono-english compatible subset)
pub fn parse_human(s: &str) -> Option<ParsedDate> {
    let s = s.trim();
    if s.is_empty() { return None; }
    let lc = s.to_lowercase();
    let now = DateTime::from_epoch(now_epoch());
    // relative plain: -N / +N
    if let Some(num) = lc.strip_prefix('-') {
        if let Ok(n) = num.trim().parse::<i64>() {
            if !num.trim().is_empty() && num.trim().chars().all(|c| c.is_ascii_digit()) {
                let e = now_epoch() - n * 86400;
                return Some(ParsedDate { dt: DateTime::from_epoch(e), precision: 0 });
            }
        }
        return None;
    }
    if let Some(num) = lc.strip_prefix('+') {
        if let Ok(n) = num.trim().parse::<i64>() {
            if !num.trim().is_empty() && num.trim().chars().all(|c| c.is_ascii_digit()) {
                let e = now_epoch() + n * 86400;
                return Some(ParsedDate { dt: DateTime::from_epoch(e), precision: 0 });
            }
        }
        return None;
    }
    let toks: Vec<&str> = s.split_whitespace().collect();
    let mut dt = now;
    let mut precision = 1u32;
    let mut idx = 0usize;
    let mut have_date = false;
    // "today" / "yesterday" / "tomorrow"
    if idx < toks.len() {
        let t = toks[idx].to_lowercase();
        if t == "today" { have_date = true; idx += 1; }
        else if t == "yesterday" { dt = DateTime::from_epoch(now_epoch() - 86400); have_date = true; idx += 1; }
        else if t == "tomorrow" { dt = DateTime::from_epoch(now_epoch() + 86400); have_date = true; idx += 1; }
    }
    let mut rel: Option<i64> = None;
    let mut rel_unit: Option<i64> = None;
    let mut ago = false;
    let mut year_seen: Option<i64> = None;
    while idx < toks.len() {
        let t = toks[idx];
        let tl = t.to_lowercase();
        if tl == "ago" { ago = true; idx += 1; continue; }
        if rel_unit.is_some() { break; }
        if let Ok(n) = tl.parse::<i64>() {
            if idx + 1 < toks.len() {
                if let Some(u) = unit_seconds(toks[idx + 1]) {
                    rel = Some(n); rel_unit = Some(u); idx += 2; continue;
                }
            }
            // day number
            if n >= 1 && n <= 31 && !have_date {
                dt.day = n as u32;
                have_date = true;
                idx += 1;
                continue;
            }
            if n > 31 {
                year_seen = Some(n);
                idx += 1;
                continue;
            }
            return None;
        }
        if unit_seconds(&tl).is_some() { break; }
        if let Some(wd) = day_from_name(&tl) {
            dt = weekday_apply(&dt, wd, true, false);
            have_date = true;
            idx += 1;
            continue;
        }
        if tl == "last" || tl == "next" {
            if idx + 1 < toks.len() {
                if let Some(wd) = day_from_name(&toks[idx + 1].to_lowercase()) {
                    dt = weekday_apply(&dt, wd, tl == "next", false);
                    have_date = true;
                    idx += 2;
                    continue;
                }
            }
            return None;
        }
        if let Some(mo) = month_from_abbr(&tl) {
            dt.month = mo;
            have_date = true;
            idx += 1;
            continue;
        }
        return None;
    }
    if rel.is_some() {
        let mut n = rel.unwrap() * rel_unit.unwrap();
        if ago { n = -n; }
        dt = DateTime::from_epoch(now_epoch() + n);
        precision = 0;
    }
    if let Some(y) = year_seen { dt.year = y; }
    // optional time part
    if idx < toks.len() {
        let tl = toks[idx].to_lowercase();
        let mut parsed_time = false;
        let mut rest = tl.clone();
        let mut ampm = None;
        if rest.ends_with("am") { ampm = Some(false); rest = rest[..rest.len() - 2].to_string(); }
        else if rest.ends_with("pm") { ampm = Some(true); rest = rest[..rest.len() - 2].to_string(); }
        if !rest.is_empty() && rest.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false) {
            let parts: Vec<&str> = rest.split(':').collect();
            if parts.len() <= 3 && !parts[0].is_empty() {
                let mut h: i64 = match parts[0].parse() { Ok(v) => v, Err(_) => return None };
                let mut m: i64 = 0;
                let mut sec: i64 = 0;
                if parts.len() > 1 { m = match parts[1].parse() { Ok(v) => v, Err(_) => return None }; }
                if parts.len() > 2 { sec = match parts[2].parse() { Ok(v) => v, Err(_) => return None }; }
                if let Some(p) = ampm {
                    if h < 12 { h += 12; }
                    if p == false && h == 12 { h = 0; }
                }
                if (0..=23).contains(&h) && (0..=59).contains(&m) && (0..=59).contains(&sec) {
                    dt.hour = h as u32; dt.min = m as u32; dt.sec = sec as u32;
                    precision = 0;
                    parsed_time = true;
                }
            }
        }
        if !parsed_time { return None; }
        idx += 1;
    }
    if idx != toks.len() { return None; }
    if !dt.is_valid() { return None; }
    Some(ParsedDate { dt, precision })
}

